import React, { useState, useEffect, useMemo } from 'react';
import { User, Car, Invoice } from '../types';
import { ShieldAlert, Search, Lock, Zap, AlertTriangle, RefreshCw, Key, UserMinus, Eye, EyeOff, UserPlus, Info, BarChart3, Activity, TrendingUp, PieChart, Users, ArrowUpRight, Clock, MapPin, Globe } from 'lucide-react';

interface AdminDashboardScreenProps {
  currentUser: User;
  allUsers: User[];
  allCars: Car[];
  allInvoices: Invoice[];
  onLogout: () => void;
  onUpdateUser: (user: User) => void;
  onDeleteUser: (userId: string) => void;
  onRefresh: () => void;
}

export const AdminDashboardScreen: React.FC<AdminDashboardScreenProps> = ({ 
  currentUser, allUsers, allCars, allInvoices, onLogout, onUpdateUser, onDeleteUser, onRefresh
}) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'intelligence' | 'users' | 'alerts'>('overview');
  const [searchTerm, setSearchTerm] = useState('');
  const [isRefreshing, setIsRefreshing] = useState(false);

  // --- LOGIQUE DE STATISTIQUES NATIONALES ---
  const stats = useMemo(() => {
    const totalUsers = allUsers.length;
    const totalCars = allCars.length;
    const totalRevenue = allInvoices.reduce((acc, inv) => acc + inv.price, 0);
    const premiumUsers = allUsers.filter(u => u.isPremium).length;

    // Répartition carburant
    const fuelDist = allCars.reduce((acc: any, car) => {
      acc[car.fuelType] = (acc[car.fuelType] || 0) + 1;
      return acc;
    }, {});

    // État de santé du parc
    const healthDist = allCars.reduce((acc: any, car) => {
      const state = car.initialState.engine === 'bad' || car.initialState.tires === 'bad' ? 'critical' : 'good';
      acc[state] = (acc[state] || 0) + 1;
      return acc;
    }, { good: 0, critical: 0 });

    return { totalUsers, totalCars, totalRevenue, premiumUsers, fuelDist, healthDist };
  }, [allUsers, allCars, allInvoices]);

  const handleManualRefresh = () => {
    setIsRefreshing(true);
    onRefresh();
    setTimeout(() => setIsRefreshing(false), 800);
  };

  const handleResetPassword = (user: User) => {
    const newPass = Math.random().toString(36).slice(-6).toUpperCase();
    if (confirm(`Générer un mot de passe temporaire pour ${user.name} ?\nNouveau MDP : ${newPass}`)) {
      onUpdateUser({ ...user, password: newPass, passwordResetRequested: false });
      alert(`Mot de passe mis à jour : ${newPass}`);
    }
  };

  const renderKPI = (label: string, value: string | number, icon: React.ReactNode, color: string, subValue?: string) => (
    <div className="bg-nsp-card border border-nsp-border p-5 rounded-2xl relative overflow-hidden group shadow-xl">
      <div className={`absolute top-0 right-0 p-4 opacity-10 group-hover:scale-110 transition-transform ${color}`}>{icon}</div>
      <span className="text-gray-500 text-[9px] uppercase font-black tracking-widest block mb-1">{label}</span>
      <div className="text-2xl font-black text-white flex items-baseline gap-2">
        {value}
        {subValue && <span className="text-[10px] text-green-500 flex items-center"><ArrowUpRight size={10}/> {subValue}</span>}
      </div>
    </div>
  );

  const renderIntelligence = () => (
    <div className="space-y-6 animate-fade-in">
      {/* KPIs Grid */}
      <div className="grid grid-cols-2 gap-4">
        {renderKPI("CA National", `${stats.totalRevenue.toLocaleString()}€`, <TrendingUp size={40}/>, "text-green-500", "+18%")}
        {renderKPI("Inscrits France", stats.totalUsers, <Users size={40}/>, "text-blue-500", "Live")}
        {renderKPI("Parc Automobile", stats.totalCars, <Activity size={40}/>, "text-yellow-500")}
        {renderKPI("Abonnés Premium", stats.premiumUsers, <Zap size={40}/>, "text-purple-500")}
      </div>

      {/* Fuel Distribution */}
      <div className="bg-nsp-card border border-nsp-border rounded-3xl p-6 shadow-2xl">
        <h3 className="text-white font-black text-xs uppercase tracking-widest mb-4 flex items-center gap-2">
          <PieChart size={16} className="text-blue-500" /> Mix Énergétique National
        </h3>
        <div className="space-y-3">
          {Object.entries(stats.fuelDist).map(([fuel, count]: any) => (
            <div key={fuel} className="space-y-1">
              <div className="flex justify-between text-[10px] font-bold">
                <span className="text-gray-400 uppercase">{fuel}</span>
                <span className="text-white">{count} ({((count / (stats.totalCars || 1)) * 100).toFixed(0)}%)</span>
              </div>
              <div className="h-1.5 w-full bg-nsp-input rounded-full overflow-hidden">
                <div 
                  className={`h-full rounded-full ${fuel === 'electrique' ? 'bg-green-500' : fuel === 'hybride' ? 'bg-blue-500' : 'bg-nsp-primary'}`} 
                  style={{ width: `${(count / (stats.totalCars || 1)) * 100}%` }}
                ></div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );

  const renderOverview = () => (
    <div className="space-y-6 animate-fade-in">
      <div className="bg-gradient-to-r from-blue-600/20 to-transparent border border-blue-500/30 p-4 rounded-2xl flex items-start gap-3">
        <Globe size={20} className="text-blue-400 shrink-0 mt-0.5" />
        <div>
          <p className="text-white font-bold text-xs uppercase tracking-tight">Réseau National AUTOBOOK</p>
          <p className="text-[10px] text-gray-400 leading-tight mt-1">
            Vous visualisez l'ensemble des automobilistes inscrits sur la plateforme. La gestion des comptes est centralisée pour garantir la sécurité des données.
          </p>
        </div>
      </div>

      <div className="grid grid-cols-2 gap-4">
        <div className="bg-nsp-input p-5 rounded-2xl border border-nsp-border shadow-lg">
          <span className="text-gray-500 text-[10px] uppercase font-black tracking-widest block mb-1">Utilisateurs Totaux</span>
          <div className="text-3xl font-black text-white">{allUsers.length}</div>
          <p className="text-[9px] text-nsp-sub mt-1">Particuliers & Professionnels</p>
        </div>
        <div className="bg-nsp-input p-5 rounded-2xl border border-nsp-border relative overflow-hidden shadow-lg">
          <span className="text-gray-500 text-[10px] uppercase font-black tracking-widest block mb-1">Sécurité</span>
          <div className={`text-3xl font-black ${allUsers.filter(u => u.passwordResetRequested).length > 0 ? 'text-red-500' : 'text-nsp-success'}`}>
            {allUsers.filter(u => u.passwordResetRequested).length || 'OK'}
          </div>
          <p className="text-[9px] text-nsp-sub mt-1">Alertes accès comptes</p>
        </div>
      </div>

      {/* Flux d'Activité Récent */}
      <div className="bg-nsp-card border border-nsp-border rounded-3xl p-5 shadow-2xl">
        <h3 className="text-white font-black text-xs uppercase tracking-widest mb-4 flex items-center gap-2">
          <Activity size={16} className="text-nsp-success" /> Dernières Inscriptions France
        </h3>
        <div className="space-y-4">
          {allUsers.slice(-5).reverse().map((u, i) => (
            <div key={u.id} className="flex gap-3 items-center text-xs border-b border-white/5 pb-3 last:border-0">
              <div className="w-8 h-8 rounded-full bg-nsp-input border border-nsp-border flex items-center justify-center text-nsp-primary font-black uppercase">{u.name.charAt(0)}</div>
              <div className="flex-1">
                <p className="text-white font-bold">{u.name} <span className="text-gray-500 font-normal">inscrit via {u.clientType === 'new' ? 'App Mobile' : 'Garage'}</span></p>
                <p className="text-[9px] text-gray-600 flex items-center gap-1"><MapPin size={10}/> France (Utilisateur Global)</p>
              </div>
              {u.isPremium && <Zap size={14} className="text-yellow-500" />}
            </div>
          ))}
        </div>
      </div>
    </div>
  );

  const filteredUsers = allUsers.filter(u => 
    u.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
    u.email.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="min-h-screen bg-[#070707] flex flex-col">
      {/* Header Admin National */}
      <div className="bg-red-950/40 border-b border-red-900/30 p-6 flex justify-between items-center pt-safe-top backdrop-blur-md sticky top-0 z-50">
        <div className="flex items-center gap-4">
           <div className="bg-red-600 p-2.5 rounded-xl shadow-lg shadow-red-900/40"><ShieldAlert className="text-white" size={24} /></div>
           <div>
             <h1 className="text-xl font-black text-white tracking-tighter uppercase leading-none">Console<span className="text-red-600">Global</span></h1>
             <p className="text-red-500 text-[9px] uppercase font-black tracking-[0.3em] mt-1">Plateforme Nationale AUTOBOOK</p>
           </div>
        </div>
        <button onClick={onLogout} className="text-white bg-red-600 px-5 py-2.5 rounded-xl font-black text-[10px] tracking-widest hover:bg-red-500 transition-colors shadow-lg">LOGOUT</button>
      </div>

      {/* Navigation Tabs */}
      <div className="flex border-b border-nsp-border px-4 bg-nsp-card/20 overflow-x-auto no-scrollbar backdrop-blur-sm sticky top-[84px] z-40">
        {[
          { id: 'overview', label: 'Global', icon: <BarChart3 size={14}/> },
          { id: 'intelligence', label: 'Marché', icon: <Zap size={14}/> },
          { id: 'users', label: 'Utilisateurs France', icon: <Users size={14}/> },
          { id: 'alerts', label: 'Sécurité', icon: <AlertTriangle size={14}/> }
        ].map(tab => (
          <button 
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)} 
            className={`py-4 px-6 text-[10px] font-black border-b-2 transition-all uppercase tracking-[0.2em] flex items-center gap-2 whitespace-nowrap ${activeTab === tab.id ? 'border-nsp-primary text-white' : 'border-transparent text-gray-600'}`}
          >
            {tab.icon} {tab.label}
          </button>
        ))}
      </div>

      {/* Main Content */}
      <div className="flex-1 p-6 overflow-y-auto max-w-4xl mx-auto w-full pb-20">
         {activeTab === 'overview' && renderOverview()}
         {activeTab === 'intelligence' && renderIntelligence()}
         {activeTab === 'users' && (
           <div className="space-y-4 animate-fade-in">
             <div className="flex gap-2 mb-4">
                <div className="bg-nsp-input p-3 rounded-2xl flex items-center gap-3 border border-nsp-border flex-1 shadow-lg">
                    <Search size={20} className="text-gray-500" />
                    <input 
                        type="text" 
                        placeholder="Chercher par nom, email..." 
                        className="bg-transparent text-white outline-none flex-1 text-sm font-bold"
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                    />
                </div>
                <button onClick={handleManualRefresh} className={`bg-nsp-card border border-nsp-border p-3 rounded-2xl shadow-lg ${isRefreshing ? 'text-nsp-primary animate-spin' : 'text-white'}`}>
                  <RefreshCw size={20} />
                </button>
             </div>

             <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
               {filteredUsers.map(u => (
                 <div key={u.id} className="bg-nsp-card p-5 rounded-2xl border border-nsp-border hover:border-nsp-primary/50 transition-all group shadow-lg">
                   <div className="flex justify-between items-start">
                      <div className="flex items-center gap-3">
                        <div className="w-12 h-12 bg-nsp-input rounded-xl flex items-center justify-center font-black text-xl text-nsp-primary shadow-inner">{u.name.charAt(0)}</div>
                        <div>
                          <h4 className="text-white font-bold text-sm uppercase flex items-center gap-2">
                            {u.name}
                            {u.isPremium && <Zap size={12} className="text-yellow-500 fill-yellow-500" />}
                          </h4>
                          <p className="text-[10px] text-nsp-sub font-mono truncate max-w-[150px]">{u.email}</p>
                          <p className="text-[8px] text-gray-600 uppercase tracking-widest mt-1">ID: {u.id.slice(-8)}</p>
                        </div>
                      </div>
                      <div className="flex flex-col gap-2">
                         <button onClick={() => handleResetPassword(u)} className="p-2 bg-nsp-input rounded-lg text-gray-500 hover:text-white transition-colors" title="Changer MDP"><Key size={14}/></button>
                         {u.role !== 'admin' && (
                            <button onClick={() => confirm(`Supprimer définitivement l'utilisateur ${u.name}?`) && onDeleteUser(u.id)} className="p-2 bg-nsp-input rounded-lg text-gray-600 hover:text-red-500 transition-colors" title="Supprimer"><UserMinus size={14}/></button>
                         )}
                      </div>
                   </div>
                   <div className="mt-4 pt-4 border-t border-white/5 flex justify-between items-center text-[10px]">
                      <span className={`px-2 py-0.5 rounded uppercase font-black tracking-widest ${u.clientType === 'new' ? 'bg-blue-900/20 text-blue-400' : 'bg-green-900/20 text-green-400'}`}>
                        {u.clientType === 'new' ? 'Indépendant' : 'Client Garage'}
                      </span>
                      <span className="text-gray-500">
                        {allCars.filter(c => c.ownerId === u.id).length} Véhicule(s)
                      </span>
                   </div>
                 </div>
               ))}
             </div>

             {filteredUsers.length === 0 && (
               <div className="text-center py-20">
                 <Users size={48} className="text-gray-800 mx-auto mb-4" />
                 <p className="text-gray-500 font-bold">Aucun utilisateur trouvé sur le territoire national.</p>
               </div>
             )}
           </div>
         )}
         {activeTab === 'alerts' && (
           <div className="bg-red-950/10 border border-red-500/20 p-6 rounded-3xl animate-fade-in shadow-2xl">
              <h3 className="text-white font-black text-xs uppercase mb-4 flex items-center gap-2"><AlertTriangle size={16} className="text-red-500" /> Demandes de Récupération ({allUsers.filter(u => u.passwordResetRequested).length})</h3>
              {allUsers.filter(u => u.passwordResetRequested).length === 0 ? (
                <div className="text-center py-10">
                   <ShieldAlert size={32} className="text-nsp-success mx-auto mb-2 opacity-50" />
                   <p className="text-gray-500 text-xs italic">Aucune alerte de sécurité en attente sur le réseau.</p>
                </div>
              ) : (
                allUsers.filter(u => u.passwordResetRequested).map(u => (
                  <div key={u.id} className="bg-nsp-card p-4 rounded-xl border border-red-500/30 flex justify-between items-center mb-3 shadow-md">
                    <div>
                      <span className="text-white font-bold text-sm block">{u.name}</span>
                      <span className="text-[10px] text-red-400 font-mono">{u.email}</span>
                    </div>
                    <button onClick={() => handleResetPassword(u)} className="bg-red-600 hover:bg-red-500 text-white px-4 py-2 rounded-lg text-[10px] font-black uppercase transition-colors">Débloquer</button>
                  </div>
                ))
              )}
           </div>
         )}
      </div>
    </div>
  );
};

