import { User, Car, Invoice } from '../types';

/**
 * AUTOBOOK CLOUD CONNECTOR (Firebase Ready)
 * Ce service gère la communication entre le téléphone du client et votre console admin.
 */

// Simulation de l'API Cloud pour la démo Vercel
// Dans une version finale, on utilise Firebase Firestore ici.
class CloudConnector {
  private static instance: CloudConnector;

  private constructor() {}

  public static getInstance(): CloudConnector {
    if (!CloudConnector.instance) {
      CloudConnector.instance = new CloudConnector();
    }
    return CloudConnector.instance;
  }

  // Enregistre un nouvel utilisateur dans la base de données centrale Europe
  async syncNewUser(user: User): Promise<void> {
    console.log(`[Cloud] Envoi de l'inscription de ${user.name} au serveur central...`);

    // On persiste en local pour le téléphone de l'utilisateur
    const localUsers = JSON.parse(localStorage.getItem('AUTOBOOK_DB_USERS_V2') || '[]');
    if (!localUsers.some((u: any) => u.email === user.email)) {
        localUsers.push(user);
        localStorage.setItem('AUTOBOOK_DB_USERS_V2', JSON.stringify(localUsers));
    }

    // SIMULATION CLOUD: Pour que l'admin voie les données, nous utilisons une clé partagée
    // Dans un vrai backend, cela va dans une base MongoDB/Firestore
    const cloudBuffer = JSON.parse(localStorage.getItem('AUTOBOOK_CLOUD_BUFFER') || '[]');
    cloudBuffer.push({ ...user, timestamp: Date.now() });
    localStorage.setItem('AUTOBOOK_CLOUD_BUFFER', JSON.stringify(cloudBuffer));
  }

  // Récupère toutes les inscriptions européennes (Pour l'Admin)
  async fetchAllRemoteUsers(): Promise<User[]> {
    // Dans la réalité, cet appel interroge le serveur HTTPS://API.AUTOBOOK.EU
    const local = JSON.parse(localStorage.getItem('AUTOBOOK_DB_USERS_V2') || '[]');
    const buffer = JSON.parse(localStorage.getItem('AUTOBOOK_CLOUD_BUFFER') || '[]');

    // Fusion et dédoublonnage
    const all = [...local, ...buffer];
    const unique = Array.from(new Map(all.map(u => [u.id, u])).values());

    return unique as User[];
  }
}

export const cloud = CloudConnector.getInstance();

