  storageBucket: "votre-projet.appspot.com",
  messagingSenderId: "votre-id",
  appId: "votre-app-id"
};

let db: any = null;
let isRealFirebase = false;

try {
    // On ne tente l'initialisation que si l'utilisateur a rempli ses clés
    if (firebaseConfig.apiKey !== "VOTRE_API_KEY" && firebaseConfig.apiKey !== "") {
        const app = initializeApp(firebaseConfig);
        db = getFirestore(app);
        isRealFirebase = true;
        console.log("🚀 Firebase Cloud connecté avec succès !");
    } else {
        console.warn("⚠️ Mode Simulation : Clés Firebase manquantes dans cloudService.ts");
    }
} catch (e) {
    console.error("❌ Erreur d'initialisation Firebase:", e);
}

class CloudConnector {
  private static instance: CloudConnector;
  private constructor() {}

  public static getInstance(): CloudConnector {
    if (!CloudConnector.instance) {
      CloudConnector.instance = new CloudConnector();
    }
    return CloudConnector.instance;
  }

  // Indique si on est en mode réel ou démo
  public isConnected(): boolean {
    return isRealFirebase;
  }

  // SYNC : Envoie l'utilisateur vers le serveur central (Paris/Toulouse/etc)
  async syncUser(user: User): Promise<void> {
    if (!isRealFirebase) {
        // Mode Simulation : Stockage local partagé pour la démo
        const buffer = JSON.parse(localStorage.getItem('AUTOBOOK_CLOUD_BUFFER') || '[]');
        if (!buffer.some((u: any) => u.id === user.id)) {
            buffer.push({ ...user, timestamp: Date.now(), location: "Simulation" });
            localStorage.setItem('AUTOBOOK_CLOUD_BUFFER', JSON.stringify(buffer));
        }
        return;
    }

    try {
        const userRef = doc(db, "users", user.id);
        await setDoc(userRef, {
            id: user.id,
            name: user.name,
            email: user.email,
            clientType: user.clientType || 'new',
            role: user.role,
            lastSync: Timestamp.now(),
            // On peut ajouter ici des métadonnées comme la ville si détectée
            source: window.location.hostname
        }, { merge: true });
    } catch (e) {
        console.error("Erreur Sync Cloud:", e);
    }
  }

  // FETCH : L'ADMIN récupère la liste globale
  async fetchAllUsers(): Promise<User[]> {
    if (!isRealFirebase) {
        const local = JSON.parse(localStorage.getItem('AUTOBOOK_DB_USERS_V2') || '[]');
        const buffer = JSON.parse(localStorage.getItem('AUTOBOOK_CLOUD_BUFFER') || '[]');
        const all = [...local, ...buffer];
        return Array.from(new Map(all.map(u => [u.id, u])).values()) as User[];
    }

    try {
        const querySnapshot = await getDocs(collection(db, "users"));
        const users: User[] = [];
        querySnapshot.forEach((doc) => {
            users.push(doc.data() as User);
        });
        return users;
    } catch (e) {
        console.error("Erreur Fetch Cloud:", e);
        return [];
    }
  }

  // LISTEN : Ecouteur en temps réel pour l'Admin
  listenToAllUsers(callback: (users: User[]) => void) {
    if (!isRealFirebase) return null;

    return onSnapshot(collection(db, "users"), (snapshot) => {
        const users: User[] = [];
        snapshot.forEach((doc) => {
            users.push(doc.data() as User);
        });
        callback(users);
    });
  }
}

