  BarChart3, Activity, TrendingUp, Users, QrCode, Printer, 
  Share2, Globe, CheckCircle2, UserCheck, Car as CarIcon, 
  FileText, Calendar, ChevronRight, X, ArrowLeft, Wifi, Server,
  Radio, MapPin, Database, ExternalLink, AlertCircle, RefreshCcw
} from 'lucide-react';

interface AdminDashboardScreenProps {
  currentUser: User;
  allUsers: User[];
  allCars: Car[];
  allInvoices: Invoice[];
  onLogout: () => void;
  onUpdateUser: (user: User) => void;
  onDeleteUser: (userId: string) => void;
  onRefresh: () => void;
}

export const AdminDashboardScreen: React.FC<AdminDashboardScreenProps> = ({ 
  currentUser, allUsers, allCars, allInvoices, onLogout, onUpdateUser, onDeleteUser, onRefresh
}) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'diffusion' | 'users' | 'setup'>('overview');
  const [searchTerm, setSearchTerm] = useState('');
  const [cloudStatus, setCloudStatus] = useState<'online' | 'syncing' | 'warning' | 'error'>('online');
  const [isRetrying, setIsRetrying] = useState(false);

  const isCloudActive = cloud.isConnected();
  const isApiDisabled = cloud.isApiDisabled();

  useEffect(() => {
    if (isApiDisabled) {
      setCloudStatus('error');
      return;
    }
    if (!isCloudActive) {
      setCloudStatus('warning');
      return;
    }

    const unsubscribe = cloud.listenToAllUsers((users) => {
      setCloudStatus('syncing');
      onRefresh();
      setTimeout(() => setCloudStatus('online'), 1000);
    });
    return () => { if(unsubscribe) unsubscribe(); };
  }, [onRefresh, isCloudActive, isApiDisabled]);

  const handleRetryCloud = () => {
    setIsRetrying(true);
    cloud.resetActivationFlag();
    onRefresh();
    setTimeout(() => setIsRetrying(false), 2000);
  };

  const stats = useMemo(() => {
    const realUsers = allUsers.filter(u => u.role !== 'admin');
    return { 
      totalUsers: realUsers.length, 
      totalCars: allCars.filter(c => realUsers.some(u => u.id === c.ownerId)).length,
      totalRevenue: allInvoices.reduce((acc, inv) => acc + inv.price, 0)
    };
  }, [allUsers, allCars, allInvoices]);

  const renderKPI = (label: string, value: string | number, icon: React.ReactNode, color: string) => (
    <div className="bg-nsp-card border border-nsp-border p-5 rounded-2xl relative overflow-hidden shadow-xl">
      <div className={`absolute top-0 right-0 p-4 opacity-10 ${color}`}>{icon}</div>
      <span className="text-gray-500 text-[9px] uppercase font-black tracking-widest block mb-1">{label}</span>
      <div className="text-2xl font-black text-white">{value}</div>
    </div>
  );

  return (
    <div className="min-h-screen bg-[#070707] flex flex-col font-sans">
      <div className="bg-red-950/40 border-b border-red-900/30 p-6 flex justify-between items-center pt-safe-top backdrop-blur-md sticky top-0 z-50">
        <div className="flex items-center gap-4">
          <div className="bg-red-600 p-2.5 rounded-xl shadow-[0_0_20px_rgba(230,57,70,0.3)]"><ShieldAlert className="text-white" size={24} /></div>
          <div>
            <h1 className="text-xl font-black text-white tracking-tighter uppercase leading-none">Console<span className="text-red-600">Global</span></h1>
            <div className="flex items-center gap-2 mt-1">
              <div className={`w-2 h-2 rounded-full ${cloudStatus === 'online' ? 'bg-green-500 animate-pulse' : cloudStatus === 'error' ? 'bg-red-500 animate-bounce' : cloudStatus === 'warning' ? 'bg-yellow-500' : 'bg-blue-500 animate-spin'}`}></div>
              <p className={`${cloudStatus === 'error' ? 'text-red-500' : cloudStatus === 'warning' ? 'text-yellow-500' : 'text-green-500'} text-[8px] uppercase font-black tracking-widest`}>
                {isApiDisabled ? 'ERREUR : API CLOUD DÉSACTIVÉE' : isCloudActive ? 'Réseau AutoPulse Connecté' : 'Mode Local Simulation'}
              </p>
            </div>
          </div>
        </div>
        <button onClick={onLogout} className="text-white bg-red-600 px-4 py-2 rounded-xl font-black text-[10px] uppercase shadow-lg">Logout</button>
      </div>

      <div className="flex border-b border-nsp-border px-4 bg-nsp-card/20 overflow-x-auto no-scrollbar backdrop-blur-sm sticky top-[84px] z-40">
        {[
          { id: 'overview', label: 'Surveillance', icon: <BarChart3 size={14}/> },
          { id: 'users', label: 'Répertoire Central', icon: <Users size={14}/> },
          { id: 'diffusion', label: 'QR Recrutement', icon: <QrCode size={14}/> },
          { id: 'setup', label: 'Configuration', icon: <Database size={14}/> }
        ].map(tab => (
          <button 
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)} 
            className={`py-4 px-6 text-[10px] font-black border-b-2 transition-all uppercase tracking-widest flex items-center gap-2 whitespace-nowrap ${activeTab === tab.id ? 'border-nsp-primary text-white' : 'border-transparent text-gray-600'}`}
          >
            {tab.icon} {tab.label}
          </button>
        ))}
      </div>

      <div className="flex-1 p-6 max-w-4xl mx-auto w-full pb-24">
         {activeTab === 'overview' && (
           <div className="space-y-6 animate-fade-in">
              {isApiDisabled && (
                <div onClick={() => setActiveTab('setup')} className="bg-red-600/20 border border-red-600/50 p-5 rounded-2xl flex items-center gap-4 cursor-pointer hover:bg-red-600/30 transition-all animate-pulse shadow-[0_0_15px_rgba(220,38,38,0.2)]">
                  <AlertCircle className="text-red-500 shrink-0" size={28} />
                  <div>
                    <p className="text-red-500 text-xs font-black uppercase">Action Requise : API Cloud Désactivée</p>
                    <p className="text-gray-400 text-[10px] mt-1">Firestore n'est pas activé sur votre projet Google. Cliquez ici pour l'activer en 2 clics.</p>
                  </div>
                  <ChevronRight size={20} className="text-red-500 ml-auto" />
                </div>
              )}

              <div className="grid grid-cols-2 gap-4">
                {renderKPI("Total Clients", stats.totalUsers, <Globe size={24}/>, "text-blue-500")}
                {renderKPI("Parc Automobile", stats.totalCars, <CarIcon size={24}/>, "text-green-500")}
              </div>

              <div className="bg-nsp-card border border-nsp-border rounded-3xl p-6">
                <h3 className="text-white font-black text-[10px] uppercase tracking-widest mb-4 flex items-center gap-2">
                  <Radio size={14} className="text-red-500 animate-pulse" /> Inscriptions Nationales en Direct
                </h3>
                <div className="space-y-4">
                  {allUsers.filter(u => u.role !== 'admin').length === 0 ? (
                    <div className="text-center py-12 border border-dashed border-gray-800 rounded-2xl">
                       <Database className="mx-auto text-gray-700 mb-2" size={32} />
                       <p className="text-gray-600 text-[10px] uppercase font-black">En attente de nouveaux clients...</p>
                    </div>
                  ) : (
                    allUsers.filter(u => u.role !== 'admin').slice(-10).reverse().map(u => (
                      <div key={u.id} className="flex items-center gap-3 border-b border-white/5 pb-3 last:border-0 hover:bg-white/5 p-2 rounded-xl transition-all">
                         <div className="w-10 h-10 rounded-full bg-nsp-input flex items-center justify-center text-xs font-black text-nsp-primary border border-white/10">{u.name.charAt(0)}</div>
                         <div className="flex-1">
                            <div className="flex items-center gap-2">
                               <p className="text-xs text-white font-bold">{u.name}</p>
                            </div>
                            <p className="text-[9px] text-gray-500 font-mono">{u.email}</p>
                         </div>
                         <div className="text-right">
                           <div className="flex flex-col items-end gap-1">
                             <span className={`text-[8px] font-black px-2 py-0.5 rounded-full ${isCloudActive ? 'bg-green-500/10 text-green-500' : 'bg-red-500/10 text-red-500'}`}>
                                {isCloudActive ? 'SYNCHRONISÉ' : 'OFFLINE'}
                             </span>
                           </div>
                         </div>
                      </div>
                    ))
                  )}
                </div>
              </div>
           </div>
         )}

         {activeTab === 'setup' && (
           <div className="space-y-6 animate-fade-in">
              <div className="bg-nsp-card border border-nsp-border p-8 rounded-3xl text-center shadow-2xl">
                 <div className={`w-16 h-16 rounded-full flex items-center justify-center mx-auto mb-4 ${isApiDisabled ? 'bg-red-600/10' : 'bg-nsp-primary/10'}`}>
                    <Database size={32} className={isApiDisabled ? 'text-red-500' : 'text-nsp-primary'} />
                 </div>
                 <h2 className="text-xl font-bold text-white mb-2">Statut Cloud : {isApiDisabled ? 'Action Requise' : 'Connecté'}</h2>

                 {isApiDisabled ? (
                   <div className="space-y-6">
                      <div className="bg-red-900/10 border border-red-900/30 p-4 rounded-xl text-left">
                        <p className="text-red-500 font-black text-xs uppercase mb-2">🔴 Erreur Détectée</p>
                        <p className="text-gray-300 text-xs leading-relaxed">
                          L'application ne peut pas enregistrer les clients car l'API **Cloud Firestore** est désactivée dans votre projet Google Cloud `autobook-nsp`.
                        </p>
                      </div>

                      <div className="text-left bg-black p-4 rounded-xl space-y-4 border border-nsp-border">
                        <p className="text-nsp-primary font-black text-xs uppercase">SOLUTION RAPIDE :</p>
                        <ol className="text-xs text-gray-300 space-y-3 list-decimal list-inside">
                          <li>Cliquez sur le bouton bleu ci-dessous.</li>
                          <li>Cliquez sur <span className="text-white font-bold">"ACTIVER"</span> (Enable) sur la page Google Cloud.</li>
                          <li>Revenez ici et cliquez sur "Vérifier à nouveau".</li>
                        </ol>
                      </div>

                      <div className="flex flex-col gap-3">
                        <a 
                          href="https://console.developers.google.com/apis/api/firestore.googleapis.com/overview?project=autobook-nsp" 
                          target="_blank" 
                          className="bg-blue-600 hover:bg-blue-500 text-white px-6 py-4 rounded-xl font-black text-xs uppercase flex items-center justify-center gap-2 shadow-[0_0_20px_rgba(37,99,235,0.3)] transition-all"
                        >
                           Activer l'API Firestore <ExternalLink size={14} />
                        </a>

                        <button 
                          onClick={handleRetryCloud}
                          disabled={isRetrying}
                          className="bg-nsp-input border border-nsp-border text-white px-6 py-3 rounded-xl font-black text-[10px] uppercase flex items-center justify-center gap-2 hover:bg-nsp-border transition-all"
                        >
                          {isRetrying ? <Loader2 className="animate-spin" size={14}/> : <RefreshCcw size={14} />} 
                          Vérifier à nouveau
                        </button>
                      </div>
                   </div>
                 ) : (
                   <div className="space-y-4">
                      <div className="bg-green-900/10 border border-green-900/30 p-4 rounded-xl">
                        <p className="text-green-500 font-black text-xs uppercase mb-1 flex items-center justify-center gap-2">
                          <CheckCircle2 size={14}/> Cloud Opérationnel
                        </p>
                        <p className="text-gray-400 text-[10px]">Toutes les inscriptions sont synchronisées en temps réel.</p>
                      </div>
                      <p className="text-gray-400 text-xs">Identifiant projet : <span className="text-white font-mono">autobook-nsp</span></p>
                   </div>
                 )}
              </div>
           </div>
         )}

         {activeTab === 'diffusion' && (
           <div className="space-y-8 animate-fade-in flex flex-col items-center py-10">
              <div className="text-center space-y-2">
                <h2 className="text-2xl font-black text-white uppercase tracking-tighter">Portail d'Aquisition</h2>
                <p className="text-nsp-sub text-xs">Imprimez et affichez ce code. Toute personne le scannant apparaîtra ici.</p>
              </div>
              <div className="bg-white p-8 rounded-[2.5rem] shadow-[0_0_50px_rgba(230,57,70,0.3)] border-[10px] border-nsp-card">
                 <img src={`https://api.qrserver.com/v1/create-qr-code/?size=400x400&data=${encodeURIComponent(window.location.origin)}&color=0-0-0`} alt="QR Code" className="w-64 h-64" />
              </div>
              <button onClick={() => window.print()} className="bg-nsp-card border border-nsp-border text-white px-8 py-4 rounded-xl font-black text-xs uppercase flex items-center gap-3 hover:bg-nsp-input transition-colors shadow-lg">
                 <Printer size={18} /> Générer l'Affiche de Comptoir
              </button>
           </div>
         )}

         {activeTab === 'users' && (
           <div className="space-y-4 animate-fade-in">
              <div className="bg-nsp-input p-4 rounded-2xl flex items-center gap-3 border border-nsp-border shadow-inner">
                <Search size={20} className="text-gray-500" />
                <input 
                   type="text" 
                   placeholder="Filtrer par Nom, Email, Ville..." 
                   className="bg-transparent text-white outline-none text-sm font-bold w-full" 
                   value={searchTerm} 
                   onChange={(e) => setSearchTerm(e.target.value)} 
                />
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {allUsers.filter(u => u.role !== 'admin').filter(u => u.name.toLowerCase().includes(searchTerm.toLowerCase()) || u.email.toLowerCase().includes(searchTerm.toLowerCase())).map(u => (
                  <div key={u.id} className="bg-nsp-card p-4 rounded-2xl border border-nsp-border flex justify-between items-center group shadow-md hover:border-nsp-primary transition-all">
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 bg-nsp-input rounded-xl flex items-center justify-center font-black text-nsp-primary shadow-lg">{u.name.charAt(0)}</div>
                      <div>
                        <p className="text-white font-bold text-sm uppercase">{u.name}</p>
                        <p className="text-[10px] text-gray-500">{u.email}</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-2">
                       {u.isPremium && <Zap size={14} className="text-yellow-500" />}
                       <button className="bg-nsp-input p-2 rounded-lg text-gray-500 hover:text-white transition-colors">
                         <ChevronRight size={18} />
                       </button>
                    </div>
                  </div>
                ))}
              </div>
           </div>
         )}
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { User, Car, Invoice } from '../types';
import { cloud } from '../services/cloudService';
import { 
  ShieldAlert, Search, Zap, AlertTriangle, RefreshCw, Key, 
  BarChart3, Activity, TrendingUp, Users, QrCode, Printer, 
  Share2, Globe, CheckCircle2, UserCheck, Car as CarIcon, 
  FileText, Calendar, ChevronRight, X, ArrowLeft, Wifi, Server,
  Radio, MapPin, Database, ExternalLink, AlertCircle, RefreshCcw,
  // Fix: Added Loader2 to imports
  Loader2
} from 'lucide-react';

interface AdminDashboardScreenProps {
  currentUser: User;
  allUsers: User[];
  allCars: Car[];
  allInvoices: Invoice[];
  onLogout: () => void;
  onUpdateUser: (user: User) => void;
  onDeleteUser: (userId: string) => void;
  onRefresh: () => void;
}

export const AdminDashboardScreen: React.FC<AdminDashboardScreenProps> = ({ 
  currentUser, allUsers, allCars, allInvoices, onLogout, onUpdateUser, onDeleteUser, onRefresh
}) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'diffusion' | 'users' | 'setup'>('overview');
  const [searchTerm, setSearchTerm] = useState('');
  const [cloudStatus, setCloudStatus] = useState<'online' | 'syncing' | 'warning' | 'error'>('online');
  const [isRetrying, setIsRetrying] = useState(false);

  const isCloudActive = cloud.isConnected();
  const isApiDisabled = cloud.isApiDisabled();

  useEffect(() => {
    if (isApiDisabled) {
      setCloudStatus('error');
      return;
    }
    if (!isCloudActive) {
      setCloudStatus('warning');
      return;
    }

    const unsubscribe = cloud.listenToAllUsers((users) => {
      setCloudStatus('syncing');
      onRefresh();
      setTimeout(() => setCloudStatus('online'), 1000);
    });
    return () => { if(unsubscribe) unsubscribe(); };
  }, [onRefresh, isCloudActive, isApiDisabled]);

  const handleRetryCloud = () => {
    setIsRetrying(true);
    cloud.resetActivationFlag();
    onRefresh();
    setTimeout(() => setIsRetrying(false), 2000);
  };

  const stats = useMemo(() => {
    const realUsers = allUsers.filter(u => u.role !== 'admin');
    return { 
      totalUsers: realUsers.length, 
      totalCars: allCars.filter(c => realUsers.some(u => u.id === c.ownerId)).length,
      totalRevenue: allInvoices.reduce((acc, inv) => acc + inv.price, 0)
    };
  }, [allUsers, allCars, allInvoices]);

  const renderKPI = (label: string, value: string | number, icon: React.ReactNode, color: string) => (
    <div className="bg-nsp-card border border-nsp-border p-5 rounded-2xl relative overflow-hidden shadow-xl">
      <div className={`absolute top-0 right-0 p-4 opacity-10 ${color}`}>{icon}</div>
      <span className="text-gray-500 text-[9px] uppercase font-black tracking-widest block mb-1">{label}</span>
      <div className="text-2xl font-black text-white">{value}</div>
    </div>
  );

  return (
    <div className="min-h-screen bg-[#070707] flex flex-col font-sans">
      <div className="bg-red-950/40 border-b border-red-900/30 p-6 flex justify-between items-center pt-safe-top backdrop-blur-md sticky top-0 z-50">
        <div className="flex items-center gap-4">
          <div className="bg-red-600 p-2.5 rounded-xl shadow-[0_0_20px_rgba(230,57,70,0.3)]"><ShieldAlert className="text-white" size={24} /></div>
          <div>
            <h1 className="text-xl font-black text-white tracking-tighter uppercase leading-none">Console<span className="text-red-600">Global</span></h1>
            <div className="flex items-center gap-2 mt-1">
              <div className={`w-2 h-2 rounded-full ${cloudStatus === 'online' ? 'bg-green-500 animate-pulse' : cloudStatus === 'error' ? 'bg-red-500 animate-bounce' : cloudStatus === 'warning' ? 'bg-yellow-500' : 'bg-blue-500 animate-spin'}`}></div>
              <p className={`${cloudStatus === 'error' ? 'text-red-500' : cloudStatus === 'warning' ? 'text-yellow-500' : 'text-green-500'} text-[8px] uppercase font-black tracking-widest`}>
