import { GoogleGenAI, Type } from "@google/genai";
import { Car, ManufacturerSpecs, TechnicalSpecs } from "../types";

export const processFile = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement('canvas');
        let width = img.width;
        let height = img.height;
        const MAX_SIZE = 1200; // Augmentation pour meilleure lecture OCR
        if (width > height) {
          if (width > MAX_SIZE) {
            height *= MAX_SIZE / width;
            width = MAX_SIZE;
          }
        } else {
          if (height > MAX_SIZE) {
            width *= MAX_SIZE / height;
            height = MAX_SIZE;
          }
        }
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.drawImage(img, 0, 0, width, height);
          resolve(canvas.toDataURL('image/jpeg', 0.8));
        } else {
          reject(new Error("Canvas context error"));
        }
      };
      img.onerror = () => reject(new Error("Image load error"));
      img.src = e.target?.result as string;
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

export const fileToGenerativePart = async (file: File): Promise<string> => {
  if (file.type.startsWith('image/')) {
    const compressedDataUrl = await processFile(file);
    return compressedDataUrl.split(',')[1];
  } else {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = reader.result as string;
        const base64Data = base64String.split(',')[1];
        resolve(base64Data);
      };
      reader.onerror = reject;
      reader.readAsDataURL(file);
    });
  }
};

const cleanJsonString = (text: string): string => {
  let clean = text.replace(/```json/g, '').replace(/```/g, '');
  return clean.trim();
};

export const analyzeInvoiceImage = async (base64Data: string, mimeType: string = 'image/jpeg') => {
  if (!process.env.API_KEY) {
    return { type: 'maintenance', title: "Saisie Manuelle", date: new Date().toISOString().split('T')[0], km: 0, price: 0 };
  }
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { mimeType: mimeType.startsWith('image') ? 'image/jpeg' : mimeType, data: base64Data } },
          { text: `ANALYSE EXPERTE NSP : Analyse cette facture ou ticket auto. 
          1. Identifie si c'est du CARBURANT (fuel) ou de l'ENTRETIEN (maintenance).
          2. Extrais les données comptables (titre, date, km, prix, volume).
          3. EXTRACTION TECHNIQUE CRITIQUE : Cherche toute référence de pièce. 
             - Pneus: dimensions (ex 205/55 R16)
             - Huile: viscosité (ex 5W30) et litres
             - Filtres: références (Huile, Air, Carburant, Habitacle)
             - Batterie: Ampérage (Ah/A)
             - Essuie-glaces: dimensions ou réf.` }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            type: { type: Type.STRING },
            title: { type: Type.STRING },
            date: { type: Type.STRING },
            km: { type: Type.NUMBER },
            price: { type: Type.NUMBER },
            volume: { type: Type.NUMBER },
            specs: { 
              type: Type.OBJECT, 
              properties: { 
                tireDimensions: { type: Type.STRING },
                oilViscosity: { type: Type.STRING },
                oilCapacity: { type: Type.STRING },
                batteryRef: { type: Type.STRING },
                oilFilterRef: { type: Type.STRING },
                airFilterRef: { type: Type.STRING },
                fuelFilterRef: { type: Type.STRING },
                cabinFilterRef: { type: Type.STRING },
                wiperRef: { type: Type.STRING }
              },
              nullable: true 
            }
          }
        }
      }
    });
    return JSON.parse(cleanJsonString(response.text || '{}'));
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    return { type: 'maintenance', title: "Erreur Analyse", date: new Date().toISOString().split('T')[0], km: 0, price: 0 };
  }
};

export const getPersonalizedMaintenance = async (car: Car, currentKm: number): Promise<ManufacturerSpecs> => {
  if (!process.env.API_KEY) {
    return { tirePressure: "2.4 bar", oilType: "5W30", checkPoints: ["Niveau Huile", "Pression Pneus", "Lave-glace"] };
  }
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `Expert Mécanique NSP. Véhicule: ${car.name}, Moteur: ${car.fuelType}, Km: ${currentKm}.
    Donne 3 points de contrôle de CONFORMITÉ et SÉCURITÉ spécifiques. Réponds en Français.`;
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            tirePressure: { type: Type.STRING },
            oilType: { type: Type.STRING },
            checkPoints: { type: Type.ARRAY, items: { type: Type.STRING } }
          }
        }
      }
    });
    return JSON.parse(cleanJsonString(response.text || '{}'));
  } catch (e) {
    return { tirePressure: "2.5 bar", oilType: "Standard", checkPoints: ["Pneus", "Huile", "Lave-glace"] };
  }
};

import React, { useState, useRef } from 'react';
import { Invoice, TechnicalSpecs } from '../types';
import { Loader2, X, Check, FileText, Upload, Fuel, Wrench, Sparkles, Camera, Zap, ShieldCheck } from 'lucide-react';
import { analyzeInvoiceImage, fileToGenerativePart, processFile } from '../services/geminiService';

interface AddInvoiceScreenProps {
  carId: string;
  onSave: (invoice: Invoice, detectedSpecs?: TechnicalSpecs) => void;
  onCancel: () => void;
}

export const AddInvoiceScreen: React.FC<AddInvoiceScreenProps> = ({ carId, onSave, onCancel }) => {
  const [activeTab, setActiveTab] = useState<'maintenance' | 'fuel'>('maintenance');
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  const [imagePreview, setImagePreview] = useState<string | null>(null);
  const [finalBase64, setFinalBase64] = useState<string | null>(null);

  const [fileType, setFileType] = useState<string>(''); 
  const [fileName, setFileName] = useState<string>('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [detectedSpecs, setDetectedSpecs] = useState<TechnicalSpecs | undefined>(undefined);

  const [formData, setFormData] = useState({
    title: '',
    date: new Date().toISOString().split('T')[0],
    km: '',
    price: '',
    volume: ''
  });

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const isPdf = file.type === 'application/pdf';
      setFileType(isPdf ? 'pdf' : 'image');
      setFileName(file.name);
      setIsAnalyzing(true);
      setDetectedSpecs(undefined);

      try {
        let previewUrl: string;
        let base64Data: string;

        if (isPdf) {
          previewUrl = URL.createObjectURL(file);
          const rawBase64 = await fileToGenerativePart(file);
          base64Data = rawBase64;
          setFinalBase64(`data:application/pdf;base64,${rawBase64}`);
        } else {
          const compressedUrl = await processFile(file);
          previewUrl = compressedUrl;
          base64Data = compressedUrl.split(',')[1];
          setFinalBase64(compressedUrl);
        }

        setImagePreview(previewUrl);

        const result = await analyzeInvoiceImage(base64Data, file.type);

        if (result.type === 'fuel' && activeTab !== 'fuel') {
          setActiveTab('fuel');
        } else if (result.type === 'maintenance' && activeTab !== 'maintenance') {
          setActiveTab('maintenance');
        }

        setFormData({
          title: result.title || (result.type === 'fuel' ? 'Station Service' : 'Entretien Divers'),
          date: result.date || new Date().toISOString().split('T')[0],
          km: result.km?.toString() || '',
          price: result.price?.toString() || '',
          volume: result.volume?.toString() || ''
        });

        if (result.specs) {
          setDetectedSpecs(result.specs);
        }

      } catch (error) {
        console.error("Error processing invoice", error);
      } finally {
        setIsAnalyzing(false);
      }
    }
  };

  const handleSubmit = () => {
    if (!carId) return;
    const newInvoice: Invoice = {
      id: Date.now().toString(),
      carId: carId,
      type: activeTab,
      title: formData.title || (activeTab === 'fuel' ? 'Plein Carburant' : 'Entretien'),
      date: formData.date,
      km: parseInt(formData.km) || 0,
      price: parseFloat(formData.price) || 0,
      volume: activeTab === 'fuel' ? parseFloat(formData.volume) || 0 : undefined,
      imageUrl: finalBase64 || undefined,
      detectedSpecs: detectedSpecs
    };
    onSave(newInvoice, detectedSpecs);
  };

  const resetUpload = (e: React.MouseEvent) => {
    e.stopPropagation();
    setImagePreview(null);
    setFinalBase64(null);
    setFileType('');
    setFileName('');
    setDetectedSpecs(undefined);
    setFormData({title: '', date: new Date().toISOString().split('T')[0], km: '', price: '', volume: ''});
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const renderDetectedSpecs = () => {
    if (!detectedSpecs) return null;

    // Check if at least one spec is not null
    const hasSpecs = Object.values(detectedSpecs).some(val => val !== null && val !== '');
    if (!hasSpecs) return null;

    return (
      <div className="mt-6 bg-nsp-primary/5 border border-nsp-primary/20 rounded-2xl p-4 animate-fade-in">
        <div className="flex items-center gap-2 mb-3">
          <Sparkles size={16} className="text-nsp-primary" />
          <h3 className="text-[10px] font-black text-white uppercase tracking-widest">Inscription Technique IA</h3>
        </div>
        <div className="grid grid-cols-2 gap-3">
          {detectedSpecs.tireDimensions && (
            <div className="bg-black/40 p-2 rounded-lg border border-white/5">
              <p className="text-[8px] text-gray-500 uppercase font-black">Pneus</p>
              <p className="text-[10px] text-white font-bold">{detectedSpecs.tireDimensions}</p>
            </div>
          )}
          {detectedSpecs.oilViscosity && (
            <div className="bg-black/40 p-2 rounded-lg border border-white/5">
              <p className="text-[8px] text-gray-500 uppercase font-black">Huile</p>
              <p className="text-[10px] text-white font-bold">{detectedSpecs.oilViscosity}</p>
            </div>
          )}
          {detectedSpecs.oilFilterRef && (
            <div className="bg-black/40 p-2 rounded-lg border border-white/5">
              <p className="text-[8px] text-gray-500 uppercase font-black">Filtre Huile</p>
              <p className="text-[10px] text-white font-bold truncate">{detectedSpecs.oilFilterRef}</p>
            </div>
          )}
          {detectedSpecs.batteryRef && (
            <div className="bg-black/40 p-2 rounded-lg border border-white/5">
              <p className="text-[8px] text-gray-500 uppercase font-black">Batterie</p>
              <p className="text-[10px] text-white font-bold">{detectedSpecs.batteryRef}</p>
            </div>
          )}
        </div>
        <div className="mt-3 flex items-center gap-2 text-[9px] text-green-500 font-bold uppercase">
           <ShieldCheck size={12} /> Ces données seront ajoutées au garage
        </div>
      </div>
    );
  };

  return (
    <div className="h-[100dvh] bg-nsp-bg flex flex-col w-full absolute inset-0 z-50">
      <div className="p-4 flex items-center justify-between bg-nsp-card border-b border-nsp-border shrink-0 pt-safe-top">
        <button onClick={onCancel} className="text-nsp-sub hover:text-white p-2"><X size={24} /></button>
        <h2 className="text-lg font-bold text-white">Ajouter Document</h2>
        <div className="w-6"></div>
      </div>

      <div className="flex p-4 gap-4 shrink-0">
        <button onClick={() => setActiveTab('maintenance')} className={`flex-1 py-3 rounded-xl border flex items-center justify-center gap-2 font-bold transition-all ${activeTab === 'maintenance' ? 'bg-nsp-primary border-nsp-primary text-white shadow-lg' : 'bg-nsp-input border-transparent text-gray-500'}`}>
          <Wrench size={18} /> Entretien
        </button>
        <button onClick={() => setActiveTab('fuel')} className={`flex-1 py-3 rounded-xl border flex items-center justify-center gap-2 font-bold transition-all ${activeTab === 'fuel' ? 'bg-blue-600 border-blue-600 text-white shadow-lg' : 'bg-nsp-input border-transparent text-gray-500'}`}>
          <Fuel size={18} /> Carburant
        </button>
      </div>

      <div className="flex-1 p-4 pt-0 overflow-y-auto w-full max-w-2xl mx-auto pb-24">
        <div 
          className="relative w-full aspect-video rounded-2xl border-2 border-dashed border-gray-600 bg-gray-800 flex flex-col items-center justify-center mb-4 overflow-hidden cursor-pointer hover:border-white transition-colors"
          onClick={() => !imagePreview && fileInputRef.current?.click()}
        >
          {imagePreview ? (
            <>
              {fileType === 'pdf' ? (
                <div className="flex flex-col items-center justify-center text-white opacity-80">
                  <FileText size={64} className="text-red-500 mb-2" />
                  <p className="font-bold text-lg">Document PDF</p>
                </div>
              ) : (
                <img src={imagePreview} alt="Preview" className="w-full h-full object-contain opacity-50" />
              )}

              <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                 {isAnalyzing ? (
                   <div className="text-center space-y-2 bg-black/60 p-4 rounded-xl backdrop-blur-sm">
                     <Loader2 size={48} className="text-nsp-primary animate-spin mx-auto" />
                     <p className="text-white font-bold">Analyse IA...</p>
                   </div>
                 ) : (
                   <div className="bg-green-500/20 text-green-400 px-4 py-2 rounded-full border border-green-500/50 flex items-center gap-2 backdrop-blur-md">
                     <Check size={16} /> Analyse terminée
                   </div>
                 )}
              </div>
              <button onClick={resetUpload} className="absolute top-4 right-4 bg-black/50 text-white p-2 rounded-full hover:bg-nsp-primary transition-colors pointer-events-auto"><X size={16} /></button>
            </>
          ) : (
            <div className="flex flex-col items-center animate-fade-in text-center p-6">
               <div className="p-4 bg-gray-700/50 rounded-full mb-3 border border-white/5">
                  <Camera size={40} className="text-white" />
               </div>
               <p className="text-white font-bold">Scanner le document</p>
               <p className="text-gray-400 text-xs mt-1">L'IA remplira automatiquement les KM, le prix et les références techniques.</p>
            </div>
          )}
          <input type="file" ref={fileInputRef} className="hidden" accept="image/*,application/pdf" onChange={handleFileChange} />
        </div>

        <div className="space-y-4">
          <div className="relative">
            <label className="block text-sm font-medium text-gray-400 mb-2">Titre</label>
            <input type="text" className="w-full bg-nsp-input border border-transparent rounded-lg px-4 py-3 text-white focus:outline-none focus:border-white" placeholder="Ex: Vidange, Pneus..." value={formData.title} onChange={(e) => setFormData({...formData, title: e.target.value})} />
            {!isAnalyzing && formData.title && <Zap size={14} className="absolute right-4 bottom-4 text-nsp-primary" />}
