            <div className="relative">
              <label className="block text-sm font-medium text-gray-400 mb-2">Prix (€)</label>
              <input type="number" inputMode="decimal" step="0.01" className="w-full bg-nsp-input border border-transparent rounded-lg px-4 py-3 text-white focus:outline-none focus:border-white" placeholder="0.00" value={formData.price} onChange={(e) => setFormData({...formData, price: e.target.value})} />
              {!isAnalyzing && formData.price && <Zap size={14} className="absolute right-4 bottom-4 text-nsp-primary" />}
