          {activeTab === 'fuel' && (
            <div className="bg-blue-900/10 border border-blue-800/30 rounded-lg p-4 animate-fade-in relative">
              <label className="block text-sm font-medium text-blue-200 mb-2">Volume (Litres)</label>
