              {!isAnalyzing && formData.volume && <Zap size={14} className="absolute right-4 bottom-4 text-blue-400" />}
            </div>
          )}

          <div className="relative">
            <label className="block text-sm font-medium text-gray-400 mb-2">Date</label>
            <input type="date" className="w-full bg-nsp-input border border-transparent rounded-lg px-4 py-3 text-white focus:outline-none [color-scheme:dark]" value={formData.date} onChange={(e) => setFormData({...formData, date: e.target.value})} />
            {!isAnalyzing && formData.date && <Zap size={14} className="absolute right-4 bottom-4 text-nsp-primary" />}
