export const processFile = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement('canvas');
        let width = img.width;
        let height = img.height;
        const MAX_SIZE = 1200; 
        if (width > height) {
          if (width > MAX_SIZE) {
            height *= MAX_SIZE / width;
            width = MAX_SIZE;
          }
        } else {
          if (height > MAX_SIZE) {
            width *= MAX_SIZE / height;
            height = MAX_SIZE;
          }
        }
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.drawImage(img, 0, 0, width, height);
          resolve(canvas.toDataURL('image/jpeg', 0.8));
        } else {
          reject(new Error("Canvas error"));
        }
      };
      img.onerror = () => reject(new Error("Image load error"));
      img.src = e.target?.result as string;
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

export const fileToGenerativePart = async (file: File): Promise<string> => {
  if (file.type.startsWith('image/')) {
    const compressedDataUrl = await processFile(file);
    return compressedDataUrl.split(',')[1];
  } else {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = reader.result as string;
        const base64Data = base64String.split(',')[1];
        resolve(base64Data);
      };
      reader.onerror = reject;
      reader.readAsDataURL(file);
    });
  }
};

const cleanJsonString = (text: string): string => {
  return text.replace(/```json/g, '').replace(/```/g, '').trim();
};

export const analyzeInvoiceImage = async (base64Data: string, mimeType: string = 'image/jpeg') => {
  if (!process.env.API_KEY) return { type: 'maintenance', title: "Saisie Manuelle", date: new Date().toISOString().split('T')[0], km: 0, price: 0 };

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { mimeType: mimeType.startsWith('image') ? 'image/jpeg' : mimeType, data: base64Data } },
          { text: `ANALYSE TECHNIQUE AUTOMOBILE NSP.
          1. Catégorie: fuel (carburant) ou maintenance (entretien/réparation).
          2. Données: titre, date (YYYY-MM-DD), km (entier), price (nombre), volume (litres si fuel).
          3. MÉMOIRE TECHNIQUE (CRITIQUE): Extrais les références exactes pour le garage :
             - tireDimensions: ex "205/55 R16 91V"
             - oilViscosity: ex "5W30"
             - batteryRef: ex "70Ah 640A"
             - oilFilterRef: référence pièce (ex "Purflux L398")
             - airFilterRef: référence pièce
             - fuelFilterRef: référence pièce
             - cabinFilterRef: référence pièce
             - wiperRef: référence ou dimension balais.` }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            type: { type: Type.STRING },
            title: { type: Type.STRING },
            date: { type: Type.STRING },
            km: { type: Type.NUMBER },
            price: { type: Type.NUMBER },
            volume: { type: Type.NUMBER },
            specs: { 
              type: Type.OBJECT,
              properties: {
                tireDimensions: { type: Type.STRING },
                oilViscosity: { type: Type.STRING },
                batteryRef: { type: Type.STRING },
                oilFilterRef: { type: Type.STRING },
                airFilterRef: { type: Type.STRING },
                fuelFilterRef: { type: Type.STRING },
                cabinFilterRef: { type: Type.STRING },
                wiperRef: { type: Type.STRING }
              },
              nullable: true
            }
          }
        }
      }
    });
    return JSON.parse(cleanJsonString(response.text || '{}'));
  } catch (error) {
    console.error("Gemini Error:", error);
    return { type: 'maintenance', title: "Erreur Analyse", date: new Date().toISOString().split('T')[0], km: 0, price: 0 };
  }
};

export const getPersonalizedMaintenance = async (car: Car, currentKm: number): Promise<ManufacturerSpecs> => {
  if (!process.env.API_KEY) return { tirePressure: "2.4 bar", oilType: "5W30", checkPoints: ["Niveau Huile", "Pression Pneus", "Lave-glace"] };
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `Expert NSP. Véhicule: ${car.name}, Moteur: ${car.fuelType}, Km: ${currentKm}. Donne 3 points de contrôle conformité.`;
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            tirePressure: { type: Type.STRING },
            oilType: { type: Type.STRING },
            checkPoints: { type: Type.ARRAY, items: { type: Type.STRING } }
          }
        }
      }
    });
    return JSON.parse(cleanJsonString(response.text || '{}'));
  } catch (e) {
    return { tirePressure: "2.5 bar", oilType: "Standard", checkPoints: ["Pneus", "Huile", "Lave-glace"] };
  }
};

