        <div 
          className="relative w-full aspect-video rounded-2xl border-2 border-dashed border-gray-600 bg-gray-800 flex flex-col items-center justify-center mb-6 overflow-hidden cursor-pointer"
          onClick={() => !finalBase64 && fileInputRef.current?.click()}
        >
          {finalBase64 ? (
            <>
              {fileType === 'pdf' ? <FileText size={48} className="text-red-500" /> : <img src={imagePreview!} className="w-full h-full object-cover opacity-40" />}
              <div className="absolute inset-0 flex items-center justify-center">
                 {isAnalyzing ? <Loader2 size={40} className="text-nsp-primary animate-spin" /> : <div className="bg-green-500/20 text-green-400 px-4 py-2 rounded-full border border-green-500/50 flex items-center gap-2 backdrop-blur-md"><Check size={16} /> Analyse IA Terminée</div>}
              </div>
