const CACHE_NAME = 'autobook-cache-v4';
const ASSETS_TO_CACHE = [
  './',
  'index.html',
  'manifest.json'
];

// Installation
self.addEventListener('install', (event) => {
  self.skipWaiting();
  event.waitUntil(
    caches.open(CACHE_NAME).then((cache) => {
      return cache.addAll(ASSETS_TO_CACHE);
    })
  );
});

// Activation
self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((cacheNames) => {
      return Promise.all(
        cacheNames.map((cacheName) => {
          if (cacheName !== CACHE_NAME) {
            return caches.delete(cacheName);
          }
        })
      );
    })
  );
  return self.clients.claim();
});

// Gestion des Notifications en arrière-plan (Push ou Local via SW)
self.addEventListener('notificationclick', (event) => {
  event.notification.close();
  // Au clic, on ouvre l'application ou on la met au premier plan
  event.waitUntil(
    clients.matchAll({ type: 'window', includeUncontrolled: true }).then((clientList) => {
      if (clientList.length > 0) {
        let client = clientList[0];
        for (let i = 0; i < clientList.length; i++) {
          if (clientList[i].focused) {
            client = clientList[i];
          }
        }
        return client.focus();
      }
      return clients.openWindow('./');
    })
  );
});

// Intercepter le fetch (mode hors-ligne)
self.addEventListener('fetch', (event) => {
  event.respondWith(
    fetch(event.request).catch(() => caches.match(event.request))
  );
});

export const requestNotificationPermission = async (): Promise<boolean> => {
  if (!("Notification" in window)) {
    console.log("Les notifications ne sont pas supportées par ce navigateur.");
    return false;
  }

  let permission = Notification.permission;
  if (permission === "default") {
    permission = await Notification.requestPermission();
  }

  return permission === "granted";
};

/**
 * Envoie une notification via le Service Worker pour un affichage "natif" sur mobile.
 */
export const sendLocalNotification = async (title: string, body: string) => {
  if (!("serviceWorker" in navigator)) {
    // Fallback si pas de SW
    if (Notification.permission === "granted") {
      new Notification(title, { body });
    }
    return;
  }

  const registration = await navigator.serviceWorker.ready;
  if (registration && Notification.permission === "granted") {
    registration.showNotification(title, {
      body: body,
      icon: 'https://cdn-icons-png.flaticon.com/512/3202/3202926.png',
      badge: 'https://cdn-icons-png.flaticon.com/512/3202/3202926.png',
      vibrate: [200, 100, 200],
      tag: 'autobook-alert',
      renotify: true,
      data: {
        url: window.location.origin
      }
    });
  }
};

