import React, { useState, useEffect, useRef } from 'react';
import { Screen, User, Car, Invoice, AIStatus, TechnicalSpecs } from './types';
import { AuthScreen } from './components/AuthScreen';
import { OnboardingScreen } from './components/OnboardingScreen';
import { DashboardScreen } from './components/DashboardScreen';
import { GarageScreen } from './components/GarageScreen';
import { AddInvoiceScreen } from './components/AddInvoiceScreen';
import { SellCarScreen } from './components/SellCarScreen';
import { BuyCarScreen } from './components/BuyCarScreen';
import { AssistanceScreen } from './components/AssistanceScreen';
import { AdminDashboardScreen } from './components/AdminDashboardScreen';
import { PaymentModal, PurchaseType } from './components/PaymentModal';
import { calculateMaintenanceStatus } from './services/mechanicRules';
import { db } from './services/storageService'; 
import { cloud } from './services/cloudService';
import { Cloud, Loader2, WifiOff } from 'lucide-react';

const App: React.FC = () => {
  const [screen, setScreen] = useState<Screen>(Screen.AUTH);
  const [user, setUser] = useState<User | null>(null);
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [allCars, setAllCars] = useState<Car[]>([]);
  const [allInvoices, setAllInvoices] = useState<Invoice[]>([]);
  const [isDatabaseReady, setIsDatabaseReady] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [showPayment, setShowPayment] = useState<PurchaseType | null>(null);
  const [activeCarId, setActiveCarId] = useState<string | null>(null);

  const loadAllData = async () => {
    try {
      const remoteUsers = await cloud.fetchAllUsers();
      setAllUsers(remoteUsers.length === 0 ? db.users.getAll() : remoteUsers);
      setAllCars(db.cars.getAll());
      setAllInvoices(db.invoices.getAll());
    } catch (e) {
      setAllUsers(db.users.getAll());
    }
  };

  useEffect(() => {
    const initApp = async () => {
      await loadAllData();
      setIsDatabaseReady(true);
      const sessionId = db.session.get();
      if (sessionId) {
        const foundUser = allUsers.find(u => u.id === sessionId);
        if (foundUser) {
          setUser(foundUser);
          if (foundUser.role === 'admin') setScreen(Screen.ADMIN_DASHBOARD);
          else {
            const savedCarId = localStorage.getItem('AUTOBOOK_ACTIVE_CAR');
            if (savedCarId) {
                setActiveCarId(savedCarId);
                setScreen(Screen.DASHBOARD);
            } else setScreen(Screen.GARAGE);
          }
        }
      }
    };
    initApp();
  }, [allUsers.length]);

  const handleLogin = async (loggedInUser: User) => {
    setIsSyncing(true);
    await cloud.syncUser(loggedInUser);
    setUser(loggedInUser);
    db.session.set(loggedInUser.id);
    setScreen(loggedInUser.role === 'admin' ? Screen.ADMIN_DASHBOARD : Screen.GARAGE);
    setTimeout(() => setIsSyncing(false), 1000);
  };

  const handleSaveInvoice = (inv: Invoice, specs?: TechnicalSpecs) => {
    const updatedInvoices = [inv, ...allInvoices];
    setAllInvoices(updatedInvoices);
    db.invoices.saveAll(updatedInvoices);

    if (specs && activeCarId) {
      setAllCars(prevCars => {
        const updated = prevCars.map(c => {
          if (c.id === activeCarId) {
            const mergedSpecs = { ...(c.specs || {}), ...specs };
            // On nettoie les valeurs null/undefined pour garder une DB propre
            Object.keys(mergedSpecs).forEach(key => {
               if (!mergedSpecs[key as keyof TechnicalSpecs]) delete mergedSpecs[key as keyof TechnicalSpecs];
            });
            return { ...c, specs: mergedSpecs };
          }
          return c;
        });
        db.cars.saveAll(updated);
        return updated;
      });
    }
    setScreen(Screen.DASHBOARD);
  };

  return (
    <div className="max-w-md mx-auto bg-nsp-bg shadow-2xl h-[100dvh] relative overflow-y-auto">
      {isSyncing && (
        <div className="fixed top-6 right-6 z-[110] bg-black/80 text-white px-4 py-2 rounded-full text-[10px] font-black uppercase tracking-widest flex items-center gap-2 border border-white/10 shadow-2xl backdrop-blur-xl">
           <Cloud size={14} className="text-green-500 animate-pulse" /> <span>Sync Cloud</span>
        </div>
      )}

      {!isDatabaseReady ? (
        <div className="h-full flex flex-col items-center justify-center space-y-6">
           <div className="relative">
              <Loader2 className="animate-spin text-nsp-primary" size={48} />
              <div className="absolute inset-0 flex items-center justify-center">
                 <div className="w-2 h-2 bg-nsp-primary rounded-full"></div>
              </div>
           </div>
           <p className="text-gray-500 text-[10px] font-black uppercase tracking-[0.3em] animate-pulse">Garage NSP Initialisation</p>
        </div>
      ) : (
        <>
         {screen === Screen.AUTH && <AuthScreen onLogin={handleLogin} onForgotPasswordRequest={(e) => {
           const u = allUsers.find(x => x.email.toLowerCase() === e.toLowerCase());
           if(u) return true;
           return false;
         }} existingUsers={allUsers} />}
         {screen === Screen.ADMIN_DASHBOARD && <AdminDashboardScreen currentUser={user!} allUsers={allUsers} allCars={allCars} allInvoices={allInvoices} onLogout={() => { setUser(null); db.session.clear(); setScreen(Screen.AUTH); }} onUpdateUser={(u) => setAllUsers(prev => prev.map(x => x.id === u.id ? u : x))} onDeleteUser={(id) => setAllUsers(prev => prev.filter(u => u.id !== id))} onRefresh={loadAllData} />}
         {screen === Screen.GARAGE && <GarageScreen user={user!} cars={allCars.filter(c => c.ownerId === user?.id)} onSelectCar={(id) => { setActiveCarId(id); localStorage.setItem('AUTOBOOK_ACTIVE_CAR', id); setScreen(Screen.DASHBOARD); }} onAddCar={() => setScreen(Screen.ONBOARDING)} onLogout={() => { setUser(null); db.session.clear(); setScreen(Screen.AUTH); }} />}
         {screen === Screen.ONBOARDING && <OnboardingScreen onSave={(c) => { 
           const carWithId = { ...c, ownerId: user!.id };
           const updatedCars = [...allCars, carWithId];
           setAllCars(updatedCars);
           db.cars.saveAll(updatedCars);
           setActiveCarId(c.id);
           localStorage.setItem('AUTOBOOK_ACTIVE_CAR', c.id);
           setScreen(Screen.DASHBOARD);
         }} onCancel={() => setScreen(Screen.GARAGE)} canUseSiv={!!(user?.isPremium || user?.hasSivAccess)} onRequireSiv={() => setShowPayment('siv')} />}
         {screen === Screen.DASHBOARD && activeCarId && <DashboardScreen user={user!} car={allCars.find(c => c.id === activeCarId)!} invoices={allInvoices.filter(i => i.carId === activeCarId)} aiStatus={{status:'neutral', message:''}} onBackToGarage={() => setScreen(Screen.GARAGE)} onAddInvoice={() => setScreen(Screen.ADD_INVOICE)} onSellCar={() => setScreen(Screen.SELL_CAR)} onBuyCar={() => setScreen(Screen.BUY_CAR)} onAssistance={() => setScreen(Screen.ASSISTANCE)} onDeleteCar={() => { const updated = allCars.filter(c => c.id !== activeCarId); setAllCars(updated); db.cars.saveAll(updated); setActiveCarId(null); setScreen(Screen.GARAGE); }} onUpdateSpecs={(s) => { const updated = allCars.map(c => c.id === activeCarId ? {...c, specs: s} : c); setAllCars(updated); db.cars.saveAll(updated); }} onUpdateCar={(c) => { const updated = allCars.map(x => x.id === c.id ? c : x); setAllCars(updated); db.cars.saveAll(updated); }} onDeleteInvoice={(id) => { const updated = allInvoices.filter(i => i.id !== id); setAllInvoices(updated); db.invoices.saveAll(updated); }} />}
         {screen === Screen.ADD_INVOICE && <AddInvoiceScreen carId={activeCarId!} onSave={handleSaveInvoice} onCancel={() => setScreen(Screen.DASHBOARD)} />}
         {screen === Screen.ASSISTANCE && <AssistanceScreen onBack={() => setScreen(Screen.DASHBOARD)} canUseAssistance={!!(user?.isPremium || user?.hasAssistanceAccess)} onRequireAccess={() => setShowPayment('assistance')} />}
        </>
      )}

      {showPayment && <PaymentModal feature={showPayment} onClose={() => setShowPayment(null)} onSuccess={(t) => {
        if(!user) return;
        const u = {...user};
        if(t === 'premium') u.isPremium = true;
        else if(t === 'siv') u.hasSivAccess = true;
        else u.hasAssistanceAccess = true;
        handleLogin(u);
        setShowPayment(null);
      }} />}
    </div>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";
import { Car, ManufacturerSpecs, TechnicalSpecs } from "../types";

export const processFile = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement('canvas');
        let width = img.width;
        let height = img.height;
        const MAX_SIZE = 1600; // Augmentation de la résolution pour une meilleure lecture
        if (width > height) {
          if (width > MAX_SIZE) {
            height *= MAX_SIZE / width;
            width = MAX_SIZE;
          }
        } else {
          if (height > MAX_SIZE) {
            width *= MAX_SIZE / height;
            height = MAX_SIZE;
          }
        }
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.drawImage(img, 0, 0, width, height);
          resolve(canvas.toDataURL('image/jpeg', 0.85));
        } else {
          reject(new Error("Erreur de rendu image"));
        }
      };
      img.onerror = () => reject(new Error("Échec du chargement de l'image"));
      img.src = e.target?.result as string;
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

export const fileToGenerativePart = async (file: File): Promise<string> => {
  if (file.type.startsWith('image/')) {
    const compressedDataUrl = await processFile(file);
    return compressedDataUrl.split(',')[1];
  } else {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = reader.result as string;
        const base64Data = base64String.split(',')[1];
        resolve(base64Data);
      };
      reader.onerror = reject;
      reader.readAsDataURL(file);
    });
  }
};

export const analyzeInvoiceImage = async (base64Data: string, mimeType: string = 'image/jpeg') => {
  if (!process.env.API_KEY) {
    console.warn("API_KEY manquante. Analyse désactivée.");
    return { type: 'maintenance', title: "Saisie Manuelle", date: new Date().toISOString().split('T')[0], km: 0, price: 0 };
  }

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview', // Utilisation du modèle Pro pour l'OCR complexe
      contents: {
        parts: [
          { inlineData: { mimeType: mimeType.startsWith('image') ? 'image/jpeg' : mimeType, data: base64Data } },
          { text: `Analyse cette facture automobile ou ticket de carburant. 
          Extrais les données obligatoires : type (fuel/maintenance), title, date (YYYY-MM-DD), km (entier), price (nombre).
          Extrais aussi les références techniques si visibles : tireDimensions, oilViscosity, batteryRef, oilFilterRef, airFilterRef, fuelFilterRef, cabinFilterRef, wiperRef.
          Réponds UNIQUEMENT en JSON pur.` }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            type: { type: Type.STRING },
            title: { type: Type.STRING },
            date: { type: Type.STRING },
            km: { type: Type.NUMBER },
            price: { type: Type.NUMBER },
            volume: { type: Type.NUMBER },
            specs: { 
              type: Type.OBJECT,
              properties: {
                tireDimensions: { type: Type.STRING },
                oilViscosity: { type: Type.STRING },
                batteryRef: { type: Type.STRING },
                oilFilterRef: { type: Type.STRING },
                airFilterRef: { type: Type.STRING },
                fuelFilterRef: { type: Type.STRING },
                cabinFilterRef: { type: Type.STRING },
                wiperRef: { type: Type.STRING }
              }
            }
          }
        }
      }
    });

    const text = response.text || "{}";
    // Nettoyage au cas où le modèle renverrait des backticks Markdown
    const cleanJson = text.replace(/```json/g, "").replace(/```/g, "").trim();
    return JSON.parse(cleanJson);
  } catch (error) {
    console.error("Erreur critique Gemini:", error);
    // Retourne un objet vide structuré pour éviter de casser l'UI
    return { type: 'maintenance', title: "Analyse échouée", date: new Date().toISOString().split('T')[0], km: 0, price: 0 };
  }
};

export const getPersonalizedMaintenance = async (car: Car, currentKm: number): Promise<ManufacturerSpecs> => {
  if (!process.env.API_KEY) return { tirePressure: "2.4 bar", oilType: "5W30", checkPoints: ["Niveau Huile", "Pression Pneus", "Lave-glace"] };
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = `Génère le plan d'entretien technique pour un véhicule ${car.name}, Moteur: ${car.fuelType}, Kilométrage actuel: ${currentKm}.`;
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            tirePressure: { type: Type.STRING },
            oilType: { type: Type.STRING },
            checkPoints: { type: Type.ARRAY, items: { type: Type.STRING } }
          }
        }
      }
    });
    const cleanJson = (response.text || "{}").replace(/```json/g, "").replace(/```/g, "").trim();
    return JSON.parse(cleanJson);
  } catch (e) {
    return { tirePressure: "2.5 bar", oilType: "Standard", checkPoints: ["Pneus", "Huile", "Lave-glace"] };
  }
};

import React, { useState, useRef } from 'react';
import { Invoice, TechnicalSpecs } from '../types';
import { Loader2, X, Check, FileText, Fuel, Wrench, Sparkles, Camera, Zap, ShieldCheck, HardDrive, AlertTriangle, ArrowRight } from 'lucide-react';
import { analyzeInvoiceImage, fileToGenerativePart, processFile } from '../services/geminiService';

interface AddInvoiceScreenProps {
  carId: string;
  onSave: (invoice: Invoice, detectedSpecs?: TechnicalSpecs) => void;
  onCancel: () => void;
}

export const AddInvoiceScreen: React.FC<AddInvoiceScreenProps> = ({ carId, onSave, onCancel }) => {
  const [activeTab, setActiveTab] = useState<'maintenance' | 'fuel'>('maintenance');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysisError, setAnalysisError] = useState<string | null>(null);
  const [imagePreview, setImagePreview] = useState<string | null>(null);
  const [finalBase64, setFinalBase64] = useState<string | null>(null);
  const [fileType, setFileType] = useState<string>(''); 
  const [detectedSpecs, setDetectedSpecs] = useState<TechnicalSpecs | undefined>(undefined);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState({
    title: '',
    date: new Date().toISOString().split('T')[0],
    km: '',
    price: '',
    volume: ''
  });

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const isPdf = file.type === 'application/pdf';
      setFileType(isPdf ? 'pdf' : 'image');
      setIsAnalyzing(true);
      setAnalysisError(null);
      setDetectedSpecs(undefined);

      try {
        let base64Data: string;
        if (isPdf) {
          const rawBase64 = await fileToGenerativePart(file);
          base64Data = rawBase64;
          setImagePreview(null);
          setFinalBase64(`data:application/pdf;base64,${rawBase64}`);
        } else {
          const compressedUrl = await processFile(file);
          setImagePreview(compressedUrl);
          base64Data = compressedUrl.split(',')[1];
          setFinalBase64(compressedUrl);
        }

        const result = await analyzeInvoiceImage(base64Data, file.type);

        if (result && result.title !== "Analyse échouée") {
          setActiveTab(result.type === 'fuel' ? 'fuel' : 'maintenance');
          setFormData({
            title: result.title || (result.type === 'fuel' ? 'Station Service' : 'Entretien'),
            date: result.date || new Date().toISOString().split('T')[0],
            km: result.km?.toString() || '',
            price: result.price?.toString() || '',
            volume: result.volume?.toString() || ''
          });
          if (result.specs) setDetectedSpecs(result.specs);
        } else {
          setAnalysisError("L'IA n'a pas pu lire ce document. Veuillez remplir les champs manuellement.");
        }
      } catch (error) {
        console.error("Error analyzing", error);
        setAnalysisError("Erreur de connexion avec le serveur d'analyse.");
      } finally {
        setIsAnalyzing(false);
      }
    }
  };

  const handleSubmit = () => {
    if (!carId) return;
    const newInvoice: Invoice = {
      id: Date.now().toString(),
      carId,
      type: activeTab,
      title: formData.title || (activeTab === 'fuel' ? 'Plein Carburant' : 'Entretien'),
      date: formData.date,
      km: parseInt(formData.km) || 0,
      price: parseFloat(formData.price) || 0,
      volume: activeTab === 'fuel' ? parseFloat(formData.volume) || 0 : undefined,
      imageUrl: finalBase64 || undefined,
      detectedSpecs
    };
    onSave(newInvoice, detectedSpecs);
  };

  return (
    <div className="h-[100dvh] bg-nsp-bg flex flex-col w-full absolute inset-0 z-50">
      <div className="p-4 flex items-center justify-between bg-nsp-card border-b border-nsp-border shrink-0 pt-safe-top">
        <button onClick={onCancel} className="text-nsp-sub p-2"><X size={24} /></button>
        <h2 className="text-lg font-bold text-white">Ajouter Document</h2>
        <div className="w-6"></div>
      </div>

      <div className="flex-1 p-4 overflow-y-auto w-full max-w-2xl mx-auto pb-24">
        <div 
          className="relative w-full aspect-video rounded-2xl border-2 border-dashed border-gray-600 bg-gray-800 flex flex-col items-center justify-center mb-6 overflow-hidden cursor-pointer group"
          onClick={() => !isAnalyzing && fileInputRef.current?.click()}
        >
          {finalBase64 ? (
            <>
              {fileType === 'pdf' ? <FileText size={48} className="text-red-500" /> : <img src={imagePreview!} className="w-full h-full object-cover opacity-40" />}
              <div className="absolute inset-0 flex items-center justify-center">
                 {isAnalyzing ? (
                   <div className="bg-black/60 px-6 py-3 rounded-2xl flex flex-col items-center gap-2 border border-white/10">
                      <Loader2 size={32} className="text-nsp-primary animate-spin" />
                      <span className="text-white text-xs font-black uppercase tracking-widest">Analyse IA en cours...</span>
                   </div>
                 ) : analysisError ? (
                   <div className="bg-red-600/20 text-red-500 px-4 py-2 rounded-full border border-red-500/50 flex items-center gap-2 backdrop-blur-md">
                      <AlertTriangle size={16} /> Échec de l'analyse
                   </div>
                 ) : (
                   <div className="bg-green-500/20 text-green-400 px-4 py-2 rounded-full border border-green-500/50 flex items-center gap-2 backdrop-blur-md">
                      <Check size={16} /> Données extraites par IA
                   </div>
                 )}
              </div>
