import { GoogleGenAI, Type } from "@google/genai";
import { Car, ManufacturerSpecs, TechnicalSpecs } from "../types";

export const processFile = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement('canvas');
        let width = img.width;
        let height = img.height;
        const MAX_SIZE = 1600; 
        if (width > height) {
          if (width > MAX_SIZE) {
            height *= MAX_SIZE / width;
            width = MAX_SIZE;
          }
        } else {
          if (height > MAX_SIZE) {
            width = width * (MAX_SIZE / height);
            height = MAX_SIZE;
          }
        }
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.drawImage(img, 0, 0, width, height);
          resolve(canvas.toDataURL('image/jpeg', 0.85));
        } else {
          reject(new Error("Erreur de rendu image"));
        }
      };
      img.onerror = () => reject(new Error("Échec du chargement de l'image"));
      img.src = e.target?.result as string;
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

export const fileToGenerativePart = async (file: File): Promise<string> => {
  if (file.type.startsWith('image/')) {
    const compressedDataUrl = await processFile(file);
    return compressedDataUrl.split(',')[1];
  } else {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = reader.result as string;
        const base64Data = base64String.split(',')[1];
        resolve(base64Data);
      };
      reader.onerror = reject;
      reader.readAsDataURL(file);
    });
  }
};

export const analyzeInvoiceImage = async (base64Data: string, mimeType: string = 'image/jpeg') => {
  // Toujours instancier avec la clé de l'environnement
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("AUTH_REQUIRED");
  }

  try {
    const ai = new GoogleGenAI({ apiKey });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { mimeType: mimeType.startsWith('image') ? 'image/jpeg' : mimeType, data: base64Data } },
          { text: `Tu es un expert en factures automobiles. Analyse ce document et extrais les données suivantes strictement en JSON :
          - type: 'fuel' (carburant) ou 'maintenance' (entretien/réparations)
          - title: nom du garage ou de l'enseigne
          - date: la date au format YYYY-MM-DD
          - km: kilométrage (nombre entier)
          - price: montant total TTC (nombre décimal)
          - volume: litres si c'est du carburant
          - specs: objet contenant les références techniques détectées (oilViscosity, tireDimensions, etc.).` }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            type: { type: Type.STRING, enum: ['fuel', 'maintenance'] },
            title: { type: Type.STRING },
            date: { type: Type.STRING },
            km: { type: Type.NUMBER },
            price: { type: Type.NUMBER },
            volume: { type: Type.NUMBER },
            specs: { 
              type: Type.OBJECT,
              properties: {
                tireDimensions: { type: Type.STRING },
                oilViscosity: { type: Type.STRING },
                batteryRef: { type: Type.STRING },
                oilFilterRef: { type: Type.STRING },
                airFilterRef: { type: Type.STRING },
                fuelFilterRef: { type: Type.STRING },
                cabinFilterRef: { type: Type.STRING },
                wiperRef: { type: Type.STRING }
              }
            }
          },
          required: ["type", "title", "date", "km", "price"]
        }
      }
    });

    const text = response.text;
    if (!text) return null;
    return JSON.parse(text);
  } catch (error: any) {
    console.error("Erreur Gemini:", error);
    if (error.message?.includes("API_KEY") || error.status === 403 || error.status === 401) {
      throw new Error("AUTH_REQUIRED");
    }
    return null;
  }
};

export const getPersonalizedMaintenance = async (car: Car, currentKm: number): Promise<ManufacturerSpecs> => {
  try {
    const apiKey = process.env.API_KEY;
    if (!apiKey) throw new Error("No API Key");
    const ai = new GoogleGenAI({ apiKey });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Génère les préconisations d'entretien JSON pour un véhicule ${car.name} (${car.fuelType}) ayant ${currentKm} km.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            tirePressure: { type: Type.STRING },
            oilType: { type: Type.STRING },
            checkPoints: { type: Type.ARRAY, items: { type: Type.STRING } }
          }
        }
      }
    });
    const text = response.text;
    return text ? JSON.parse(text) : { tirePressure: "2.5 bar", oilType: "Standard", checkPoints: ["Pneus", "Huile"] };
  } catch (e) {
    return { tirePressure: "2.5 bar", oilType: "Standard", checkPoints: ["Pneus", "Huile"] };
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { Invoice, TechnicalSpecs, AIStudio } from '../types';
import { Loader2, X, Check, FileText, Sparkles, Camera, Zap, ShieldCheck, HardDrive, AlertTriangle, ArrowRight, ImageIcon, Settings, ExternalLink, Key, Fuel, Wrench } from 'lucide-react';
import { analyzeInvoiceImage, fileToGenerativePart, processFile } from '../services/geminiService';

interface AddInvoiceScreenProps {
  carId: string;
  onSave: (invoice: Invoice, detectedSpecs?: TechnicalSpecs) => void;
  onCancel: () => void;
}

export const AddInvoiceScreen: React.FC<AddInvoiceScreenProps> = ({ carId, onSave, onCancel }) => {
  const [activeTab, setActiveTab] = useState<'maintenance' | 'fuel'>('maintenance');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysisError, setAnalysisError] = useState<string | null>(null);
  const [imagePreview, setImagePreview] = useState<string | null>(null);
  const [finalBase64, setFinalBase64] = useState<string | null>(null);
  const [detectedSpecs, setDetectedSpecs] = useState<TechnicalSpecs | undefined>(undefined);
  const [hasApiKey, setHasApiKey] = useState(true);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const cameraInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState({
    title: '',
    date: new Date().toISOString().split('T')[0],
    km: '',
    price: '',
    volume: ''
  });

  useEffect(() => {
    const checkKey = async () => {
      // Priorité à process.env.API_KEY qui est injectée par l'environnement
      if (process.env.API_KEY) {
        setHasApiKey(true);
      } else if (window.aistudio) {
        const hasKey = await window.aistudio.hasSelectedApiKey();
        setHasApiKey(hasKey);
      } else {
        setHasApiKey(false);
      }
    };
    checkKey();
  }, []);

  const handleConfigureKey = async () => {
    if (window.aistudio) {
      await window.aistudio.openSelectKey();
      // On procède comme si c'était ok pour éviter les blocages de race condition
      setHasApiKey(true);
      setAnalysisError(null);
    }
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const isPdf = file.type === 'application/pdf';
      setIsAnalyzing(true);
      setAnalysisError(null);
      setDetectedSpecs(undefined);

      try {
        let base64Data: string;
        if (isPdf) {
          const rawBase64 = await fileToGenerativePart(file);
          base64Data = rawBase64;
          setImagePreview(null);
          setFinalBase64(`data:application/pdf;base64,${rawBase64}`);
        } else {
          const compressedUrl = await processFile(file);
          setImagePreview(compressedUrl);
          base64Data = compressedUrl.split(',')[1];
          setFinalBase64(compressedUrl);
        }

        const result = await analyzeInvoiceImage(base64Data, file.type);

        if (result) {
          setActiveTab(result.type === 'fuel' ? 'fuel' : 'maintenance');
          setFormData({
            title: result.title || '',
            date: result.date || new Date().toISOString().split('T')[0],
            km: result.km?.toString() || '',
            price: result.price?.toString() || '',
            volume: result.volume?.toString() || ''
          });
          if (result.specs) setDetectedSpecs(result.specs);
        } else {
          setAnalysisError("Analyse terminée. Certaines données n'ont pas pu être lues.");
        }
      } catch (error: any) {
        console.error("Error analyzing", error);
        if (error.message === "AUTH_REQUIRED") {
          setHasApiKey(false);
          setAnalysisError("Clé API requise pour l'analyse IA.");
        } else {
          setAnalysisError("Erreur lors de l'analyse. Saisie manuelle possible.");
        }
      } finally {
        setIsAnalyzing(false);
      }
    }
  };

  const handleSubmit = () => {
    if (!carId) return;
    const newInvoice: Invoice = {
      id: Date.now().toString(),
      carId,
      type: activeTab,
      title: formData.title || (activeTab === 'fuel' ? 'Plein Carburant' : 'Entretien'),
      date: formData.date,
      km: parseInt(formData.km) || 0,
      price: parseFloat(formData.price) || 0,
      volume: activeTab === 'fuel' ? parseFloat(formData.volume) || 0 : undefined,
      imageUrl: finalBase64 || undefined,
      detectedSpecs
    };
    onSave(newInvoice, detectedSpecs);
  };

  return (
    <div className="h-[100dvh] bg-nsp-bg flex flex-col w-full absolute inset-0 z-50">
      <div className="p-4 flex items-center justify-between bg-nsp-card border-b border-nsp-border shrink-0 pt-safe-top">
        <button onClick={onCancel} className="text-nsp-sub p-2"><X size={24} /></button>
        <h2 className="text-lg font-bold text-white">Scanner Document</h2>
        <div className="w-6"></div>
      </div>

      <div className="flex-1 p-4 overflow-y-auto w-full max-w-2xl mx-auto pb-32">

        <div className="flex bg-nsp-input p-1 rounded-2xl mb-6">
          <button 
            onClick={() => setActiveTab('maintenance')}
            className={`flex-1 py-4 rounded-xl flex items-center justify-center gap-2 font-black text-xs uppercase tracking-widest transition-all ${activeTab === 'maintenance' ? 'bg-nsp-primary text-white shadow-lg' : 'text-gray-500'}`}
          >
            <Wrench size={18} /> Entretien
          </button>
          <button 
            onClick={() => setActiveTab('fuel')}
            className={`flex-1 py-4 rounded-xl flex items-center justify-center gap-2 font-black text-xs uppercase tracking-widest transition-all ${activeTab === 'fuel' ? 'bg-nsp-primary text-white shadow-lg' : 'text-gray-500'}`}
          >
            <Fuel size={18} /> Carburant
          </button>
        </div>

        <div className="mb-6">
          <div 
            onClick={() => !isAnalyzing && (cameraInputRef.current?.click())}
            className={`relative aspect-[4/3] rounded-[2rem] border-2 border-dashed flex flex-col items-center justify-center overflow-hidden cursor-pointer transition-all ${finalBase64 ? 'border-nsp-primary bg-nsp-card' : 'border-gray-700 bg-nsp-input'}`}
          >
            {finalBase64 ? (
              <>
                <img src={imagePreview || finalBase64} className="absolute inset-0 w-full h-full object-cover opacity-40" />
                <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/20">
                   {isAnalyzing ? (
                     <div className="bg-black/80 px-6 py-3 rounded-2xl border border-white/10 flex flex-col items-center gap-3">
                        <Loader2 size={32} className="text-nsp-primary animate-spin" />
                        <span className="text-white text-[10px] font-black uppercase tracking-widest animate-pulse">Extraction des données...</span>
                     </div>
                   ) : (
                     <div className="bg-green-500/80 text-white px-6 py-3 rounded-full flex items-center gap-2 font-bold shadow-xl animate-fade-in">
                        <Check size={20} /> Analyse OK
                     </div>
                   )}
                </div>
                <button 
                  onClick={(e) => { e.stopPropagation(); setFinalBase64(null); setImagePreview(null); }}
                  className="absolute top-4 right-4 bg-black/60 p-2 rounded-full text-white hover:bg-red-500"
                >
                  <X size={16} />
                </button>
              </>
            ) : (
              <div className="flex flex-col items-center gap-4 text-gray-500">
                <Camera size={48} />
                <span className="text-[10px] font-black uppercase tracking-[0.2em]">Cliquer pour scanner</span>
              </div>
            )}
          </div>

          <div className="flex justify-center mt-4">
            <button onClick={() => fileInputRef.current?.click()} className="text-[10px] text-gray-500 font-black uppercase underline flex items-center gap-2">
              <ImageIcon size={14} /> Charger une image ou PDF
            </button>
          </div>
        </div>

        {analysisError && (
          <div className="mb-6 bg-red-950/20 border border-red-500/30 p-4 rounded-2xl flex items-center gap-3 text-red-500">
            <AlertTriangle size={18} />
            <p className="text-xs font-bold">{analysisError}</p>
          </div>
        )}

        {!hasApiKey && (
           <div className="mb-6 bg-yellow-950/20 border border-yellow-500/30 p-5 rounded-[2rem] flex flex-col items-center gap-4 text-center">
              <Key className="text-yellow-500" size={24} />
              <p className="text-[10px] text-gray-400 font-black uppercase tracking-widest">
                Configuration requise pour l'analyse intelligente.
              </p>
              <button 
                onClick={handleConfigureKey}
                className="w-full bg-yellow-600 text-black font-black py-4 rounded-2xl text-[10px] uppercase tracking-widest flex items-center justify-center gap-3"
              >
                Activer l'IA <Zap size={16} />
              </button>
           </div>
        )}

        <div className="space-y-6">
          <div>
            <label className="text-[10px] text-gray-500 font-black uppercase mb-1.5 ml-1 block">Établissement / Garage</label>
            <input 
              type="text" 
              className="w-full bg-nsp-input border-transparent rounded-2xl px-5 py-5 text-white font-bold focus:border-nsp-primary border transition-colors" 
              value={formData.title} 
              onChange={(e) => setFormData({...formData, title: e.target.value})} 
              placeholder="Nom du garage" 
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="text-[10px] text-gray-500 font-black uppercase mb-1.5 ml-1 block">Kilométrage</label>
              <input type="number" className="w-full bg-nsp-input border-transparent rounded-2xl px-5 py-5 text-white font-bold focus:border-nsp-primary border" value={formData.km} onChange={(e) => setFormData({...formData, km: e.target.value})} placeholder="0" />
            </div>
            <div>
              <label className="text-[10px] text-gray-500 font-black uppercase mb-1.5 ml-1 block">Montant TTC (€)</label>
              <input type="number" className="w-full bg-nsp-input border-transparent rounded-2xl px-5 py-5 text-white font-bold focus:border-nsp-primary border" value={formData.price} onChange={(e) => setFormData({...formData, price: e.target.value})} placeholder="0" />
            </div>
          </div>

          {activeTab === 'fuel' && (
            <div>
              <label className="text-[10px] text-gray-500 font-black uppercase mb-1.5 ml-1 block">Volume (L)</label>
              <input type="number" className="w-full bg-nsp-input border-transparent rounded-2xl px-5 py-5 text-white font-bold focus:border-nsp-primary border" value={formData.volume} onChange={(e) => setFormData({...formData, volume: e.target.value})} placeholder="0" />
            </div>
          )}

          {detectedSpecs && Object.values(detectedSpecs).some(v => v) && (
            <div className="bg-nsp-primary/10 border border-nsp-primary/20 rounded-[2rem] p-6">
              <h3 className="text-[11px] font-black text-white uppercase tracking-widest mb-4 flex items-center gap-2"><HardDrive size={16} /> Mémoire Technique</h3>
              <div className="grid grid-cols-2 gap-3">
                {Object.entries(detectedSpecs).map(([key, val]) => val && (
                  <div key={key} className="bg-black/40 p-3 rounded-xl border border-white/5">
                    <p className="text-[8px] text-gray-500 uppercase font-black">{key.replace(/Ref|Dimensions|Viscosity/g, '')}</p>
                    <p className="text-[10px] text-white font-bold truncate">{val}</p>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>

        <input type="file" ref={cameraInputRef} className="hidden" accept="image/*" capture="environment" onChange={handleFileChange} />
        <input type="file" ref={fileInputRef} className="hidden" accept="image/*,application/pdf" onChange={handleFileChange} />
      </div>

      <div className="p-4 bg-nsp-card border-t border-nsp-border shrink-0 fixed bottom-0 w-full pb-safe-bottom">
        <button 
          onClick={handleSubmit} 
          disabled={isAnalyzing}
          className="w-full font-black py-5 rounded-2xl text-white bg-nsp-primary hover:bg-red-600 shadow-xl flex items-center justify-center gap-3 uppercase tracking-widest transition-all active:scale-95 disabled:opacity-50"
        >
           {isAnalyzing ? 'Analyse...' : 'Enregistrer'}
        </button>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import { User, Car, Invoice, AIStudio } from '../types';
import { cloud } from '../services/cloudService';
import { 
  BarChart3, Users, QrCode, Printer, 
  Globe, Radio, Database, ExternalLink, AlertCircle, RefreshCcw,
  Loader2, Copy, Check, ShieldAlert, ChevronRight, MousePointer2, HardDrive, Plus, ShieldCheck, ArrowRight,
  Search, Info, Car as CarIcon, X, Smartphone, Globe2
} from 'lucide-react';

interface AdminDashboardScreenProps {
  currentUser: User;
  allUsers: User[];
  allCars: Car[];
  allInvoices: Invoice[];
  onLogout: () => void;
  onUpdateUser: (user: User) => void;
  onDeleteUser: (userId: string) => void;
  onRefresh: () => void;
}

export const AdminDashboardScreen: React.FC<AdminDashboardScreenProps> = ({ 
  currentUser, allUsers, allCars, allInvoices, onLogout, onUpdateUser, onDeleteUser, onRefresh
}) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'diffusion' | 'users' | 'setup'>('overview');
  const [searchTerm, setSearchTerm] = useState('');
  const [cloudStatus, setCloudStatus] = useState<'online' | 'syncing' | 'warning' | 'error'>('online');
  const [isRetrying, setIsRetrying] = useState(false);
  const [copySuccess, setCopySuccess] = useState(false);
  const [customDomain, setCustomDomain] = useState('');

  const isCloudActive = cloud.isConnected();
  const isApiDisabled = cloud.isApiDisabled();

  // Détection auto du domaine Vercel ou local
  const defaultUrl = window.location.origin;
  const publicUrl = customDomain ? (customDomain.startsWith('http') ? customDomain : `https://${customDomain}`) : defaultUrl;

  useEffect(() => {
    if (isApiDisabled) {
      setCloudStatus('error');
      return;
    }
    if (!isCloudActive) {
      setCloudStatus('warning');
      return;
    }

    const unsubscribe = cloud.listenToAllUsers((users) => {
      setCloudStatus('syncing');
      onRefresh();
      setTimeout(() => setCloudStatus('online'), 1000);
    });
    return () => { if(unsubscribe) unsubscribe(); };
  }, [onRefresh, isCloudActive, isApiDisabled]);

  const handleCopyLink = () => {
    navigator.clipboard.writeText(publicUrl);
    setCopySuccess(true);
    setTimeout(() => setCopySuccess(false), 2000);
  };

  const handleRetryCloud = () => {
    setIsRetrying(true);
    cloud.resetActivationFlag();
    onRefresh();
    setTimeout(() => setIsRetrying(false), 2000);
  };

  const stats = useMemo(() => {
    const realUsers = allUsers.filter(u => u.role !== 'admin');
    return { 
      totalUsers: realUsers.length, 
      totalCars: allCars.filter(c => realUsers.some(u => u.id === c.ownerId)).length,
      totalRevenue: allInvoices.reduce((acc, inv) => acc + inv.price, 0)
    };
  }, [allUsers, allCars, allInvoices]);

  const renderKPI = (label: string, value: string | number, icon: React.ReactNode, color: string) => (
    <div className="bg-nsp-card border border-nsp-border p-5 rounded-2xl relative overflow-hidden shadow-xl">
