// Utility to process and compress images before sending to Gemini
export const processFile = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement('canvas');
        let width = img.width;
        let height = img.height;
        const MAX_SIZE = 1600; 
        if (width > height) {
          if (width > MAX_SIZE) {
            height *= MAX_SIZE / width;
            width = MAX_SIZE;
          }
        } else {
          if (height > MAX_SIZE) {
            width = width * (MAX_SIZE / height);
            height = MAX_SIZE;
          }
        }
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.drawImage(img, 0, 0, width, height);
          resolve(canvas.toDataURL('image/jpeg', 0.85));
        } else {
          reject(new Error("Erreur de rendu image"));
        }
      };
      img.onerror = () => reject(new Error("Échec du chargement de l'image"));
      img.src = e.target?.result as string;
    };
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

// Converts a file to base64 for Gemini inlineData
export const fileToGenerativePart = async (file: File): Promise<string> => {
  if (file.type.startsWith('image/')) {
    const compressedDataUrl = await processFile(file);
    return compressedDataUrl.split(',')[1];
  } else {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64String = reader.result as string;
        const base64Data = base64String.split(',')[1];
        resolve(base64Data);
      };
      reader.onerror = reject;
      reader.readAsDataURL(file);
    });
  }
};

// Analyzes an invoice image using Gemini 3 and returns structured data
export const analyzeInvoiceImage = async (base64Data: string, mimeType: string = 'image/jpeg') => {
  // Always obtain the API key exclusively from process.env.API_KEY
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("AUTH_REQUIRED");
  }

  try {
    // Create instance right before making the call using process.env.API_KEY
    const ai = new GoogleGenAI({ apiKey });

    // Explicit model name for basic text/extraction tasks as per documentation
    const modelName = 'gemini-3-flash-preview';

    const response = await ai.models.generateContent({
      model: modelName,
      contents: {
        parts: [
          { inlineData: { mimeType: mimeType.startsWith('image') ? 'image/jpeg' : mimeType, data: base64Data } },
          { text: `Analyse cette facture ou ticket de carburant. Extrais impérativement au format JSON :
          - type: 'fuel' ou 'maintenance'
          - title: nom de l'établissement
          - date: YYYY-MM-DD
          - km: kilométrage (nombre)
          - price: total TTC (nombre)
          - volume: litres (si fuel)
          - specs: références techniques (pneus, huile, filtres).` }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            type: { type: Type.STRING },
            title: { type: Type.STRING },
            date: { type: Type.STRING },
            km: { type: Type.NUMBER },
            price: { type: Type.NUMBER },
            volume: { type: Type.NUMBER },
            specs: { 
              type: Type.OBJECT,
              properties: {
                tireDimensions: { type: Type.STRING },
                oilViscosity: { type: Type.STRING },
                batteryRef: { type: Type.STRING },
                oilFilterRef: { type: Type.STRING },
                airFilterRef: { type: Type.STRING },
                fuelFilterRef: { type: Type.STRING },
                cabinFilterRef: { type: Type.STRING },
                wiperRef: { type: Type.STRING }
              }
            }
          },
          required: ["type", "title", "date", "km", "price"]
        }
      }
    });

    // Directly access text property (not a method)
    const text = response.text;
    if (!text) {
      console.warn("IA Gemini : Réponse vide");
      return null;
    }

    return JSON.parse(text);
  } catch (error: any) {
    console.error(`Erreur IA Gemini (${error.status || 'unknown'}):`, error);
    // Handle 404 (model not found), 403 (unauthorized)
    if (error.status === 404) {
      console.error("Modèle Gemini non trouvé (404). Vérifiez la configuration du projet Google Cloud.");
    }

    if (error.status === 403 || error.status === 401 || error.message?.includes("API_KEY") || error.message?.includes("not found")) {
      throw new Error("AUTH_REQUIRED");
    }
    throw error;
  }
};

// Generates personalized maintenance advice for a car based on its current state
export const getPersonalizedMaintenance = async (car: Car, currentKm: number): Promise<ManufacturerSpecs> => {
  try {
    const apiKey = process.env.API_KEY;
    if (!apiKey) throw new Error("No API Key");

    const ai = new GoogleGenAI({ apiKey });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Génère les préconisations d'entretien JSON pour un véhicule ${car.name} (${car.fuelType}) ayant ${currentKm} km.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            tirePressure: { type: Type.STRING },
            oilType: { type: Type.STRING },
            checkPoints: { type: Type.ARRAY, items: { type: Type.STRING } }
          }
        }
      }
    });

    const text = response.text;
    return text ? JSON.parse(text) : { tirePressure: "2.5 bar", oilType: "Standard", checkPoints: ["Pneus", "Huile"] };
  } catch (e) {
    console.error("Maintenance advice error:", e);
    return { tirePressure: "2.5 bar", oilType: "Standard", checkPoints: ["Pneus", "Huile"] };
  }
};

