      model: 'gemini-3-flash-preview',
      contents: `Génère les préconisations d'entretien JSON pour un véhicule ${car.name} (${car.fuelType}) ayant ${currentKm} km.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            tirePressure: { type: Type.STRING },
            oilType: { type: Type.STRING },
            checkPoints: { type: Type.ARRAY, items: { type: Type.STRING } }
          }
        }
      }
    });

    const text = response.text;
    return text ? JSON.parse(text) : { tirePressure: "2.5 bar", oilType: "Standard", checkPoints: ["Pneus", "Huile"] };
  } catch (e) {
    console.error("Maintenance advice error:", e);
    return { tirePressure: "2.5 bar", oilType: "Standard", checkPoints: ["Pneus", "Huile"] };
  }
};

import React, { useState, useRef, useEffect } from 'react';
import { Invoice, TechnicalSpecs, AIStudio } from '../types';
import { Loader2, X, Check, FileText, Sparkles, Camera, Zap, ShieldCheck, HardDrive, AlertTriangle, ArrowRight, ImageIcon, Settings, ExternalLink, Key, Fuel, Wrench } from 'lucide-react';
import { analyzeInvoiceImage, fileToGenerativePart, processFile } from '../services/geminiService';

interface AddInvoiceScreenProps {
  carId: string;
  onSave: (invoice: Invoice, detectedSpecs?: TechnicalSpecs) => void;
  onCancel: () => void;
}

export const AddInvoiceScreen: React.FC<AddInvoiceScreenProps> = ({ carId, onSave, onCancel }) => {
  const [activeTab, setActiveTab] = useState<'maintenance' | 'fuel'>('maintenance');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysisError, setAnalysisError] = useState<string | null>(null);
  const [imagePreview, setImagePreview] = useState<string | null>(null);
  const [finalBase64, setFinalBase64] = useState<string | null>(null);
  const [detectedSpecs, setDetectedSpecs] = useState<TechnicalSpecs | undefined>(undefined);

  // Logic updated to use current environment API_KEY or check via bridge
  const [hasApiKey, setHasApiKey] = useState(true); // Assume true to not block UI initially

  const fileInputRef = useRef<HTMLInputElement>(null);
  const cameraInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState({
    title: '',
    date: new Date().toISOString().split('T')[0],
    km: '',
    price: '',
    volume: ''
  });

  useEffect(() => {
    const checkKeyStatus = async () => {
      if (process.env.API_KEY) {
        setHasApiKey(true);
      } else if (window.aistudio) {
        const selected = await window.aistudio.hasSelectedApiKey();
        setHasApiKey(selected);
      } else {
        setHasApiKey(false);
      }
    };
    checkKeyStatus();
  }, []);

  const handleConfigureKey = async () => {
    if (window.aistudio) {
      await window.aistudio.openSelectKey();
      // Rule: Assume success immediately after openSelectKey
      setHasApiKey(true);
      setAnalysisError(null);
    }
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      const file = e.target.files[0];
      const isPdf = file.type === 'application/pdf';
      setIsAnalyzing(true);
      setAnalysisError(null);
      setDetectedSpecs(undefined);

      try {
        let base64Data: string;
        if (isPdf) {
          const rawBase64 = await fileToGenerativePart(file);
          base64Data = rawBase64;
          setImagePreview(null);
          setFinalBase64(`data:application/pdf;base64,${rawBase64}`);
        } else {
          const compressedUrl = await processFile(file);
          setImagePreview(compressedUrl);
          base64Data = compressedUrl.split(',')[1];
          setFinalBase64(compressedUrl);
        }

        const result = await analyzeInvoiceImage(base64Data, file.type);

        if (result) {
          setActiveTab(result.type === 'fuel' ? 'fuel' : 'maintenance');
          setFormData({
            title: result.title || '',
            date: result.date || new Date().toISOString().split('T')[0],
            km: result.km?.toString() || '',
            price: result.price?.toString() || '',
            volume: result.volume?.toString() || ''
          });
          if (result.specs) setDetectedSpecs(result.specs);
        } else {
          setAnalysisError("Analyse effectuée, mais aucune donnée exploitable n'a été extraite.");
        }
      } catch (error: any) {
        console.error("Analysis failed:", error);
        if (error.message === "AUTH_REQUIRED") {
          setHasApiKey(false);
          setAnalysisError("Clé API manquante ou invalide. Cliquez sur le bouton ci-dessous pour l'activer.");
        } else {
          setAnalysisError("Erreur technique lors de l'analyse. Saisie manuelle possible.");
        }
      } finally {
        setIsAnalyzing(false);
      }
    }
  };

  const handleSubmit = () => {
    if (!carId) return;
    const newInvoice: Invoice = {
      id: Date.now().toString(),
      carId,
      type: activeTab,
      title: formData.title || (activeTab === 'fuel' ? 'Plein Carburant' : 'Entretien'),
      date: formData.date,
      km: parseInt(formData.km) || 0,
      price: parseFloat(formData.price) || 0,
      volume: activeTab === 'fuel' ? parseFloat(formData.volume) || 0 : undefined,
      imageUrl: finalBase64 || undefined,
      detectedSpecs
    };
    onSave(newInvoice, detectedSpecs);
  };

  return (
    <div className="h-[100dvh] bg-nsp-bg flex flex-col w-full absolute inset-0 z-50">
      <div className="p-4 flex items-center justify-between bg-nsp-card border-b border-nsp-border shrink-0 pt-safe-top">
        <button onClick={onCancel} className="text-nsp-sub p-2"><X size={24} /></button>
        <h2 className="text-lg font-bold text-white">Ajouter un document</h2>
        <div className="w-6"></div>
      </div>

      <div className="flex-1 p-4 overflow-y-auto w-full max-w-2xl mx-auto pb-32">

        <div className="flex bg-nsp-input p-1 rounded-2xl mb-6">
          <button 
            onClick={() => setActiveTab('maintenance')}
            className={`flex-1 py-4 rounded-xl flex items-center justify-center gap-2 font-black text-xs uppercase tracking-widest transition-all ${activeTab === 'maintenance' ? 'bg-nsp-primary text-white shadow-lg' : 'text-gray-500'}`}
          >
            <Wrench size={18} /> Entretien
          </button>
          <button 
            onClick={() => setActiveTab('fuel')}
            className={`flex-1 py-4 rounded-xl flex items-center justify-center gap-2 font-black text-xs uppercase tracking-widest transition-all ${activeTab === 'fuel' ? 'bg-nsp-primary text-white shadow-lg' : 'text-gray-500'}`}
          >
            <Fuel size={18} /> Carburant
          </button>
        </div>

        <div className="mb-6">
          <div 
            onClick={() => !isAnalyzing && (cameraInputRef.current?.click())}
            className={`relative aspect-[4/3] rounded-[2rem] border-2 border-dashed flex flex-col items-center justify-center overflow-hidden cursor-pointer transition-all ${finalBase64 ? 'border-nsp-primary bg-nsp-card' : 'border-gray-700 bg-nsp-input'}`}
          >
            {finalBase64 ? (
              <>
                <img src={imagePreview || finalBase64} className="absolute inset-0 w-full h-full object-cover opacity-40" />
                <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/40">
                   {isAnalyzing ? (
                     <div className="bg-black/80 px-6 py-4 rounded-[2rem] border border-white/10 flex flex-col items-center gap-3">
                        <Loader2 size={32} className="text-nsp-primary animate-spin" />
                        <div className="text-center">
                          <span className="text-white text-[10px] font-black uppercase tracking-widest block">Traitement...</span>
                        </div>
                     </div>
                   ) : (
                     <div className="bg-nsp-success text-white px-6 py-3 rounded-full flex items-center gap-2 font-bold shadow-2xl animate-fade-in">
                        <Check size={20} /> Analyse terminée
                     </div>
                   )}
                </div>
                <button 
                  onClick={(e) => { e.stopPropagation(); setFinalBase64(null); setImagePreview(null); }}
                  className="absolute top-4 right-4 bg-black/60 p-2 rounded-full text-white hover:bg-red-500 z-10"
                >
                  <X size={16} />
                </button>
              </>
            ) : (
              <div className="flex flex-col items-center gap-4 text-gray-500">
                <div className="w-16 h-16 rounded-full bg-nsp-input flex items-center justify-center border border-white/5">
                  <Camera size={32} />
                </div>
                <span className="text-[10px] font-black uppercase tracking-[0.2em]">Scanner un ticket</span>
              </div>
            )}
          </div>

          <div className="flex justify-center mt-4">
            <button onClick={() => fileInputRef.current?.click()} className="text-[10px] text-gray-500 font-black uppercase underline flex items-center gap-2">
              <ImageIcon size={14} /> Fichier PDF ou Image
            </button>
          </div>
        </div>

        {analysisError && (
          <div className="mb-6 bg-red-950/30 border border-red-500/30 p-4 rounded-2xl flex items-center gap-3 text-red-400">
            <AlertTriangle size={18} />
            <p className="text-xs font-bold leading-tight">{analysisError}</p>
          </div>
        )}

        {!hasApiKey && !isAnalyzing && (
           <div className="mb-6 bg-yellow-950/30 border border-yellow-500/20 p-5 rounded-[2rem] flex flex-col items-center gap-4 text-center">
              <Key className="text-yellow-500" size={24} />
              <div className="space-y-1">
                <p className="text-white font-bold text-xs uppercase">IA non activée sur ce compte</p>
                <p className="text-[9px] text-gray-400 font-bold uppercase tracking-widest">Une clé API est nécessaire pour l'extraction automatique.</p>
              </div>
              <button 
                onClick={handleConfigureKey}
                className="w-full bg-yellow-600 text-black font-black py-4 rounded-2xl text-[10px] uppercase tracking-widest flex items-center justify-center gap-3 active:scale-95 transition-transform"
              >
                Activer l'IA maintenant <Zap size={16} />
              </button>
              <a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" className="text-[8px] text-gray-500 underline uppercase font-bold">Documentation Facturation Gemini</a>
           </div>
        )}

        <div className="space-y-6">
          <div>
            <label className="text-[10px] text-gray-500 font-black uppercase mb-1.5 ml-1 block">Titre du document</label>
            <input 
              type="text" 
              className="w-full bg-nsp-input border-transparent rounded-2xl px-5 py-5 text-white font-bold focus:border-nsp-primary border transition-colors outline-none" 
              value={formData.title} 
              onChange={(e) => setFormData({...formData, title: e.target.value})} 
              placeholder="Ex: Révision 60.000km, Station Total..." 
            />
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="text-[10px] text-gray-500 font-black uppercase mb-1.5 ml-1 block">Kilométrage</label>
              <input type="number" className="w-full bg-nsp-input border-transparent rounded-2xl px-5 py-5 text-white font-bold focus:border-nsp-primary border outline-none" value={formData.km} onChange={(e) => setFormData({...formData, km: e.target.value})} placeholder="0" />
            </div>
            <div>
              <label className="text-[10px] text-gray-500 font-black uppercase mb-1.5 ml-1 block">Prix (€)</label>
              <input type="number" className="w-full bg-nsp-input border-transparent rounded-2xl px-5 py-5 text-white font-bold focus:border-nsp-primary border outline-none" value={formData.price} onChange={(e) => setFormData({...formData, price: e.target.value})} placeholder="0.00" />
            </div>
          </div>

          {activeTab === 'fuel' && (
            <div>
              <label className="text-[10px] text-gray-500 font-black uppercase mb-1.5 ml-1 block">Litres (L)</label>
              <input type="number" className="w-full bg-nsp-input border-transparent rounded-2xl px-5 py-5 text-white font-bold focus:border-nsp-primary border outline-none" value={formData.volume} onChange={(e) => setFormData({...formData, volume: e.target.value})} placeholder="0.00" />
            </div>
          )}

          {detectedSpecs && Object.values(detectedSpecs).some(v => v) && (
            <div className="bg-nsp-primary/10 border border-nsp-primary/20 rounded-[2.5rem] p-6 animate-slide-up">
              <h3 className="text-[11px] font-black text-white uppercase tracking-widest mb-4 flex items-center gap-2"><HardDrive size={16} /> Données techniques extraites</h3>
              <div className="grid grid-cols-2 gap-3">
                {Object.entries(detectedSpecs).map(([key, val]) => val && (
                  <div key={key} className="bg-black/40 p-3 rounded-2xl border border-white/5">
                    <p className="text-[8px] text-gray-500 uppercase font-black mb-1">{key.replace(/Ref|Dimensions|Viscosity/g, '')}</p>
                    <p className="text-[10px] text-white font-bold truncate">{val}</p>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>

        <input type="file" ref={cameraInputRef} className="hidden" accept="image/*" capture="environment" onChange={handleFileChange} />
        <input type="file" ref={fileInputRef} className="hidden" accept="image/*,application/pdf" onChange={handleFileChange} />
      </div>

      <div className="p-4 bg-nsp-card border-t border-nsp-border shrink-0 fixed bottom-0 w-full pb-safe-bottom z-40">
        <button 
          onClick={handleSubmit} 
          disabled={isAnalyzing}
          className="w-full font-black py-5 rounded-2xl text-white bg-nsp-primary hover:bg-red-600 shadow-2xl flex items-center justify-center gap-3 uppercase tracking-widest transition-all active:scale-95 disabled:opacity-50"
        >
           {isAnalyzing ? <><Loader2 className="animate-spin" size={18} /> Extraction...</> : 'SAUVEGARDER'}
        </button>
      </div>
    </div>
  );
};

