import React, { useState, useRef, useEffect } from 'react';
import { Invoice, TechnicalSpecs } from '../types';
import { Loader2, X, Check, Camera, Zap, HardDrive, AlertTriangle, ImageIcon, Key, Fuel, Wrench } from 'lucide-react';
import { analyzeInvoiceImage, fileToGenerativePart, processFile } from '../services/geminiService';

interface AddInvoiceScreenProps {
  carId: string;
  onSave: (invoice: Invoice, detectedSpecs?: TechnicalSpecs) => void;
  onCancel: () => void;
}

export const AddInvoiceScreen: React.FC<AddInvoiceScreenProps> = ({ carId, onSave, onCancel }) => {
  const [activeTab, setActiveTab] = useState<'maintenance' | 'fuel'>('maintenance');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);
  const [analysisError, setAnalysisError] = useState<string | null>(null);
  const [imagePreview, setImagePreview] = useState<string | null>(null);
  const [finalBase64, setFinalBase64] = useState<string | null>(null);
  const [detectedSpecs, setDetectedSpecs] = useState<TechnicalSpecs | undefined>(undefined);
  const [hasApiKey, setHasApiKey] = useState(true);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const cameraInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState({
    title: '',
    date: new Date().toISOString().split('T')[0],
    km: '',
    price: '',
    volume: ''
  });

  useEffect(() => {
    const checkKey = async () => {
      if (process.env.API_KEY) {
        setHasApiKey(true);
      } else if (window.aistudio) {
        const selected = await window.aistudio.hasSelectedApiKey();
        setHasApiKey(selected);
      } else {
        setHasApiKey(false);
      }
    };
    checkKey();
  }, []);

  const handleActivateIA = async () => {
    if (window.aistudio) {
      await window.aistudio.openSelectKey();
      setHasApiKey(true);
      setAnalysisError(null);
    }
  };

  const handleFile = async (e: React.ChangeEvent<HTMLInputElement>) => {
    if (!e.target.files?.[0]) return;
    const file = e.target.files[0];
    setIsAnalyzing(true);
    setIsSuccess(false);
    setAnalysisError(null);

    try {
      const base64 = file.type === 'application/pdf' 
        ? await fileToGenerativePart(file)
        : (await processFile(file)).split(',')[1];

      if (file.type !== 'application/pdf') {
        setImagePreview(URL.createObjectURL(file));
      }
      setFinalBase64(base64);

      const res = await analyzeInvoiceImage(base64, file.type);
      if (res && res.title) {
        setIsSuccess(true);
        setActiveTab(res.type === 'fuel' ? 'fuel' : 'maintenance');
        setFormData({
          title: res.title,
          date: res.date || formData.date,
          km: res.km?.toString() || '',
          price: res.price?.toString() || '',
          volume: res.volume?.toString() || ''
        });
        setDetectedSpecs(res.specs);
      }
    } catch (err: any) {
      if (err.message === "AUTH_REQUIRED") setHasApiKey(false);
      setAnalysisError(err.message === "AUTH_REQUIRED" ? "IA non activée. Cliquez sur le bouton jaune." : "Erreur d'analyse document.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  return (
    <div className="h-[100dvh] bg-nsp-bg flex flex-col w-full absolute inset-0 z-50">
      <div className="p-4 flex items-center justify-between bg-nsp-card border-b border-nsp-border pt-safe-top">
        <button onClick={onCancel} className="text-nsp-sub p-2"><X size={24} /></button>
        <h2 className="text-sm font-black text-white uppercase tracking-widest">Nouveau Document</h2>
        <div className="w-6"></div>
      </div>

      <div className="flex-1 p-4 overflow-y-auto pb-32">
        <div className="flex bg-nsp-input p-1 rounded-2xl mb-6">
          <button onClick={() => setActiveTab('maintenance')} className={`flex-1 py-4 rounded-xl flex items-center justify-center gap-2 font-black text-[10px] uppercase tracking-widest ${activeTab === 'maintenance' ? 'bg-nsp-primary text-white shadow-lg' : 'text-gray-500'}`}><Wrench size={16} /> Entretien</button>
          <button onClick={() => setActiveTab('fuel')} className={`flex-1 py-4 rounded-xl flex items-center justify-center gap-2 font-black text-[10px] uppercase tracking-widest ${activeTab === 'fuel' ? 'bg-nsp-primary text-white shadow-lg' : 'text-gray-500'}`}><Fuel size={16} /> Carburant</button>
        </div>

        <div className="mb-6">
          <div onClick={() => !isAnalyzing && cameraInputRef.current?.click()} className={`relative aspect-video rounded-[2rem] border-2 border-dashed flex flex-col items-center justify-center cursor-pointer overflow-hidden ${isSuccess ? 'border-nsp-success bg-nsp-success/5' : 'border-gray-700 bg-nsp-input'}`}>
            {imagePreview ? <img src={imagePreview} className="absolute inset-0 w-full h-full object-cover opacity-30" /> : null}
            <div className="z-10 flex flex-col items-center gap-3">
              {isAnalyzing ? <Loader2 className="animate-spin text-nsp-primary" size={32} /> : isSuccess ? <div className="bg-nsp-success text-white px-4 py-2 rounded-full font-black text-[10px] uppercase tracking-widest flex items-center gap-2"><Check size={14}/> Analyse Réussie</div> : <><Camera size={32} className="text-gray-600" /><span className="text-[10px] font-black text-gray-500 uppercase">Scanner Facture</span></>}
            </div>
          </div>
        </div>

        {!hasApiKey && (
          <div className="mb-6 bg-yellow-500/10 border border-yellow-500/20 p-5 rounded-[2rem] text-center space-y-4 shadow-xl">
            <Key className="text-yellow-500 mx-auto" size={24} />
            <p className="text-[10px] font-black text-white uppercase tracking-widest">Activation IA Requise</p>
            <button onClick={handleActivateIA} className="w-full bg-yellow-500 text-black font-black py-4 rounded-2xl text-[10px] uppercase tracking-widest active:scale-95 transition-transform">ACTIVER MON IA MAINTENANT</button>
            <a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" className="text-[8px] text-gray-500 underline uppercase block">Infos Facturation Gemini</a>
          </div>
        )}

        <div className="space-y-5">
          <div>
            <label className="text-[9px] text-gray-600 font-black uppercase mb-2 block tracking-widest ml-1">Titre de la facture</label>
            <input type="text" className="w-full bg-nsp-input border border-nsp-border rounded-2xl px-6 py-5 text-white font-bold text-sm focus:border-nsp-primary outline-none" value={formData.title} onChange={e => setFormData({...formData, title: e.target.value})} placeholder="Ex: Vidange Garage Central..." />
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="text-[9px] text-gray-600 font-black uppercase mb-2 block tracking-widest ml-1">Kilométrage</label>
              <input type="number" className="w-full bg-nsp-input border border-nsp-border rounded-2xl px-6 py-5 text-white font-bold text-sm focus:border-nsp-primary outline-none" value={formData.km} onChange={e => setFormData({...formData, km: e.target.value})} placeholder="0" />
            </div>
            <div>
              <label className="text-[9px] text-gray-600 font-black uppercase mb-2 block tracking-widest ml-1">Prix TTC (€)</label>
              <input type="number" className="w-full bg-nsp-input border border-nsp-border rounded-2xl px-6 py-5 text-white font-bold text-sm focus:border-nsp-primary outline-none" value={formData.price} onChange={e => setFormData({...formData, price: e.target.value})} placeholder="0.00" />
            </div>
          </div>
        </div>

        {detectedSpecs && (
          <div className="mt-8 bg-nsp-primary/5 border border-nsp-primary/10 p-6 rounded-[2.5rem] animate-slide-up">
            <h3 className="text-[10px] font-black text-white uppercase tracking-widest mb-4 flex items-center gap-2"><HardDrive size={16} /> Mémoire Technique Extrâite</h3>
            <div className="grid grid-cols-2 gap-3">
              {Object.entries(detectedSpecs).map(([k, v]) => v && (
                <div key={k} className="bg-black/40 p-3 rounded-xl border border-white/5">
                  <p className="text-[8px] text-gray-500 uppercase font-black mb-1">{k}</p>
                  <p className="text-[10px] text-white font-bold truncate">{v}</p>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      <div className="p-4 bg-nsp-card border-t border-nsp-border fixed bottom-0 w-full pb-safe-bottom z-50">
        <button onClick={() => onSave({ id: Date.now().toString(), carId, type: activeTab, title: formData.title, date: formData.date, km: Number(formData.km), price: Number(formData.price), volume: Number(formData.volume), imageUrl: finalBase64 || undefined }, detectedSpecs)} className="w-full bg-nsp-primary text-white font-black py-5 rounded-[2rem] text-[11px] uppercase tracking-[0.3em] shadow-[0_20px_40px_rgba(230,57,70,0.3)]">Enregistrer dans le Garage</button>
      </div>

      <input type="file" ref={cameraInputRef} className="hidden" capture="environment" onChange={handleFile} />
    </div>
  );
};

