        </div>

        {analysisError && (
           <div className="mb-6 bg-red-950/40 border border-red-500/30 p-5 rounded-[2rem] flex items-center gap-4 text-red-200 animate-slide-up">
             <AlertTriangle size={24} className="shrink-0 text-red-500" />
