import React, { useState, useEffect } from 'react';
import { Screen, User, Car, Invoice, TechnicalSpecs } from './types';
import { AuthScreen } from './components/AuthScreen';
import { OnboardingScreen } from './components/OnboardingScreen';
import { DashboardScreen } from './components/DashboardScreen';
import { GarageScreen } from './components/GarageScreen';
import { AddInvoiceScreen } from './components/AddInvoiceScreen';
import { AssistanceScreen } from './components/AssistanceScreen';
import { AdminDashboardScreen } from './components/AdminDashboardScreen';
import { InvoicesListScreen } from './components/InvoicesListScreen';
import { PaymentModal, PurchaseType } from './components/PaymentModal';
import { db } from './services/storageService'; 
import { cloud } from './services/cloudService';
import { Cloud, Loader2 } from 'lucide-react';

const App: React.FC = () => {
  const [screen, setScreen] = useState<Screen>(Screen.AUTH);
  const [user, setUser] = useState<User | null>(null);
  const [allUsers, setAllUsers] = useState<User[]>([]);
  const [allCars, setAllCars] = useState<Car[]>([]);
  const [allInvoices, setAllInvoices] = useState<Invoice[]>([]);
  const [isDatabaseReady, setIsDatabaseReady] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [showPayment, setShowPayment] = useState<PurchaseType | null>(null);
  const [activeCarId, setActiveCarId] = useState<string | null>(null);

  const loadAllData = async () => {
    try {
      const localUsers = db.users.getAll();
      const localCars = db.cars.getAll();
      const localInvoices = db.invoices.getAll();
      setAllUsers(localUsers);
      setAllCars(localCars);
      setAllInvoices(localInvoices);
      if (cloud.isConnected()) {
        const remoteUsers = await cloud.fetchAllUsers();
        if (remoteUsers && remoteUsers.length > 0) setAllUsers(remoteUsers);
      }
    } catch (e) {
      console.warn("Sync Cloud off.");
    } finally {
      setIsDatabaseReady(true);
    }
  };

  useEffect(() => {
    const initApp = async () => {
      await loadAllData();
      const sessionId = db.session.get();
      if (sessionId) {
        const currentUsers = db.users.getAll();
        const foundUser = currentUsers.find(u => u.id === sessionId);
        if (foundUser) {
          setUser(foundUser);
          if (foundUser.role === 'admin') setScreen(Screen.ADMIN_DASHBOARD);
          else {
            const savedCarId = localStorage.getItem('AUTOBOOK_ACTIVE_CAR');
            if (savedCarId) {
                setActiveCarId(savedCarId);
                setScreen(Screen.GARAGE);
            } else setScreen(Screen.GARAGE);
          }
        }
      }
    };
    initApp();
  }, []);

  const handleLogin = async (loggedInUser: User) => {
    setIsSyncing(true);
    try {
      await cloud.syncUser(loggedInUser);
      setUser(loggedInUser);
      db.session.set(loggedInUser.id);
      const currentUsers = db.users.getAll();
      if (!currentUsers.some(u => u.id === loggedInUser.id)) db.users.saveAll([...currentUsers, loggedInUser]);
      setScreen(loggedInUser.role === 'admin' ? Screen.ADMIN_DASHBOARD : Screen.GARAGE);
    } catch (e) {
      console.error("Login failed:", e);
    } finally {
      setTimeout(() => setIsSyncing(false), 800);
    }
  };

  const handleSaveInvoice = (inv: Invoice, specs?: TechnicalSpecs) => {
    const updatedInvoices = [inv, ...allInvoices];
    setAllInvoices(updatedInvoices);
    db.invoices.saveAll(updatedInvoices);
    if (specs && activeCarId) {
      const updated = allCars.map(c => {
        if (c.id === activeCarId) return { ...c, specs: { ...(c.specs || {}), ...specs } };
        return c;
      });
      setAllCars(updated);
      db.cars.saveAll(updated);
    }
    setScreen(Screen.INVOICES_LIST);
  };

  return (
    <div className="max-w-md mx-auto bg-nsp-bg shadow-2xl h-[100dvh] relative overflow-y-auto">
      {isSyncing && (
        <div className="fixed top-6 right-6 z-[110] bg-black/80 text-white px-4 py-2 rounded-full text-[10px] font-black uppercase tracking-widest flex items-center gap-2 border border-white/10 shadow-2xl backdrop-blur-xl animate-fade-in">
           <Cloud size={14} className="text-green-500 animate-pulse" /> <span>Sync Cloud</span>
        </div>
      )}

      {!isDatabaseReady ? (
        <div className="h-full flex flex-col items-center justify-center space-y-6">
           <Loader2 className="animate-spin text-nsp-primary" size={48} />
           <p className="text-gray-500 text-[10px] font-black uppercase tracking-widest">Chargement...</p>
        </div>
      ) : (
        <>
         {screen === Screen.AUTH && <AuthScreen onLogin={handleLogin} onForgotPasswordRequest={(e) => !!allUsers.find(x => x.email.toLowerCase() === e.toLowerCase())} existingUsers={allUsers} />}
         {screen === Screen.ADMIN_DASHBOARD && <AdminDashboardScreen currentUser={user!} allUsers={allUsers} allCars={allCars} allInvoices={allInvoices} onLogout={() => { setUser(null); db.session.clear(); setScreen(Screen.AUTH); }} onUpdateUser={(u) => setAllUsers(prev => prev.map(x => x.id === u.id ? u : x))} onDeleteUser={(id) => setAllUsers(prev => prev.filter(u => u.id !== id))} onRefresh={loadAllData} />}
         {screen === Screen.GARAGE && <GarageScreen user={user!} cars={allCars.filter(c => c.ownerId === user?.id)} invoices={allInvoices} onSelectCar={(id) => { setActiveCarId(id); localStorage.setItem('AUTOBOOK_ACTIVE_CAR', id); setScreen(Screen.DASHBOARD); }} onViewInvoices={(id) => { setActiveCarId(id); setScreen(Screen.INVOICES_LIST); }} onAddCar={() => setScreen(Screen.ONBOARDING)} onLogout={() => { setUser(null); db.session.clear(); setScreen(Screen.AUTH); }} />}
         {screen === Screen.ONBOARDING && <OnboardingScreen onSave={(c) => { 
           const carWithId = { ...c, ownerId: user!.id };
           const updatedCars = [...allCars, carWithId];
           setAllCars(updatedCars);
           db.cars.saveAll(updatedCars);
           setActiveCarId(c.id);
           setScreen(Screen.DASHBOARD);
         }} onCancel={() => setScreen(Screen.GARAGE)} canUseSiv={!!(user?.isPremium || user?.hasSivAccess)} onRequireSiv={() => setShowPayment('siv')} />}
         {screen === Screen.DASHBOARD && activeCarId && <DashboardScreen user={user!} car={allCars.find(c => c.id === activeCarId)!} invoices={allInvoices.filter(i => i.carId === activeCarId)} aiStatus={{status:'neutral', message:''}} onBackToGarage={() => setScreen(Screen.GARAGE)} onAddInvoice={() => setScreen(Screen.ADD_INVOICE)} onSellCar={() => {}} onBuyCar={() => {}} onAssistance={() => setScreen(Screen.ASSISTANCE)} onDeleteCar={() => {}} onUpdateSpecs={() => {}} onUpdateCar={() => {}} onDeleteInvoice={(id) => setAllInvoices(prev => prev.filter(i => i.id !== id))} />}
         {screen === Screen.ADD_INVOICE && <AddInvoiceScreen carId={activeCarId!} onSave={handleSaveInvoice} onCancel={() => setScreen(Screen.DASHBOARD)} />}
         {screen === Screen.ASSISTANCE && <AssistanceScreen onBack={() => setScreen(Screen.DASHBOARD)} canUseAssistance={!!(user?.isPremium || user?.hasAssistanceAccess)} onRequireAccess={() => setShowPayment('assistance')} />}
         {screen === Screen.INVOICES_LIST && activeCarId && <InvoicesListScreen car={allCars.find(c => c.id === activeCarId)!} invoices={allInvoices.filter(i => i.carId === activeCarId)} onBack={() => setScreen(Screen.GARAGE)} onAdd={() => setScreen(Screen.ADD_INVOICE)} onDelete={(id) => { const updated = allInvoices.filter(i => i.id !== id); setAllInvoices(updated); db.invoices.saveAll(updated); }} />}
        </>
      )}

      {showPayment && <PaymentModal feature={showPayment} onClose={() => setShowPayment(null)} onSuccess={(t) => {
        if(!user) return;
        const u = {...user};
        if(t === 'premium') u.isPremium = true;
        else if(t === 'siv') u.hasSivAccess = true;
        else u.hasAssistanceAccess = true;
        handleLogin(u);
        setShowPayment(null);
      }} />}
    </div>
  );
};

export default App;

import { defineConfig, loadEnv } from 'vite';
import react from '@vitejs/plugin-react';
import process from 'node:process';

export default defineConfig(({ mode }) => {
  // Charge les variables .env en local + les variables d'environnement Vercel
  // Use process.cwd() to correctly obtain the current working directory in a Node environment.
  const env = loadEnv(mode, process.cwd(), '');

  // On priorise la variable de l'environnement de build
  // Use process.env to ensure consistent access to build-time environment variables.
  const apiKey = env.API_KEY || process.env.API_KEY;

  return {
    plugins: [react()],
    define: {
      // Remplace toutes les occurrences de process.env.API_KEY par la valeur réelle pour le frontend
      'process.env.API_KEY': JSON.stringify(apiKey),
    },
    build: {
      chunkSizeWarningLimit: 2500,
      rollupOptions: {
        output: {
          manualChunks: {
            'gemini-vendor': ['@google/genai'],
            'react-vendor': ['react', 'react-dom'],
            'icons-vendor': ['lucide-react'],
          },
        },
      },
    },
  };
});

import React, { useState, useRef } from 'react';
import { Invoice, TechnicalSpecs } from '../types';
import { Loader2, X, Check, Camera, Zap, AlertTriangle, Fuel, Wrench, RefreshCw, FileText, Info } from 'lucide-react';
import { analyzeInvoiceImage, processFile } from '../services/geminiService';

interface AddInvoiceScreenProps {
  carId: string;
  onSave: (invoice: Invoice, detectedSpecs?: TechnicalSpecs) => void;
  onCancel: () => void;
}

export const AddInvoiceScreen: React.FC<AddInvoiceScreenProps> = ({ carId, onSave, onCancel }) => {
  const [activeTab, setActiveTab] = useState<'maintenance' | 'fuel'>('maintenance');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);
  const [analysisError, setAnalysisError] = useState<string | null>(null);
  const [persistentImage, setPersistentImage] = useState<string | null>(null);
  const [currentMimeType, setCurrentMimeType] = useState<string>('image/jpeg');
  const [detectedSpecs, setDetectedSpecs] = useState<TechnicalSpecs | undefined>(undefined);

  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState({
    title: '',
    date: new Date().toISOString().split('T')[0],
    km: '',
    price: '',
    volume: ''
  });

  const performAnalysis = async (base64DataUrl: string, mime: string) => {
    setIsAnalyzing(true);
    setIsSuccess(false);
    setAnalysisError(null);

    try {
      // On extrait la partie pure base64 pour l'API Gemini
      const pureBase64 = base64DataUrl.split(',')[1];
      const result = await analyzeInvoiceImage(pureBase64, mime);

      if (result) {
        setIsSuccess(true);
        setActiveTab(result.type === 'fuel' ? 'fuel' : 'maintenance');
        setFormData({
          title: result.title || '',
          date: result.date || new Date().toISOString().split('T')[0],
          km: result.km?.toString() || '',
          price: result.price?.toString() || '',
          volume: result.volume?.toString() || ''
        });
        setDetectedSpecs(result.specs);
      }
    } catch (error: any) {
      console.error("AI Analysis Failed:", error);
      setAnalysisError("L'IA n'a pas pu lire le document. Vérifiez la netteté de la photo.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const mime = file.type;
    setCurrentMimeType(mime);
    setIsAnalyzing(true);
    setAnalysisError(null);

    try {
      // Transformation en Base64 permanent et compressé
      const base64DataUrl = await processFile(file);
      setPersistentImage(base64DataUrl);

      // Analyse par l'IA
      await performAnalysis(base64DataUrl, mime);
    } catch (error: any) {
      setIsAnalyzing(false);
      setAnalysisError("Impossible de traiter ce fichier.");
    }
  };

  const handleSubmit = () => {
    if (!carId) return;
    const newInvoice: Invoice = {
      id: Date.now().toString(),
      carId,
      type: activeTab,
      title: formData.title || (activeTab === 'fuel' ? 'Plein Carburant' : 'Entretien'),
      date: formData.date,
      km: parseInt(formData.km) || 0,
      price: parseFloat(formData.price) || 0,
      volume: activeTab === 'fuel' ? parseFloat(formData.volume) || 0 : undefined,
      imageUrl: persistentImage || undefined, // On sauvegarde le Base64 permanent
      detectedSpecs
    };
    onSave(newInvoice, detectedSpecs);
  };

  return (
    <div className="h-[100dvh] bg-nsp-bg flex flex-col w-full absolute inset-0 z-50 overflow-hidden">
      <div className="p-4 flex items-center justify-between bg-nsp-card border-b border-nsp-border shrink-0 pt-safe-top">
        <button onClick={onCancel} className="text-nsp-sub p-2"><X size={24} /></button>
        <h2 className="text-sm font-black text-white uppercase tracking-widest">Scanner Document</h2>
        <div className="w-6"></div>
      </div>

      <div className="flex-1 p-4 overflow-y-auto pb-32">
        <div className="flex bg-nsp-input p-1 rounded-2xl mb-6">
          <button 
            onClick={() => setActiveTab('maintenance')}
            className={`flex-1 py-4 rounded-xl flex items-center justify-center gap-2 font-black text-[10px] uppercase tracking-widest transition-all ${activeTab === 'maintenance' ? 'bg-nsp-primary text-white shadow-lg' : 'text-gray-500'}`}
          >
            <Wrench size={16} /> Maintenance
          </button>
          <button 
            onClick={() => setActiveTab('fuel')}
            className={`flex-1 py-4 rounded-xl flex items-center justify-center gap-2 font-black text-[10px] uppercase tracking-widest transition-all ${activeTab === 'fuel' ? 'bg-nsp-primary text-white shadow-lg' : 'text-gray-500'}`}
          >
            <Fuel size={16} /> Carburant
          </button>
        </div>

        <div className="mb-6">
          <div 
            onClick={() => !isAnalyzing && fileInputRef.current?.click()}
            className={`relative aspect-[3/4] rounded-[2.5rem] border-2 border-dashed flex flex-col items-center justify-center overflow-hidden cursor-pointer transition-all ${isSuccess ? 'border-nsp-success bg-nsp-success/5' : analysisError ? 'border-red-500/30 bg-red-950/10' : 'border-gray-700 bg-nsp-input'}`}
          >
            {persistentImage && (
              <img src={persistentImage} className="absolute inset-0 w-full h-full object-cover" alt="Scan Document" />
            )}

            <div className={`z-10 flex flex-col items-center gap-3 ${persistentImage ? 'bg-black/60 p-6 rounded-3xl backdrop-blur-sm' : ''}`}>
              {isAnalyzing ? (
                <div className="flex flex-col items-center gap-4">
                  <div className="relative">
                    <Loader2 className="animate-spin text-nsp-primary" size={48} />
                    <Zap className="absolute inset-0 m-auto text-nsp-primary animate-pulse" size={16} />
                  </div>
                  <span className="text-[11px] font-black text-white uppercase tracking-[0.3em] animate-pulse">Lecture IA...</span>
                </div>
              ) : isSuccess ? (
                <div className="bg-nsp-success text-white px-8 py-4 rounded-full font-black text-[11px] uppercase tracking-widest flex items-center gap-3 shadow-2xl">
                  <Check size={20} /> Analyse OK
                </div>
              ) : (
                <>
                  <div className="w-16 h-16 rounded-full bg-nsp-bg flex items-center justify-center border border-white/5 shadow-2xl mb-2">
                    <Camera size={32} className="text-gray-600" />
                  </div>
                  <span className="text-[10px] font-black text-gray-500 uppercase tracking-widest text-center">Photographier la facture</span>
                </>
              )}
            </div>
          </div>

          {persistentImage && !isAnalyzing && (
            <button 
              onClick={() => performAnalysis(persistentImage, currentMimeType)}
              className="mt-4 w-full bg-nsp-primary/10 text-nsp-primary border border-nsp-primary/20 py-4 rounded-2xl text-[10px] font-black uppercase flex items-center justify-center gap-2 transition-transform active:scale-95"
            >
              <RefreshCw size={14} /> Ré-analyser par l'IA
            </button>
          )}
        </div>

        {analysisError && (
           <div className="mb-6 bg-red-950/40 border border-red-500/30 p-5 rounded-[2rem] flex items-center gap-4 text-red-200">
              <AlertTriangle size={24} className="shrink-0 text-red-500" />
              <p className="text-[10px] font-black uppercase tracking-widest leading-tight">{analysisError}</p>
           </div>
        )}

        <div className="space-y-6">
          <div className="bg-nsp-card p-5 rounded-3xl border border-nsp-border space-y-4">
            <div>
              <label className="text-[9px] text-gray-600 font-black uppercase mb-2 ml-1 block tracking-widest">Établissement / Garage</label>
              <input 
                type="text" 
                className="w-full bg-nsp-input border border-transparent rounded-2xl px-6 py-4 text-white font-bold text-sm focus:border-nsp-primary outline-none" 
                value={formData.title} 
                onChange={e => setFormData({...formData, title: e.target.value})} 
                placeholder="Ex: Neo Service Pneu..." 
              />
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-[9px] text-gray-600 font-black uppercase mb-2 ml-1 block tracking-widest">Kilométrage</label>
                <input 
                  type="number" 
                  className="w-full bg-nsp-input border border-transparent rounded-2xl px-6 py-4 text-white font-bold text-sm focus:border-nsp-primary outline-none" 
                  value={formData.km} 
                  onChange={e => setFormData({...formData, km: e.target.value})} 
                />
              </div>
              <div>
                <label className="text-[9px] text-gray-600 font-black uppercase mb-2 ml-1 block tracking-widest">Total (€)</label>
                <input 
                  type="number" 
                  className="w-full bg-nsp-input border border-transparent rounded-2xl px-6 py-4 text-white font-bold text-sm focus:border-nsp-primary outline-none" 
                  value={formData.price} 
                  onChange={e => setFormData({...formData, price: e.target.value})} 
                />
              </div>
            </div>
          </div>
        </div>
      </div>

      <div className="p-4 bg-nsp-card border-t border-nsp-border fixed bottom-0 w-full pb-safe-bottom z-40">
        <button 
          onClick={handleSubmit} 
          disabled={isAnalyzing || !persistentImage}
          className="w-full bg-nsp-primary text-white font-black py-5 rounded-[2.5rem] text-[12px] uppercase tracking-[0.3em] shadow-[0_20px_40px_rgba(230,57,70,0.3)] disabled:opacity-50"
        >
