  const toggleNotifications = async () => {
    if (notifEnabled) {
      setNotifEnabled(false);
      // On ne peut pas révoquer au niveau OS via JS, mais on désactive l'intérêt applicatif
    } else {
      const granted = await requestNotificationPermission();
