class CloudConnector {
  private static instance: CloudConnector;
  private constructor() {}

  public static getInstance(): CloudConnector {
    if (!CloudConnector.instance) {
      CloudConnector.instance = new CloudConnector();
    }
    return CloudConnector.instance;
  }

  public isConnected(): boolean {
    return isRealFirebase && !apiNeedsActivation;
  }

  public isApiDisabled(): boolean {
    return apiNeedsActivation;
  }

  public resetActivationFlag(): void {
    apiNeedsActivation = false;
    localStorage.removeItem(API_DISABLED_KEY);
  }

  private markApiDisabled(): void {
    apiNeedsActivation = true;
    localStorage.setItem(API_DISABLED_KEY, 'true');
  }

  // --- UTILISATEURS ---
  async syncUser(user: User): Promise<void> {
    if (!this.isConnected()) return;
    try {
        const userRef = doc(db, "users", user.id);
        await setDoc(userRef, { ...user, lastSync: Timestamp.now() }, { merge: true });
    } catch (e: any) { this.markApiDisabled(); }
  }

  async fetchAllUsers(): Promise<User[]> {
    if (!this.isConnected()) return [];
    try {
        const querySnapshot = await getDocs(collection(db, "users"));
        return querySnapshot.docs.map(doc => ({ ...doc.data(), id: doc.id } as User));
    } catch (e: any) { return []; }
  }

  async deleteUser(userId: string): Promise<void> {
    if (!this.isConnected()) return;
    try { await deleteDoc(doc(db, "users", userId)); } catch (e: any) {}
  }

  // --- VÉHICULES ---
  async syncCar(car: Car): Promise<void> {
    if (!this.isConnected()) return;
    try {
      await setDoc(doc(db, "cars", car.id), { ...car, lastSync: Timestamp.now() }, { merge: true });
    } catch (e) { console.error("Sync Car Error", e); }
  }

  async fetchUserCars(userId: string): Promise<Car[]> {
    if (!this.isConnected()) return [];
    try {
      const q = query(collection(db, "cars"), where("ownerId", "==", userId));
      const snap = await getDocs(q);
      return snap.docs.map(d => d.data() as Car);
    } catch (e) { return []; }
  }

  // --- FACTURES ---
  async syncInvoice(invoice: Invoice): Promise<void> {
    if (!this.isConnected()) return;
    try {
      await setDoc(doc(db, "invoices", invoice.id), { ...invoice, lastSync: Timestamp.now() }, { merge: true });
    } catch (e) { console.error("Sync Invoice Error", e); }
  }

  async fetchUserInvoices(userId: string): Promise<Invoice[]> {
    if (!this.isConnected()) return [];
    try {
      // On récupère toutes les factures, le filtrage par carId se fera côté client ou via query complexe
      // Pour la démo et simplicité, on récupère tout ce qui appartient aux voitures du user
      const snap = await getDocs(collection(db, "invoices"));
      return snap.docs.map(d => d.data() as Invoice);
    } catch (e) { return []; }
  }

  async deleteInvoice(invoiceId: string): Promise<void> {
    if (!this.isConnected()) return;
    try { await deleteDoc(doc(db, "invoices", invoiceId)); } catch (e) {}
  }

  listenToAllUsers(callback: (users: User[]) => void) {
    if (!this.isConnected()) return null;
    return onSnapshot(collection(db, "users"), (snapshot) => {
      callback(snapshot.docs.map(doc => doc.data() as User));
    });
  }
}

