import { GoogleGenAI, Type } from "@google/genai";
import { Car, ManufacturerSpecs, TechnicalSpecs } from "../types";

export const processFile = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();

    reader.onload = (e) => {
      const result = e.target?.result as string;

      if (file.type === 'application/pdf' || file.name.toLowerCase().endsWith('.pdf')) {
        resolve(result);
        return;
      }

      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement('canvas');
        // Réduction optimisée pour éviter les crashs mémoire sur mobile
        const MAX_SIZE = 800; 
        let width = img.width;
        let height = img.height;

        if (width > height && width > MAX_SIZE) {
          height *= MAX_SIZE / width;
          width = MAX_SIZE;
        } else if (height > MAX_SIZE) {
          width *= MAX_SIZE / height;
          height = MAX_SIZE;
        }

        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.drawImage(img, 0, 0, width, height);
          // Qualité 0.5 : bon compromis lisibilité / poids Base64
          resolve(canvas.toDataURL('image/jpeg', 0.5));
        } else {
          resolve(result);
        }
      };
      img.onerror = () => resolve(result);
      img.src = result;
    };

    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

export const safeBase64ToBlobUrl = (base64Data: string): string => {
  if (!base64Data) return "";
  if (base64Data.startsWith('data:')) return base64Data;
  // Détection auto si c'est du PDF ou Image pour le préfixe
  const isPDF = base64Data.length > 100 && base64Data.substring(0, 10).includes('JVBER');
  const prefix = isPDF ? 'data:application/pdf;base64,' : 'data:image/jpeg;base64,';
  return `${prefix}${base64Data}`;
};

