 * Système de persistance renforcé. Les clés sont fixes pour garantir la survie aux updates.
 */

const KEYS = {
  USERS: 'AUTOBOOK_USERS_STABLE', 
  CARS: 'AUTOBOOK_CARS_STABLE',
  INVOICES: 'AUTOBOOK_INVOICES_STABLE',
  SESSION: 'AUTOBOOK_SESSION_STABLE',
  LAST_EMAIL: 'AUTOBOOK_LAST_KNOWN_EMAIL'
};

