          if (rememberMe) localStorage.setItem('AUTOBOOK_CREDS', JSON.stringify({ email, password }));
          onLogin(foundUser);
        } else if (isAdminMode && email === 'neoservicepneu31@gmail.com' && password === 'PAM180279') {
          onLogin({ id: 'admin-001', name: 'Administrateur', email, role: 'admin' });
        } else {
          setError("Identifiants incorrects.");
        }
      } else {
        if (foundUser) {
          setError("Email déjà utilisé.");
        } else {
          onLogin({ id: 'u-' + Date.now(), name, email, password, role: 'user', isValidated: true });
        }
      }
    }, 800);
  };

  return (
    <div className="flex-1 w-full bg-black flex flex-col overflow-y-auto min-h-full pb-10">
