             <button onClick={() => setMode('login')} className={`flex-1 py-2 text-[10px] font-black uppercase rounded-lg transition-all ${mode === 'login' ? 'bg-nsp-card text-white' : 'text-gray-500'}`}>Connexion</button>
             <button onClick={() => setMode('register')} className={`flex-1 py-2 text-[10px] font-black uppercase rounded-lg transition-all ${mode === 'register' ? 'bg-nsp-card text-white' : 'text-gray-500'}`}>Inscription</button>
