          <form onSubmit={handleSubmit} className="space-y-4">
            {mode === 'register' && (
              <input type="text" placeholder="NOM COMPLET" value={name} onChange={e => setName(e.target.value)} className="w-full bg-nsp-input border border-transparent focus:border-nsp-primary rounded-xl px-4 py-3 text-white text-xs font-bold outline-none" required />
            )}
            <input type="email" placeholder="EMAIL" value={email} onChange={e => setEmail(e.target.value)} className="w-full bg-nsp-input border border-transparent focus:border-nsp-primary rounded-xl px-4 py-3 text-white text-xs font-bold outline-none" required />
            <input type="password" placeholder="MOT DE PASSE" value={password} onChange={e => setPassword(e.target.value)} className="w-full bg-nsp-input border border-transparent focus:border-nsp-primary rounded-xl px-4 py-3 text-white text-xs font-bold outline-none" required />

