/**
 * Nettoie récursivement un objet pour supprimer les clés dont la valeur est 'undefined'.
 * Firestore rejette les 'undefined' mais accepte les 'null'.
 */
const cleanData = (obj: any): any => {
  if (obj === null || typeof obj !== 'object' || obj instanceof Timestamp) {
    return obj;
  }

  if (Array.isArray(obj)) {
    return obj.map(item => cleanData(item)).filter(item => item !== undefined);
  }

  const newObj: any = {};
  for (const key in obj) {
    if (Object.prototype.hasOwnProperty.call(obj, key)) {
      const val = obj[key];
      if (val !== undefined) {
        newObj[key] = cleanData(val);
      }
    }
  }
  return newObj;
};

