                         <p className="text-white text-3xl font-black">{specs?.tirePressureFront || '2.3 bar'}</p>
                       </div>
                       <div className="w-16 h-16 bg-blue-500/10 rounded-2xl flex items-center justify-center text-blue-400">
                          <Gauge size={32} />
                       </div>
                    </div>
                    <div className="bg-nsp-input p-6 rounded-3xl border border-white/5 flex items-center justify-between shadow-inner">
                       <div>
                         <h4 className="text-blue-400 font-black text-[10px] uppercase mb-1 tracking-widest">Pression Arrière</h4>
                         <p className="text-white text-3xl font-black">{specs?.tirePressureRear || '2.1 bar'}</p>
                       </div>
                       <div className="w-16 h-16 bg-blue-500/10 rounded-2xl flex items-center justify-center text-blue-400">
                          <Gauge size={32} />
                       </div>
                    </div>
                    <p className="text-[10px] text-gray-500 italic p-4 text-center leading-relaxed">Données issues de la base constructeur {car.name.split(' ')[0]}. Vérifier sur l'étiquette du montant de porte.</p>
                 </div>
               )}

               {activeReport === 'fluids' && (
                 <div className="space-y-4">
                    <div className="bg-nsp-input p-6 rounded-[2rem] border border-white/5 shadow-inner">
                       <h4 className="text-yellow-500 font-black text-[10px] uppercase mb-3 tracking-widest">Huile Moteur Recommandée</h4>
                       <div className="flex items-center gap-6">
                          <div className="w-16 h-16 bg-yellow-500/10 rounded-[1.5rem] flex items-center justify-center text-yellow-500"><Droplet size={32}/></div>
                          <div>
                             <p className="text-white font-black text-2xl tracking-tighter">{specs?.oilType || '5W30'}</p>
                             <p className="text-gray-500 text-[10px] uppercase font-black tracking-widest">Spécification Constructeur</p>
                          </div>
                       </div>
                    </div>
                    <div className="bg-nsp-input p-6 rounded-[2rem] border border-white/5 shadow-inner">
                       <h4 className="text-yellow-500 font-black text-[10px] uppercase mb-2 tracking-widest">Liquide Refroidissement</h4>
                       <p className="text-white font-black text-lg">{specs?.coolantType || 'Rose (G12/G13)'}</p>
                       <p className="text-gray-600 text-[9px] mt-1 font-bold uppercase tracking-widest">Contrôle à froid uniquement</p>
                    </div>
                 </div>
               )}
            </div>

            <button 
              onClick={() => setActiveReport(null)}
              className="w-full bg-nsp-primary text-white py-6 rounded-[2rem] font-black text-xs uppercase tracking-widest mt-10 shadow-xl active:scale-95 transition-all"
            >
               Fermer l'analyse
            </button>
          </div>
        </div>
      )}

      {/* --- UNIFIED DOCUMENT VIEWER (IMPROVED FOR PDF) --- */}
      {viewingInvoice && (
        <div className="fixed inset-0 z-[2000] bg-black/98 flex flex-col pt-safe-top animate-fade-in overflow-hidden">
          <header className="p-6 flex justify-between items-center bg-black/50 border-b border-white/10 z-[2001]">
             <button onClick={() => setViewingInvoice(null)} className="p-3 bg-nsp-input rounded-xl text-white hover:bg-nsp-primary transition-colors"><X size={24}/></button>
             <div className="text-center">
                <h3 className="text-white font-black text-xs uppercase tracking-[0.2em] truncate max-w-[150px]">{viewingInvoice.title}</h3>
                <p className="text-[9px] text-nsp-primary font-black uppercase mt-1 tracking-widest">Archive Numérique Certifiée</p>
