                      <FileText size={60} className="text-red-500 mb-4" />
                      <p className="text-white font-black text-[10px] uppercase tracking-widest">Visionneuse PDF Active</p>
                   </div>
                </div>
              ) : (
                <img 
                  src={safeBase64ToBlobUrl(viewingInvoice.imageUrl || '')} 
                  className="w-full h-full object-contain bg-[#050505]" 
