const wait = (ms: number) => new Promise(res => setTimeout(res, ms));

export const processFile = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();

    reader.onload = (e) => {
      const result = e.target?.result as string;

      // Si c'est un PDF, on garde le résultat tel quel mais on s'assure qu'il est bien formatté
      if (file.type === 'application/pdf' || file.name.toLowerCase().endsWith('.pdf')) {
        resolve(result);
        return;
      }

      // Pour les images, réduction de la résolution pour fluidité (MAX_SIZE à 1000px au lieu de 1200px)
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement('canvas');
        const MAX_SIZE = 1000; 
        let width = img.width;
        let height = img.height;

        if (width > height && width > MAX_SIZE) {
          height *= MAX_SIZE / width;
          width = MAX_SIZE;
        } else if (height > MAX_SIZE) {
          width *= MAX_SIZE / height;
          height = MAX_SIZE;
        }

        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        if (ctx) {
          ctx.imageSmoothingEnabled = true;
          ctx.imageSmoothingQuality = 'medium';
          ctx.drawImage(img, 0, 0, width, height);
          // Qualité 0.5 pour un excellent compromis poids/lisibilité
          resolve(canvas.toDataURL('image/jpeg', 0.5));
        } else {
          resolve(result);
        }
      };
      img.onerror = () => resolve(result);
      img.src = result;
    };

    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

export const safeBase64ToBlobUrl = (base64Data: string): string => {
  if (!base64Data) return "";
  if (base64Data.startsWith('data:')) return base64Data;

  try {
    const isPDF = base64Data.length > 20 && base64Data.substring(0, 30).includes('JVBER');
    const prefix = isPDF ? 'data:application/pdf;base64,' : 'data:image/jpeg;base64,';
    return `${prefix}${base64Data}`;
  } catch (e) {
    return base64Data;
  }
};

/**
 * Convertit un base64 pur en Blob URL réel pour contourner les limitations des balises embed/iframe sur mobile
 */
export const base64ToRealBlobUrl = (base64: string, mimeType: string = 'application/pdf'): string => {
  try {
    const sliceSize = 1024;
    const byteCharacters = atob(base64.includes(',') ? base64.split(',')[1] : base64);
    const bytesLength = byteCharacters.length;
    const slicesCount = Math.ceil(bytesLength / sliceSize);
    const byteArrays = new Array(slicesCount);

    for (let sliceIndex = 0; sliceIndex < slicesCount; ++sliceIndex) {
      const begin = sliceIndex * sliceSize;
      const end = Math.min(begin + sliceSize, bytesLength);
      const bytes = new Array(end - begin);
      for (let offset = begin, i = 0; offset < end; ++i, ++offset) {
        bytes[i] = byteCharacters[offset].charCodeAt(0);
      }
      byteArrays[sliceIndex] = new Uint8Array(bytes);
    }
    const blob = new Blob(byteArrays, { type: mimeType });
    return URL.createObjectURL(blob);
  } catch (e) {
    console.error("Blob conversion error", e);
    return base64;
  }
};

export const analyzeInvoiceImage = async (base64Data: string, mimeType: string = 'image/jpeg', retryCount = 0): Promise<any> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const finalMime = mimeType.includes('pdf') ? 'application/pdf' : 'image/jpeg';
  const pureBase64 = base64Data.includes(',') ? base64Data.split(',')[1] : base64Data;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: {
        parts: [
          { inlineData: { mimeType: finalMime, data: pureBase64 } },
          { text: `Extraire en JSON strict: { type, title, date (YYYY-MM-DD), km (entier), price (total), specs: { tireDimensions, oilViscosity, batteryRef } }` }
        ]
      },
      config: { responseMimeType: "application/json" }
    });
    return JSON.parse(response.text?.trim() || '{}');
  } catch (error: any) {
    if (error?.status === 429 && retryCount < 3) {
        await wait(2000 * (retryCount + 1));
        return analyzeInvoiceImage(base64Data, mimeType, retryCount + 1);
    }
    throw error;
  }
};

