                              <div className="w-1.5 h-1.5 rounded-full bg-nsp-success shadow-[0_0_5px_rgba(42,157,143,0.5)]"></div> {point}
                           </div>
                         )) : (
                           <p className="text-xs text-gray-500 italic">Analyse des points de contrôle en cours...</p>
                         )}
                      </div>
                   </div>
                 )}

                 {activeReport === 'tires' && (
                   <div className="space-y-4">
                      <div className="bg-nsp-input p-6 rounded-3xl border border-white/5 flex items-center justify-between shadow-inner">
                         <div>
                           <h4 className="text-blue-400 font-black text-[10px] uppercase mb-1 tracking-widest">Pression Avant</h4>
