                            <Gauge size={32} />
                         </div>
                      </div>
                      <div className="bg-nsp-input p-6 rounded-3xl border border-white/5 flex items-center justify-between shadow-inner">
                         <div>
                           <h4 className="text-blue-400 font-black text-[10px] uppercase mb-1 tracking-widest">Pression Arrière</h4>
                           <p className="text-white text-3xl font-black">{specs?.tirePressureRear || '2.1 bar'}</p>
                         </div>
                         <div className="w-16 h-16 bg-blue-500/10 rounded-2xl flex items-center justify-center text-blue-400">
                            <Gauge size={32} />
                         </div>
                      </div>
                      <p className="text-[10px] text-gray-500 italic p-4 text-center leading-relaxed">Données issues de la base constructeur {car.name.split(' ')[0]}. Vérifier sur l'étiquette du montant de porte.</p>
                   </div>
                 )}

                 {activeReport === 'fluids' && (
                   <div className="space-y-4">
                      <div className="bg-nsp-input p-6 rounded-[2rem] border border-white/5 shadow-inner">
                         <h4 className="text-yellow-500 font-black text-[10px] uppercase mb-3 tracking-widest">Huile Moteur Recommandée</h4>
                         <div className="flex items-center gap-6">
                            <div className="w-16 h-16 bg-yellow-500/10 rounded-[1.5rem] flex items-center justify-center text-yellow-500"><Droplet size={32}/></div>
