                    {activeReport === 'health' && (
                      <div className="space-y-4">
                        <div className="grid grid-cols-2 gap-4">
                           <div className="bg-nsp-input p-5 rounded-3xl border border-white/5">
                              <span className="text-gray-500 text-[9px] uppercase font-black block mb-1">Entretien</span>
                              <span className="text-white font-black text-lg">{specs?.maintenanceIntervalKm?.toLocaleString() || '20 000'} KM</span>
                           </div>
                           <div className="bg-nsp-input p-5 rounded-3xl border border-white/5">
                              <span className="text-gray-500 text-[9px] uppercase font-black block mb-1">Courroie</span>
                              <span className="text-white font-black text-lg">{specs?.timingBeltIntervalKm && specs.timingBeltIntervalKm > 0 ? `${specs.timingBeltIntervalKm.toLocaleString()} KM` : 'N/A'}</span>
                           </div>
                        </div>
                        <div className="bg-nsp-input p-5 rounded-3xl border border-white/5">
                           <p className="text-[10px] text-gray-500 font-black uppercase mb-3 tracking-widest">Checklist Officielle :</p>
