                                  <div className="w-1 h-1 rounded-full bg-nsp-success"></div> {point}
                               </div>
                             ))}
                           </div>
                        </div>
                      </div>
                    )}

                    {activeReport === 'tires' && (
                      <div className="grid grid-cols-2 gap-4">
                         <div className="bg-nsp-input p-6 rounded-3xl border border-white/5 flex flex-col items-center justify-center shadow-inner text-center">
                            <h4 className="text-blue-400 font-black text-[9px] uppercase mb-1 tracking-widest">Avant</h4>
                            <p className="text-white text-2xl font-black">{specs?.tirePressureFront || '2.3 bar'}</p>
