                            <p className="text-white text-2xl font-black">{specs?.tirePressureRear || '2.1 bar'}</p>
                         </div>
                      </div>
                    )}

                    {activeReport === 'fluids' && (
                      <div className="space-y-4">
                        <div className="bg-nsp-input p-6 rounded-3xl border border-white/5 flex items-center gap-5 shadow-inner">
                           <div className="w-14 h-14 bg-yellow-500/10 rounded-2xl flex items-center justify-center text-yellow-500"><Droplet size={28}/></div>
                           <div>
                              <p className="text-white font-black text-lg tracking-tight">{specs?.oilType || '5W30'}</p>
                              <p className="text-gray-500 text-[9px] uppercase font-black tracking-widest">Type Recommandé</p>
                           </div>
                        </div>
                      </div>
                    )}
                 </section>

                 {/* REAL HISTORY SECTION */}
                 <section className="space-y-4">
                    <h3 className="text-[10px] text-gray-500 font-black uppercase tracking-[0.2em] px-2 flex items-center gap-2">
                      <History size={14} className="text-nsp-primary" /> Historique des Interventions
