                                            </div>
                                            <p className="text-white font-black text-base">{item.specs.oilViscosity}</p>
                                         </div>
                                      </div>
                                   )}
                                   {item.specs.filterRefs && item.specs.filterRefs.some(f => f.toLowerCase().includes('huile')) && (
