    if (cloud.isConnected()) await cloud.syncUser(updatedUser);
  };

  const handleDeleteUser = async (userId: string) => {
    setIsSyncing(true);
    try {
      if (cloud.isConnected()) {
        const userCars = allCars.filter(c => c.ownerId === userId);
        for (const car of userCars) {
          const carInvoices = allInvoices.filter(i => i.carId === car.id);
          for (const inv of carInvoices) {
            await cloud.deleteInvoice(inv.id);
          }
          await cloud.deleteCar(car.id);
        }
        await cloud.deleteUser(userId);
      }
      const updatedLocalUsers = db.users.getAll().filter(u => u.id !== userId);
      db.users.saveAll(updatedLocalUsers);
      setAllUsers(updatedLocalUsers);
    } catch (e) {
      console.error("Suppression error", e);
    } finally {
      setIsSyncing(false);
    }
  };

  const handleSaveCar = async (car: Car) => {
    const updatedCars = [...allCars.filter(c => c.id !== car.id), car];
    setAllCars(updatedCars);
    db.cars.saveAll(updatedCars);
    if (cloud.isConnected()) await cloud.syncCar(car);
    if (user) performHealthChecks(updatedCars, allInvoices, user.email);
  };

  const handleSaveInvoice = async (inv: Invoice, specs?: TechnicalSpecs) => {
    const updatedInvoices = [inv, ...allInvoices];
    setAllInvoices(updatedInvoices);
    db.invoices.saveAll(updatedInvoices);
    if (cloud.isConnected()) await cloud.syncInvoice(inv);
    if (specs && activeCarId) {
      const car = allCars.find(c => c.id === activeCarId);
      if (car) {
        const updatedCar = { ...car, specs: { ...(car.specs || {}), ...specs } };
        await handleSaveCar(updatedCar);
      }
    }
    if (user) performHealthChecks(allCars, updatedInvoices, user.email);
    setScreen(Screen.INVOICES_LIST);
  };

  const handleDeleteInvoice = async (invoiceId: string) => {
    const updated = allInvoices.filter(i => i.id !== invoiceId);
    setAllInvoices(updated);
    db.invoices.saveAll(updated);
    if (cloud.isConnected()) {
      cloud.deleteInvoice(invoiceId).catch(err => console.error(err));
    }
  };

  return (
    <div className="max-w-md mx-auto bg-nsp-bg shadow-2xl min-h-[100dvh] flex flex-col overflow-x-hidden relative">
      {isSyncing && (
        <div className="fixed top-2 left-1/2 -translate-x-1/2 z-[3000] bg-nsp-primary text-white px-3 py-1.5 rounded-full text-[8px] font-black uppercase flex items-center gap-2 shadow-2xl border border-white/10 pointer-events-none animate-fade-in">
           <RefreshCw size={10} className="animate-spin" /> Protection Cloud Active
        </div>
      )}
      {!isDatabaseReady ? (
        <div className="flex-1 flex flex-col items-center justify-center space-y-4 p-10 bg-nsp-bg">
           <Loader2 className="animate-spin text-nsp-primary" size={40} />
           <p className="text-white font-black text-[10px] uppercase tracking-widest">Restauration du Garage...</p>
        </div>
      ) : (
        <div className="flex-1 flex flex-col w-full h-full min-h-full">
         {screen === Screen.AUTH && <AuthScreen onLogin={handleLogin} onForgotPasswordRequest={() => true} existingUsers={allUsers} />}
         {screen === Screen.GARAGE && <GarageScreen user={user!} cars={allCars} invoices={allInvoices} onSelectCar={(id) => { setActiveCarId(id); setScreen(Screen.DASHBOARD); }} onViewInvoices={(id) => { setActiveCarId(id); setScreen(Screen.INVOICES_LIST); }} onAddCar={() => setScreen(Screen.ONBOARDING)} onLogout={() => { setUser(null); db.session.clear(); setScreen(Screen.AUTH); }} onBuyCar={() => setScreen(Screen.BUY_CAR)} />}
         {screen === Screen.ADMIN_DASHBOARD && <AdminDashboardScreen currentUser={user!} allUsers={allUsers} allCars={allCars} allInvoices={allInvoices} onLogout={() => { setUser(null); db.session.clear(); setScreen(Screen.AUTH); }} onUpdateUser={handleUpdateUser} onDeleteUser={handleDeleteUser} onRefresh={() => loadAllData(user!)} />}
         {screen === Screen.DASHBOARD && activeCarId && <DashboardScreen user={user!} car={allCars.find(c => c.id === activeCarId)!} invoices={allInvoices.filter(i => i.carId === activeCarId)} aiStatus={{status:'neutral', message:''}} onBackToGarage={() => setScreen(Screen.GARAGE)} onAddInvoice={() => setScreen(Screen.ADD_INVOICE)} onSellCar={() => setScreen(Screen.SELL_CAR)} onBuyCar={() => {}} onAssistance={() => setScreen(Screen.ASSISTANCE)} onDeleteCar={() => {}} onUpdateSpecs={() => {}} onUpdateCar={() => {}} onDeleteInvoice={handleDeleteInvoice} />}
         {screen === Screen.ONBOARDING && <OnboardingScreen onSave={(c) => { handleSaveCar({...c, ownerId: user!.id}); setScreen(Screen.GARAGE); }} onCancel={() => setScreen(Screen.GARAGE)} canUseSiv={true} onRequireSiv={() => {}} />}
         {screen === Screen.ADD_INVOICE && <AddInvoiceScreen carId={activeCarId!} onSave={handleSaveInvoice} onCancel={() => setScreen(Screen.DASHBOARD)} />}
         {screen === Screen.INVOICES_LIST && activeCarId && <InvoicesListScreen car={allCars.find(c => c.id === activeCarId)!} invoices={allInvoices.filter(i => i.carId === activeCarId)} onBack={() => setScreen(Screen.DASHBOARD)} onAdd={() => setScreen(Screen.ADD_INVOICE)} onDelete={handleDeleteInvoice} />}
         {screen === Screen.SELL_CAR && activeCarId && <SellCarScreen car={allCars.find(c => c.id === activeCarId)!} invoices={allInvoices.filter(i => i.carId === activeCarId)} onCancel={() => setScreen(Screen.DASHBOARD)} onConfirmTransfer={handleTransferComplete} />}
         {screen === Screen.BUY_CAR && <BuyCarScreen onCancel={() => setScreen(Screen.GARAGE)} onImportSuccess={handleImportSuccess} />}
         {screen === Screen.ASSISTANCE && <AssistanceScreen onBack={() => setScreen(Screen.DASHBOARD)} canUseAssistance={true} onRequireAccess={() => {}} />}
        </div>
      )}
    </div>
  );
};
export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { User, Car, Invoice } from '../types';
import { cloud } from '../services/cloudService';
import { safeBase64ToBlobUrl, base64ToRealBlobUrl } from '../services/geminiService';
import { 
  BarChart3, Users, QrCode, Printer, Globe, Radio, Database, ExternalLink, AlertCircle, RefreshCcw,
  Loader2, Copy, Check, ShieldAlert, ChevronRight, MousePointer2, HardDrive, Plus, ShieldCheck, ArrowRight,
  Search, Info, Car as CarIcon, X, Smartphone, Globe2, Link, ExternalLink as OpenLink, Trash2, Key, History, Mail, Eye, LogOut, Clock, Wrench, UserPlus, FileText, Share2, Download, Image as ImageIcon, Maximize2, CloudUpload, CloudDownload
} from 'lucide-react';

interface AdminDashboardScreenProps {
  currentUser: User;
  allUsers: User[];
  allCars: Car[];
  allInvoices: Invoice[];
  onLogout: () => void;
  onUpdateUser: (user: User) => void;
  onDeleteUser: (userId: string) => void;
  onRefresh: () => void;
}

export const AdminDashboardScreen: React.FC<AdminDashboardScreenProps> = ({ 
  currentUser, allUsers, allCars, allInvoices, onLogout, onUpdateUser, onDeleteUser, onRefresh
}) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'diffusion' | 'users' | 'setup'>('overview');
  const [searchTerm, setSearchTerm] = useState('');
  const [cloudStatus, setCloudStatus] = useState<'online' | 'syncing' | 'warning' | 'error'>('online');
  const [isEmergencyAction, setIsEmergencyAction] = useState(false);
  const [copySuccess, setCopySuccess] = useState(false);
  const [selectedUser, setSelectedUser] = useState<User | null>(null);
  const [viewingDoc, setViewingDoc] = useState<{title: string, url: string} | null>(null);
  const [customDomain, setCustomDomain] = useState('autobook-zxwf.vercel.app');

  const isCloudActive = cloud.isConnected();
  const isApiDisabled = cloud.isApiDisabled();

  const isPDF = (url?: string) => {
    if (!url) return false;
    return url.includes('application/pdf') || url.substring(0, 30).includes('JVBER');
  };

  const publicUrl = useMemo(() => {
    let domain = customDomain.trim();
    if (!domain.startsWith('http')) domain = `https://${domain}`;
    return domain;
  }, [customDomain]);

  const qrCodeUrl = useMemo(() => {
    return `https://api.qrserver.com/v1/create-qr-code/?size=400x400&data=${encodeURIComponent(publicUrl)}&color=E63946&bgcolor=1E1E1E`;
  }, [publicUrl]);

  useEffect(() => {
    if (isApiDisabled) {
      setCloudStatus('error');
      return;
    }
    if (!isCloudActive) {
      setCloudStatus('warning');
      return;
    }
    const unsubscribe = cloud.listenToAllUsers(() => {
      setCloudStatus('syncing');
      onRefresh();
      setTimeout(() => setCloudStatus('online'), 1000);
    });
    return () => { if(unsubscribe) unsubscribe(); };
  }, [onRefresh, isCloudActive, isApiDisabled]);

  const handleCopyLink = () => {
    navigator.clipboard.writeText(publicUrl);
    setCopySuccess(true);
    setTimeout(() => setCopySuccess(false), 2000);
  };

  const handleReconnectCloud = () => {
    cloud.resetActivationFlag();
    window.location.reload();
  };

  // NOUVEAUTÉ : RESTAURATION D'URGENCE
  const handleForcePushToCloud = async () => {
    if (!confirm("🚨 ACTION CRITIQUE : Cette opération va forcer l'envoi de TOUS les utilisateurs locaux vers Firebase.\n\nUtilisez cela si vous voyez des utilisateurs ici mais qu'ils ont disparu du Cloud.\n\nContinuer ?")) return;

    setIsEmergencyAction(true);
    try {
      for (const u of allUsers) {
        await cloud.syncUser(u);
      }
      for (const c of allCars) {
        await cloud.syncCar(c);
      }
      alert("✅ Restauration terminée ! Tous les utilisateurs et véhicules locaux ont été poussés sur Firebase.");
      onRefresh();
    } catch (e) {
      alert("❌ Échec de la restauration. Vérifiez vos règles Firebase.");
    } finally {
      setIsEmergencyAction(false);
    }
  };

  const handleDeleteUserAction = async (userId: string) => {
    if (confirm("🚨 ATTENTION : Suppression Définitive\n\nCette action est irréversible et supprimera le compte de la base de données Cloud.\n\nContinuer ?")) {
      await onDeleteUser(userId);
      setSelectedUser(null);
    }
  };

  const handleResetPasswordAction = async (user: User) => {
    const newPass = prompt("Saisissez le nouveau mot de passe temporaire pour ce client :", "NSP" + Math.floor(1000 + Math.random() * 9000));
    if (newPass) {
      await onUpdateUser({ ...user, password: newPass, passwordResetRequested: false });
      alert("✅ Mot de passe mis à jour sur le Cloud.\nVeuillez le communiquer au client.");
    }
  };

  const stats = useMemo(() => {
    const realUsers = allUsers.filter(u => u.role !== 'admin');
    const newUsers = realUsers.filter(u => {
      if (!u.createdAt) return false;
      const createdDate = new Date(u.createdAt);
      const now = new Date();
      return (now.getTime() - createdDate.getTime()) < (48 * 60 * 60 * 1000);
    });
    return { 
      totalUsers: realUsers.length, 
      newUsers: newUsers.length,
      totalCars: allCars.length,
      totalInvoices: allInvoices.length,
      totalRevenue: allInvoices.reduce((acc, inv) => acc + (inv.price || 0), 0)
    };
  }, [allUsers, allCars, allInvoices]);

  const getUserDetails = (userId: string) => {
    const cars = allCars.filter(c => c.ownerId === userId);
    const userInvoices = allInvoices.filter(i => cars.some(c => c.id === i.carId));
    return { cars, invoices: userInvoices };
  };

  const filteredUsers = allUsers
