    try {
      const q = query(collection(db, "users"), limit(1));
      await getDocs(q);
      return { success: true, message: "Connexion établie avec succès. Le Cloud est accessible." };
    } catch (e: any) {
      console.error("Diagnostic Error:", e);
      return { 
        success: false, 
        message: e.message || "Erreur inconnue", 
        code: e.code || "unknown" 
      };
    }
  }

