    if (!this.isConnected()) return;
    try {
        const cleaned = cleanData(user);
        await setDoc(doc(db, "users", user.id), { 
          ...cleaned, 
          lastSync: Timestamp.now(),
          platform: 'web-mobile'
        }, { merge: true });
    } catch (e: any) { 
        if(e.code === 'permission-denied') {
