    setIsEmergencyAction(true);
    try {
      const users = await cloud.fetchAllUsersRaw();
      if (users.length > 0) {
        db.users.saveAll(users);
        alert(`✅ SCAN RÉUSSI : ${users.length} utilisateurs rapatriés.`);
        onRefresh();
