          {!persistentImage && (
             <div className="grid grid-cols-2 gap-3 max-w-[300px] mx-auto">
                <div className="relative bg-nsp-primary text-white py-4 rounded-2xl flex flex-col items-center gap-2 shadow-xl active:scale-95 transition-all">
