                       <div className="bg-nsp-input p-5 rounded-3xl border border-white/5 text-center">
                          <p className="text-[8px] text-gray-500 font-black uppercase mb-1">Pression AV</p>
                          <p className="text-white font-black text-xl">{specs?.tirePressureFront || '2.3 bar'}</p>
                       </div>
                       <div className="bg-nsp-input p-5 rounded-3xl border border-white/5 text-center">
                          <p className="text-[8px] text-gray-500 font-black uppercase mb-1">Pression AR</p>
                          <p className="text-white font-black text-xl">{specs?.tirePressureRear || '2.1 bar'}</p>
                       </div>
                    </div>

                    {/* Rappels maintenance pneus */}
                    <div className="space-y-3">
                       <div className="bg-blue-900/10 border border-blue-500/20 p-4 rounded-2xl flex items-center gap-4">
                          <div className="w-10 h-10 bg-blue-500/20 rounded-xl flex items-center justify-center text-blue-400"><History size={20}/></div>
                          <div>
                             <p className="text-white font-bold text-xs">Permutation suggérée</p>
                             <p className="text-[9px] text-gray-500 font-medium">Recommandé tous les 10 000 km pour une usure uniforme.</p>
                          </div>
                       </div>
                       <div className="bg-blue-900/10 border border-blue-500/20 p-4 rounded-2xl flex items-center gap-4">
                          <div className="w-10 h-10 bg-blue-500/20 rounded-xl flex items-center justify-center text-blue-400"><Scale size={20}/></div>
                          <div>
                             <p className="text-white font-bold text-xs">Équilibrage & Parallélisme</p>
                             <p className="text-[9px] text-gray-500 font-medium">À vérifier si vous ressentez des vibrations ou si le véhicule tire.</p>
                          </div>
                       </div>
                    </div>
                 </section>
               )}

               {/* 1. SECTION PRECONISATIONS CONSTRUCTEUR (AUTRES RAPPORTS) */}
               {activeReport !== 'tires' && (
                 <section className="space-y-4">
                    <div className="flex items-center justify-between px-2">
                       <h3 className="text-[10px] text-gray-500 font-black uppercase tracking-[0.2em] flex items-center gap-2">
                          <ShieldCheck size={14} className="text-nsp-primary" /> Données Constructeur
