                            Aucune donnée technique détectée.<br/>Scannez vos factures pour extraire les pièces.
                         </p>
                      </div>
                    ) : (
                      technicalHistory.filter(item => {
                         if (activeReport === 'tires') return !!item.specs.tireDimensions;
                         if (activeReport === 'fluids') return !!item.specs.oilViscosity || (item.specs.filterRefs && item.specs.filterRefs.some(f => f.toLowerCase().includes('huile')));
                         if (activeReport === 'health') return (item.specs.mechanicalParts && item.specs.mechanicalParts.length > 0) || (item.specs.filterRefs && item.specs.filterRefs.length > 0) || !!item.specs.batteryRef;
                         return false;
                      }).map((item, idx) => (
                        <div key={idx} className="bg-nsp-card border border-nsp-border rounded-[2.5rem] overflow-hidden shadow-xl animate-fade-in" style={{animationDelay: `${idx * 0.1}s`}}>
                           <div className="bg-nsp-input px-6 py-4 flex justify-between items-center border-b border-white/5">
                              <div className="flex items-center gap-2 overflow-hidden">
                                 <Calendar size={12} className="text-nsp-primary" />
                                 <span className="text-white font-black text-[9px] uppercase tracking-tight truncate">{item.title}</span>
                              </div>
                              <span className="text-gray-500 font-bold text-[8px] whitespace-nowrap">{item.date} • {item.km.toLocaleString()} KM</span>
                           </div>
                           <div className="p-6 space-y-5">
                              {activeReport === 'tires' && item.specs.tireDimensions && (
                                <div className="flex items-start gap-4 bg-blue-500/5 p-4 rounded-2xl border border-blue-500/10">
                                   <div className="w-10 h-10 bg-blue-500/10 rounded-xl flex items-center justify-center text-blue-400 shrink-0"><Layers size={20}/></div>
                                   <div>
                                      <p className="text-[8px] text-blue-400 uppercase font-black tracking-widest mb-1">Dimensions Identifiées :</p>
                                      <p className="text-white font-black text-base">{item.specs.tireDimensions}</p>
                                   </div>
                                </div>
                              )}

                              {activeReport === 'fluids' && (
                                <div className="space-y-4">
                                   {item.specs.oilViscosity && (
                                      <div className="flex items-start gap-4 bg-yellow-500/5 p-4 rounded-2xl border border-yellow-500/10">
                                         <div className="w-10 h-10 bg-yellow-500/10 rounded-xl flex items-center justify-center text-yellow-500 shrink-0"><Droplet size={20}/></div>
                                         <div className="flex-1">
                                            <div className="flex justify-between items-start">
                                               <p className="text-[8px] text-yellow-500 uppercase font-black tracking-widest mb-1">Huile Relevée :</p>
                                               {item.specs.oilQuantity && <span className="text-[10px] text-white font-black bg-yellow-500/20 px-2 py-0.5 rounded-md">{item.specs.oilQuantity}</span>}
                                            </div>
                                            <p className="text-white font-black text-base">{item.specs.oilViscosity}</p>
                                         </div>
                                      </div>
                                   )}
                                </div>
                              )}

                              {activeReport === 'health' && (
                                <div className="space-y-5">
                                   {item.specs.mechanicalParts && item.specs.mechanicalParts.length > 0 && (
                                      <div className="space-y-3">
                                         <p className="text-[8px] text-nsp-primary font-black uppercase tracking-widest ml-1 flex items-center gap-2">
                                            <Wrench size={10} /> Organes Mécaniques :
                                         </p>
                                         <div className="flex flex-wrap gap-2">
                                            {item.specs.mechanicalParts.map((part, i) => (
                                              <span key={i} className="bg-white/5 px-3 py-1.5 rounded-xl text-white font-bold text-[10px] border border-white/10 shadow-sm">{part}</span>
                                            ))}
                                         </div>
                                      </div>
                                   )}
                                </div>
                              )}

                              <div className="flex items-center justify-between pt-4 border-t border-white/5">
                                 <div className="flex items-center gap-2">
                                    <div className="w-1.5 h-1.5 rounded-full bg-nsp-success"></div>
                                    <span className="text-[8px] text-gray-600 font-black uppercase tracking-widest">Origine Certifiée IA</span>
                                 </div>
                                 <button className="text-nsp-primary font-black text-[8px] uppercase tracking-widest flex items-center gap-1 hover:translate-x-1 transition-transform">
                                    Recommander ces pièces <ChevronRight size={10}/>
                                 </button>
                              </div>
                           </div>
                        </div>
                      ))
                    )}
                  </div>
               </section>
            </div>

            <button 
              onClick={() => setActiveReport(null)}
              className="w-full bg-nsp-primary text-white py-6 rounded-[2rem] font-black text-xs uppercase tracking-widest mt-12 shadow-xl active:scale-95 transition-all"
            >
               Fermer l'Analyse Technique
            </button>
          </div>
        </div>
      )}

      {/* VISIONNEUSE DE DOCUMENTS */}
      {viewingInvoice && (
        <div className="fixed inset-0 z-[2000] bg-black/98 flex flex-col pt-safe-top animate-fade-in overflow-hidden">
          <header className="p-6 flex justify-between items-center bg-black/50 border-b border-white/10 z-[2001]">
             <button onClick={() => setViewingInvoice(null)} className="p-3 bg-nsp-input rounded-xl text-white hover:bg-nsp-primary transition-colors"><X size={24}/></button>
             <div className="text-center">
                <h3 className="text-white font-black text-xs uppercase tracking-[0.2em] truncate max-w-[150px]">{viewingInvoice.title}</h3>
                <p className="text-[9px] text-nsp-primary font-black uppercase mt-1 tracking-widest">Coffre-fort Numérique</p>
             </div>
             <div className="flex gap-2">
               <button onClick={() => window.open(base64ToRealBlobUrl(viewingInvoice.imageUrl || '', isPDF(viewingInvoice.imageUrl) ? 'application/pdf' : 'image/jpeg'), '_blank')} className="p-3 bg-nsp-input rounded-xl text-white"><Maximize2 size={24}/></button>
             </div>
          </header>

          <div className="flex-1 flex flex-col items-center justify-center p-4">
            <div className="w-full h-full max-w-4xl bg-nsp-card rounded-[2.5rem] overflow-hidden border border-white/10 shadow-2xl relative">
              {isPDF(viewingInvoice.imageUrl) ? (
                <div className="w-full h-full bg-black overflow-hidden relative">
                   <iframe 
                      src={base64ToRealBlobUrl(viewingInvoice.imageUrl || '', 'application/pdf') + '#toolbar=0&navpanes=0'} 
                      className="w-full h-full border-0"
                      title="PDF Viewer"
                   />
                </div>
              ) : (
                <img src={safeBase64ToBlobUrl(viewingInvoice.imageUrl || '')} className="w-full h-full object-contain bg-[#050505]" alt="Facture" />
              )}
            </div>
          </div>

          <div className="p-8 bg-nsp-card/80 backdrop-blur-xl border-t border-white/10 space-y-6">
             <div className="grid grid-cols-2 gap-4">
                <div className="bg-nsp-input p-5 rounded-2xl border border-white/5">
                   <p className="text-[9px] text-gray-500 font-black uppercase mb-1">Montant Payé</p>
                   <p className="text-white font-black text-2xl tracking-tighter">{viewingInvoice.price} €</p>
                </div>
                <div className="bg-nsp-input p-5 rounded-2xl border border-white/5">
                   <p className="text-[9px] text-gray-500 font-black uppercase mb-1">Relevé KM</p>
                   <p className="text-white font-black text-2xl tracking-tighter">{viewingInvoice.km.toLocaleString()}</p>
                </div>
             </div>
             <div className="flex gap-4">
                <button onClick={handleDelete} className="flex-1 bg-red-600/10 text-red-500 font-black py-5 rounded-[2rem] text-[10px] uppercase border border-red-500/20 active:scale-95 transition-all flex items-center justify-center gap-2">
                  <Trash2 size={18} /> Supprimer
                </button>
                <button onClick={() => setViewingInvoice(null)} className="flex-1 bg-white/10 text-white font-black py-5 rounded-[2rem] text-[10px] uppercase border border-white/10 active:scale-95 transition-all"> Fermer </button>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

import { Invoice, Car } from '../types';

const BASE_RULES = {
  REVISION_KM: 20000,
  REVISION_MONTHS: 12,
  CHECK_FLUIDS_DAYS: 30,
  CHECK_TIRES_DAYS: 30,
  CHECK_OIL_DAYS: 90,
  CT_INTERVAL_YEARS: 2,
  TIRE_LIFESPAN_KM: 45000, 
  TIRE_AGE_YEARS: 5,
};

interface MaintenanceStatus {
  status: 'success' | 'warning' | 'critical' | 'neutral';
  message: string;
  nextDeadline: string;
  alerts: string[];
  pendingTasks: {id: string, label: string, severity: 'low' | 'high', basis?: string} [];
  upcomingDeadlines: {id: string, label: string, date: string, type: 'CT' | 'REVISION'} [];
  tireHealth?: {
    mileageSinceChange: number;
    wearPercentage: number;
    lastChangeDate?: string;
    recommendation: string;
  };
  lastCTInvoice?: Invoice;
  allDetectedParts: {name: string, date: string, km: number, ref?: string}[];
}

export const calculateMaintenanceStatus = (car: Car, invoices: Invoice[]): MaintenanceStatus => {
  const currentKm = invoices.length > 0 ? Math.max(...invoices.map(i => i.km)) : car.initialKm;
  const today = new Date();
  const alerts: string[] = [];
  const pendingTasks: {id: string, label: string, severity: 'low' | 'high', basis?: string}[] = [];
  const upcomingDeadlines: MaintenanceStatus['upcomingDeadlines'] = [];

  const lastDocDate = invoices.length > 0 
    ? new Date(Math.max(...invoices.map(i => new Date(i.date).getTime())))
    : new Date(car.firstRegistrationDate);

  const daysSinceLastCheck = Math.floor((today.getTime() - lastDocDate.getTime()) / (1000 * 60 * 60 * 24));

  const make = car.name.split(' ')[0].toUpperCase();
  let maintenanceIntervalKm = BASE_RULES.REVISION_KM;

  if (['RENAULT', 'PEUGEOT', 'CITROEN'].includes(make)) maintenanceIntervalKm = 20000;
  if (['BMW', 'AUDI', 'MERCEDES', 'PORSCHE'].includes(make)) maintenanceIntervalKm = 30000;
  if (car.fuelType === 'electrique') maintenanceIntervalKm = 30000;

  // 1. ANALYSE RÉVISION
  const lastRevision = invoices
    .filter(i => /révision|vidange|entretien|revision/i.test(i.title.toLowerCase()))
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())[0];

  if (lastRevision) {
    const revDate = new Date(lastRevision.date);
    const nextRevisionDate = new Date(revDate);
    nextRevisionDate.setFullYear(nextRevisionDate.getFullYear() + 1); 

    const kmSinceRevision = currentKm - lastRevision.km;
    const timeToNextRev = nextRevisionDate.getTime() - today.getTime();
    const daysToNextRev = Math.ceil(timeToNextRev / (1000 * 60 * 60 * 24));

    if (daysToNextRev <= 0 || kmSinceRevision >= maintenanceIntervalKm) {
      alerts.push("REVISION_DUE");
      pendingTasks.push({
        id: 'rev_due', 
        label: `Révision ${make} à effectuer`, 
        severity: 'high',
        basis: `Dernière faite le ${revDate.toLocaleDateString()} (${kmSinceRevision.toLocaleString()} km parcourus)`
      });
    } else if (daysToNextRev <= 30) {
      upcomingDeadlines.push({
        id: 'rev_soon',
        label: `Révision prévue dans ${daysToNextRev} jours`,
        date: nextRevisionDate.toLocaleDateString(),
        type: 'REVISION'
      });
    }
  }

  // 2. CONTRÔLE TECHNIQUE
  const lastCT = invoices
    .filter(i => /contr[oô]le technique|ct\b|visite technique/i.test(i.title.toLowerCase()))
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())[0];

  const nextCTDate = calculateNextCT(car.firstRegistrationDate, invoices);
  const diffTimeCT = nextCTDate.getTime() - today.getTime();
  const diffDaysCT = Math.ceil(diffTimeCT / (1000 * 60 * 60 * 24));

  if (diffDaysCT < 0) {
    alerts.push("CT_EXPIRED");
    pendingTasks.push({id: 'ct_crit', label: 'Contrôle Technique PÉRIMÉ', severity: 'high', basis: `Date limite : ${nextCTDate.toLocaleDateString()}`});
  } else if (diffDaysCT <= 30) {
    upcomingDeadlines.push({
      id: 'ct_soon',
      label: `Contrôle technique dans ${diffDaysCT} jours`,
      date: nextCTDate.toLocaleDateString(),
      type: 'CT'
    });
  }

  // 3. AGRÉGATION DES PIÈCES IA
  const allDetectedParts: {name: string, date: string, km: number, ref?: string}[] = [];
  invoices.forEach(inv => {
    if (inv.detectedSpecs) {
      if (inv.detectedSpecs.mechanicalParts) {
        inv.detectedSpecs.mechanicalParts.forEach(p => allDetectedParts.push({ name: p, date: inv.date, km: inv.km }));
      }
      if (inv.detectedSpecs.filterRefs) {
        inv.detectedSpecs.filterRefs.forEach(f => allDetectedParts.push({ name: 'Filtre', ref: f, date: inv.date, km: inv.km }));
      }
      if (inv.detectedSpecs.oilViscosity) {
        allDetectedParts.push({ name: 'Huile Moteur', ref: inv.detectedSpecs.oilViscosity, date: inv.date, km: inv.km });
      }
      if (inv.detectedSpecs.batteryRef) {
        allDetectedParts.push({ name: 'Batterie', ref: inv.detectedSpecs.batteryRef, date: inv.date, km: inv.km });
      }
    }
  });

  // 4. ANALYSE PNEUS
  const lastTireChange = invoices
    .filter(i => /pneu|pneumatique|tire|montage/i.test(i.title.toLowerCase()) && i.price > 100)
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())[0];

  let tireHealth = {
    mileageSinceChange: lastTireChange ? currentKm - lastTireChange.km : currentKm,
    wearPercentage: 0,
    lastChangeDate: lastTireChange?.date,
    recommendation: "Pneus en bon état apparent."
  };

  tireHealth.wearPercentage = Math.min(100, Math.round((tireHealth.mileageSinceChange / BASE_RULES.TIRE_LIFESPAN_KM) * 100));

  if (tireHealth.wearPercentage > 85) {
    tireHealth.recommendation = "Remplacement recommandé immédiatement.";
  }

  let status: MaintenanceStatus['status'] = 'success';
  let message = `Toutes les échéances de votre ${car.name} sont à jour.`;

  if (pendingTasks.some(t => t.severity === 'high')) {
    status = 'critical';
    message = `ALERTE : Des entretiens critiques sont en retard.`;
  } else if (pendingTasks.length > 0 || upcomingDeadlines.length > 0) {
    status = 'warning';
    message = `VIGILANCE : Des échéances approchent.`;
  }

  return { 
    status, 
    message, 
    nextDeadline: nextCTDate.toLocaleDateString(), 
    alerts,
    pendingTasks,
    upcomingDeadlines,
    tireHealth,
    lastCTInvoice: lastCT,
    allDetectedParts
  };
};

const calculateNextCT = (firstRegDateStr: string, invoices: Invoice[]): Date => {
  const firstReg = new Date(firstRegDateStr);
  const lastCT = invoices
    .filter(i => /contr[oô]le technique|ct\b|visite technique/i.test(i.title.toLowerCase()))
    .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime())[0];

  if (lastCT) {
    const next = new Date(lastCT.date);
    next.setFullYear(next.getFullYear() + 2);
    return next;
  }

  const firstCT = new Date(firstReg);
  firstCT.setFullYear(firstCT.getFullYear() + 4);
  const today = new Date();
  if (today > firstCT) {
      let estimatedNext = new Date(firstCT);
      while(estimatedNext < today) {
          estimatedNext.setFullYear(estimatedNext.getFullYear() + 2);
      }
      return estimatedNext;
  }
  return firstCT;
};

