                        <div className="w-full h-full flex items-center justify-center bg-gray-900">
                          {car.type === 'motorcycle' ? <Bike size={48} className="text-gray-800"/> : <CarIcon size={48} className="text-gray-800"/>}
                        </div>
                      )}
                      <div className="absolute inset-0 bg-gradient-to-t from-nsp-card via-transparent to-transparent"></div>
                      <div className="absolute top-5 left-5 bg-[#003399] text-white px-4 py-2 rounded-xl text-xs font-black tracking-widest shadow-2xl border border-white/10">
                        {car.plate}
                      </div>

                      {/* BADGE DE NOTIFICATION GARAGE */}
                      {alertCount > 0 && (
                        <div className="absolute top-5 right-5 z-20 bg-red-600 text-white w-7 h-7 rounded-full flex items-center justify-center text-[10px] font-black border-2 border-nsp-card shadow-lg animate-pulse">
                          {alertCount}
                        </div>
                      )}

                      <div className={`absolute top-5 ${alertCount > 0 ? 'right-14' : 'right-5'} bg-nsp-success text-white px-3.5 py-1.5 rounded-full text-[9px] font-black uppercase tracking-widest flex items-center gap-1.5 shadow-2xl backdrop-blur-md`}>
                         <ShieldCheck size={12} /> Certifié IA
                      </div>
                    </div>

                    <div className="p-7 pt-2 flex items-center justify-between">
                      <div>
                        <h3 className="text-2xl font-black text-white uppercase tracking-tighter">{car.name}</h3>
                        <div className="flex items-center gap-3 mt-1.5">
                          <span className="text-[10px] text-nsp-primary font-black uppercase tracking-widest">{car.fuelType}</span>
                          <span className="w-1.5 h-1.5 rounded-full bg-gray-800"></span>
                          <span className="text-[10px] text-gray-500 font-black uppercase tracking-widest">{car.initialKm.toLocaleString()} KM</span>
                        </div>
                      </div>
                      <div className="w-14 h-14 bg-nsp-primary rounded-[1.5rem] flex items-center justify-center text-white shadow-xl group-hover:scale-110 transition-transform">
                        <ChevronRight size={28} />
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      </div>

      {/* Article Modal */}
      {selectedArticle && (
        <div className="fixed inset-0 z-[300] bg-black flex flex-col pt-safe-top animate-fade-in overflow-hidden">
           <header className="p-6 flex justify-between items-center border-b border-white/10 bg-black/50 backdrop-blur-md">
              <button onClick={() => setSelectedArticle(null)} className="p-3 bg-nsp-input rounded-xl text-white"><X size={24}/></button>
              <h3 className="text-white font-black text-xs uppercase tracking-[0.2em]">{selectedArticle.category}</h3>
              <div className="w-12"></div>
           </header>
           <div className="flex-1 overflow-y-auto">
              <img src={selectedArticle.imageUrl} className="w-full aspect-video object-cover" alt={selectedArticle.title} />
              <div className="p-8 space-y-6">
                 <h2 className="text-4xl font-black text-white tracking-tighter leading-tight uppercase">{selectedArticle.title}</h2>
                 <div className="flex items-center gap-4 text-gray-500 text-[10px] font-black uppercase tracking-widest">
                    <span className="bg-nsp-input px-3 py-1 rounded-full text-nsp-primary">{selectedArticle.date}</span>
                    <span className="w-1.5 h-1.5 rounded-full bg-gray-800"></span>
                    <span>{selectedArticle.readTime} de lecture</span>
                 </div>
                 <p className="text-gray-300 text-lg font-medium leading-relaxed">{selectedArticle.summary}</p>
                 <div className="h-px bg-white/5 w-full"></div>
                 <p className="text-gray-400 leading-relaxed font-medium">{selectedArticle.content}</p>
                 <div className="bg-nsp-input p-6 rounded-[2rem] border border-white/5 mt-10">
                   <p className="text-gray-400 leading-relaxed italic text-sm">Information certifiée pour les membres AUTOBOOK. Restez informés des changements de réglementation pour éviter les amendes et optimiser la revente de votre véhicule.</p>
                 </div>
              </div>
           </div>
           <div className="p-6 pb-safe-bottom bg-black/80 backdrop-blur-md border-t border-white/10">
              <button onClick={() => setSelectedArticle(null)} className="w-full bg-nsp-primary text-white py-5 rounded-[2rem] font-black text-xs uppercase tracking-widest shadow-2xl active:scale-95 transition-all">
                J'ai compris
              </button>
           </div>
        </div>
      )}
    </div>
  );
};

import React, { useEffect, useState, useMemo } from 'react';
import { User, Car, Invoice, AIStatus, ManufacturerSpecs, TechnicalSpecs } from '../types';
import { 
  Plus, FileText, ArrowLeft, Sparkles, Gauge, Droplet, PhoneCall, X, 
  Wrench, AlertCircle, Share2, ShieldCheck, ChevronRight, Activity, Info, Eye, Download, Maximize2, Loader2, Trash2, Layers, Search, History, CheckCircle2, AlertTriangle, ListChecks, Calendar, Scale, Image as ImageIcon, BellRing, Clock, ShieldAlert, CircleAlert, Shield, SearchCode, PackageSearch, TrendingUp, TrendingDown, Wallet
} from 'lucide-react';
import { getPersonalizedMaintenance, safeBase64ToBlobUrl, base64ToRealBlobUrl } from '../services/geminiService';
import { calculateMaintenanceStatus } from '../services/mechanicRules';

interface DashboardScreenProps {
  user: User;
  car: Car;
  invoices: Invoice[];
  aiStatus: AIStatus;
  onBackToGarage: () => void;
  onAddInvoice: () => void;
  onSellCar: () => void;
  onBuyCar: () => void;
  onAssistance: () => void;
  onDeleteCar: () => void;
  onUpdateSpecs: (specs: TechnicalSpecs) => void;
  onUpdateCar: (car: Car) => void;
  onDeleteInvoice: (invoiceId: string) => void;
}

export const DashboardScreen: React.FC<DashboardScreenProps> = ({
  user, car, invoices, onBackToGarage, onAddInvoice, onAssistance, onDeleteInvoice, onSellCar
}) => {
  const [specs, setSpecs] = useState<ManufacturerSpecs | null>(null);
  const [isLoadingSpecs, setIsLoadingSpecs] = useState(false);
  const [activeReport, setActiveReport] = useState<'health' | 'tires' | 'fluids' | 'ct' | 'insurance' | 'parts' | null>(null);
  const [viewingInvoice, setViewingInvoice] = useState<Invoice | null>(null);
  const [viewingDoc, setViewingDoc] = useState<{title: string, url: string} | null>(null);

  const proactiveStatus = calculateMaintenanceStatus(car, invoices);
  const lastMileage = invoices.length > 0 ? Math.max(...invoices.map(i => i.km)) : car.initialKm;

  const alertCount = proactiveStatus.pendingTasks.length + proactiveStatus.upcomingDeadlines.length;

  useEffect(() => {
    const loadSpecs = async () => {
      setIsLoadingSpecs(true);
      try {
        const data = await getPersonalizedMaintenance(car, lastMileage);
        setSpecs(data);
      } finally {
        setIsLoadingSpecs(false);
      }
    };
    loadSpecs();
  }, [car.id, lastMileage]);

  const isPDF = (url?: string) => {
    if (!url) return false;
    return url.includes('application/pdf') || url.substring(0, 30).includes('JVBER');
  };

  const handleDelete = async () => {
    if (!viewingInvoice) return;
    if (confirm('Voulez-vous supprimer ce document ?')) {
      const idToDelete = viewingInvoice.id;
      setViewingInvoice(null);
      onDeleteInvoice(idToDelete);
    }
  };

  return (
    <div className="flex-1 flex flex-col bg-nsp-bg w-full pb-32 overflow-y-auto relative">
      <header className="bg-nsp-card/90 backdrop-blur-md sticky top-0 z-[100] border-b border-nsp-border px-5 py-5 pt-safe-top flex items-center gap-4">
        <button onClick={onBackToGarage} className="p-3 rounded-xl bg-nsp-input text-nsp-sub"><ArrowLeft size={20} /></button>
        <div className="flex-1 overflow-hidden">
           <h2 className="text-lg font-black text-white leading-none truncate uppercase tracking-tight">{car.name}</h2>
           <p className="text-[10px] text-nsp-primary font-black mt-1 tracking-widest">{car.plate}</p>
        </div>
        <button onClick={onSellCar} className="p-3 rounded-xl bg-nsp-input text-white border border-white/5 shadow-lg">
           <Share2 size={20} />
        </button>
      </header>

      <main className="p-6 space-y-8 animate-fade-in flex-1">

        {/* COMMAND CENTER : SCORE DE SANTÉ & COTE */}
        <div className="bg-nsp-card border border-nsp-border rounded-[3rem] p-8 shadow-2xl relative overflow-hidden group">
           <div className="absolute top-0 right-0 w-32 h-32 bg-nsp-primary/5 blur-[50px] rounded-full group-hover:bg-nsp-primary/10 transition-all"></div>

           <div className="flex items-center justify-between relative z-10">
              <div className="space-y-4">
                 <div className="flex items-center gap-2">
                    <Sparkles size={16} className="text-nsp-primary animate-pulse" />
                    <span className="text-[9px] text-gray-400 font-black uppercase tracking-[0.2em]">Diagnostic IA Pro</span>
                 </div>

                 <div>
                    <div className="flex items-end gap-1">
                       <span className={`text-6xl font-black tracking-tighter ${proactiveStatus.healthScore > 80 ? 'text-nsp-success' : proactiveStatus.healthScore > 50 ? 'text-orange-500' : 'text-nsp-primary'}`}>
                          {proactiveStatus.healthScore}
                       </span>
                       <span className="text-2xl font-black text-gray-700 mb-2">%</span>
                    </div>
                    <p className="text-[11px] font-black text-white uppercase mt-1 tracking-widest">Coefficient de santé</p>
                 </div>

                 <div className="flex items-center gap-3 pt-2">
                    <div className="bg-nsp-input/50 px-3 py-1.5 rounded-xl border border-white/5 flex items-center gap-2">
                       <TrendingUp size={12} className="text-nsp-success" />
                       <span className="text-[8px] text-white font-black uppercase tracking-widest">Moteur Opti</span>
                    </div>
                    <div className="bg-nsp-input/50 px-3 py-1.5 rounded-xl border border-white/5 flex items-center gap-2">
                       <History size={12} className="text-nsp-primary" />
                       <span className="text-[8px] text-white font-black uppercase tracking-widest">Historique OK</span>
                    </div>
                 </div>
              </div>

              <div className="text-right flex flex-col items-end">
                 <div className="w-20 h-20 rounded-full border-4 border-nsp-input flex items-center justify-center relative">
                    <svg className="w-full h-full transform -rotate-90">
                       <circle
                          cx="40"
                          cy="40"
                          r="34"
                          stroke="currentColor"
                          strokeWidth="8"
                          fill="transparent"
                          className="text-white/5"
                       />
                       <circle
                          cx="40"
                          cy="40"
                          r="34"
                          stroke="currentColor"
                          strokeWidth="8"
                          fill="transparent"
                          strokeDasharray={2 * Math.PI * 34}
                          strokeDashoffset={2 * Math.PI * 34 * (1 - proactiveStatus.healthScore / 100)}
                          className={proactiveStatus.healthScore > 80 ? 'text-nsp-success' : proactiveStatus.healthScore > 50 ? 'text-orange-500' : 'text-nsp-primary'}
                       />
                    </svg>
                    <div className="absolute inset-0 flex items-center justify-center">
                       <ShieldCheck size={28} className={proactiveStatus.healthScore > 80 ? 'text-nsp-success' : 'text-gray-700'} />
                    </div>
                 </div>
                 <div className="mt-6 bg-nsp-input/80 backdrop-blur-md p-4 rounded-2xl border border-white/10 shadow-xl w-36">
                    <div className="flex items-center gap-2 mb-1">
                       <Wallet size={12} className="text-nsp-primary" />
                       <span className="text-[8px] text-gray-500 font-black uppercase tracking-widest">Valeur Argus</span>
                    </div>
                    <p className="text-xl font-black text-white tracking-tighter">{proactiveStatus.estimatedValue.toLocaleString()} €</p>
                 </div>
              </div>
           </div>
        </div>

        {/* Grille de Navigation Quick-Access 2x3 */}
        <div className="grid grid-cols-3 gap-3">
            {[
              { id: 'health', icon: <Wrench size={20}/>, label: 'Santé', color: 'text-green-500 bg-green-500/10', badge: alertCount },
              { id: 'tires', icon: <Gauge size={20}/>, label: 'Pneus', color: 'text-blue-400 bg-blue-400/10' },
              { id: 'fluids', icon: <Droplet size={20}/>, label: 'Fluides', color: 'text-yellow-400 bg-yellow-400/10' },
              { id: 'ct', icon: <ShieldCheck size={20}/>, label: 'C.T', color: 'text-orange-400 bg-orange-400/10' },
              { id: 'insurance', icon: <Shield size={20}/>, label: 'Assurance', color: 'text-purple-400 bg-purple-400/10' },
              { id: 'parts', icon: <PackageSearch size={20}/>, label: 'Pièces', color: 'text-gray-200 bg-gray-200/10' },
            ].map(item => (
              <button key={item.id} onClick={() => setActiveReport(item.id as any)} className="bg-nsp-card border border-nsp-border rounded-2xl p-4 flex flex-col items-center text-center shadow-lg active:scale-95 transition-all relative">
                {item.badge ? (
                   <div className="absolute top-2 right-2 bg-red-600 text-white w-5 h-5 rounded-full flex items-center justify-center text-[8px] font-black border border-nsp-card animate-pulse z-10">
                     {item.badge}
                   </div>
                ) : null}
                <div className={`w-10 h-10 rounded-xl flex items-center justify-center mb-2 ${item.color}`}>{item.icon}</div>
                <span className="text-[8px] text-gray-400 font-black uppercase tracking-widest">{item.label}</span>
              </button>
            ))}
        </div>

        {/* Diagnostic Banner */}
        <div className={`relative overflow-hidden rounded-[2.5rem] border p-8 shadow-2xl ${proactiveStatus.status === 'critical' ? 'border-red-600 bg-red-900/10' : 'border-nsp-success/30 bg-green-900/10'}`}>
          <div className="flex items-start gap-4">
            <div className={`p-3 rounded-2xl bg-nsp-input ${proactiveStatus.status === 'critical' ? 'text-red-500' : 'text-nsp-primary'}`}><BellRing size={24} /></div>
            <div className="flex-1">
              <h3 className="font-black text-white text-[10px] uppercase tracking-[0.2em] mb-2">Conformité IA</h3>
              <p className="text-gray-200 text-sm font-bold leading-relaxed">{proactiveStatus.message}</p>
            </div>
          </div>
        </div>

        {/* SECTION DOSSIER OFFICIEL */}
        <div className="bg-nsp-card border border-nsp-border rounded-[2.5rem] p-6 space-y-5 shadow-xl">
